window.__D("text/torat-chaim/c014",{"p":[[2300540429,"מלך הגוים וכתי' יראו מה' כל הארץ<sup data-n=\"1234\">142</sup> כו', ואומר שירה כמו שרו של עשו<sup data-n=\"1235\">143</sup> כו' וכמ\"ש כל העמים תקעו כף<sup data-n=\"1236\">144</sup> כו' וכן הבו לה' משפחות עמים<sup data-n=\"1237\">145</sup> וכן הללו את ה'<sup data-n=\"1238\">146</sup> כל גוים כו' וכה\"ג רבות בכתובים. רק שעכ\"ז הרי הן בבחי' תערובות טו\"ר, ע\"כ יש בהן ג\"כ בחי' הפירוד לפרקים להגביה א\"ע בחוצפא וגסות לומר כחי ועוצם ידי<sup data-n=\"1239\">147</sup> כו' וכמו שר של מצרים שא' לי יאורי<sup data-n=\"1240\">148</sup> ואני עשיתני כו' ובשרו של אדום או' אם תגביהי כנשר<sup data-n=\"1241\">149</sup> כו'. ויש מהן למטה יותר שהן בבחי' פירוד ממש כמו סנחריב<sup data-n=\"1242\">150</sup> כו' וכן נבוכדנצר שעשה עצמו אלק[\"ה<sup data-n=\"1243\">151</sup> ] כו', וגם הן באים לבחי' ביטול והכנעה כמו נבוכדנצר שהודה ושיבח כו' וכמ\"ש כמצבייא עביד בחיל שמיא<sup data-n=\"1244\">152</sup> כו' וכן יתרו אמר עתה ידעתי<sup data-n=\"1245\">153</sup> כי גדול ה' כו', ויש מהן שיודעים<sup data-n=\"1246\">154</sup> את רבונם ומכוין<sup data-n=\"1247\">155</sup> למרוד בו (כאנשי דור הפלגה<sup data-n=\"1248\">156</sup> וכאנוש<sup data-n=\"1249\">157</sup> ונמרוד<sup data-n=\"1250\">158</sup> וכה\"ג) ועכ\"ז הכל יודעים את רבונם וקרו לי' אלקא דאלקיי'<sup data-n=\"1251\">159</sup> כו' רק שאין רצונם בעבודה וביטול הגסות לגמרי כו'. <span data-k=\"pg\">86</span> ּ ואמנם כ\"ז אינו רק מצד בחי' צמצום והסתר אור האלקי ביותר כו' עד שיכולים להיות בבחי' פירוד גמור, וראי' שאם נגלה אור האלקי עליהם מעט ביותר מכפי צמצום האחרון ביותר אז מתבטלים לגמרי כו' כמו במחנה סנחריב שהשמיע ה' את הוד קולו<sup data-n=\"1252\">160</sup> כו' וכן נ\"נ נתבטל ממציאותו וכרע וסגיד<sup data-n=\"1253\">161</sup> לאלהה שמייא כו' בכמה מעשיות בכתובים ובנביאים כו' וד\"ל.\n[ט] <b>והנה</b> ידוע שזה ההסתר אור האלקי היותר אחרון שמתצמצם במ\"ח צרופי' האחרונים דאלקים להיות מלך אלקים על גוים כו' הוא הנק' גלות השכינה בע\"ש דק\"נ שמשפיעים<sup data-n=\"1254\">162</sup> להם חיות והן בבחי' הפירוד ויש ודבר בפ\"ע ואין בהם בחי' הביטול לאלקי' ואע\"פ שיודעים את רבונם וקרו לי' אלקא דאלקיי' כו', וא\"כ יש להפל[י]א למה יומשך להם אור ושפע האלקי' כו'. הענין הוא דבאמת לפי כוונת המאציל בירידה [ל]צורך עלי' דוקא שהוא בחי' הביטול לאין שזהו ענין הקה\"מ<sup data-n=\"1255\">163</sup> הנ\"ל הרי לא יומשך גילוי אור האלקי רק בסט'",[["1234","142","<b>יראו מה' כל הארץ</b>: תהלים לג, ח."],["1235","143","<b>שירה כמו שרו של עשו</b>: חולין צא, ב."],["1236","144","<b>כל העמים תקעו כף</b>: תהלים מז, ב."],["1237","145","<b>הבו לה' משפחות עמים</b>: תהלים צו, ז. דהי\"א טז, כח."],["1238","146","<b>הללו את ה'</b>: תהלים קיז, א."],["1239","147","<b>כחי ועוצם ידי</b>: לשון הכתוב עקב ח, יז."],["1240","148","<b>שר. . לי יאורי</b>: יחזקאל כט, ג. ראה גם ש\"א מח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ערה. וש\"נ. שעה\"י קמו, ב ובהערה 41. לקמן פ' וארא סד, ג. בשלח רנ, א."],["1241","149","<b>אם תגביהי </b>[גח: תגביה]<b> כנשר</b>: עובדי' א, ד [ושם: תגביה — ראה לקמן פ' בשלח קפא, ג. ד. מאמרי אדה\"א בראשית ע' תסט. שמות ח\"ב ע' תקסג ובהנסמן בהנ\"ל]."],["1242","150","<b>סנחריב</b>: ראה מלכים-ב יח, יט ואילך. ישעי' לו, ד ואילך."],["1243","151","<b>נבוכדנצר. . אלק</b> [\"ה]: ראה דניאל פ\"ג."],["1244","152","<b>כמצבייא </b>[ח: וכמצבייא]<b> עביד בחיל שמיא</b>: דניאל ד, לב [ושם: וכמצבי' — ראה מאמרי אדה\"א במדבר ח\"א ע' לג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670193\" data-slug=\"torat-chaim\" data-id=\"2300670193\">תו\"ח וירא צט, ג</a> הערה 34]."],["1245","153","<b>עתה ידעתי</b>: יתרו יח, יא."],["1246","154","<b>שיודעים. . ומכוין למרוד בו</b>: ראה תו\"כ בחוקותי כו, יד (הובא ברש\"י ויל\"ש שם). רש\"י נח י, ט. לך יג, יג."],["1247","155","<b>ומכוין</b>: גח: ומתכווני'."],["1248","156","<b>כאנשי דור הפלגה</b>: ראה סנהדרין קט, א (רש\"י נח יא, א). ב\"ר פל\"ח, ז."],["1249","157","<b>וכאנוש</b>: ראה שאילתות פ' בראשית שאילתא א. רי\"ף וע\"י שבת קיח, ב. רמב\"ם ריש הל' ע\"ז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111153\" data-slug=\"likkutei-sichot\" data-id=\"1300111153\">לקו\"ש תשא (כרך יא) ע' 145</a> הערה 41. וראה גם ב\"ר פכ\"ג, ז."],["1250","158","<b>ונמרוד</b>: ראה בהנסמן בהערה 154."],["1251","159","<b>וקרו לי' אלקא דאלקיי'</b>: מנחות בסופה."],["1252","160","<b>במחנה סנחריב. . קולו</b>: ישעי' ל, ל. ראה סנהדרין צה, ב. סידור שער הלולב רסד, ג. שעה\"י קכה, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670445\" data-slug=\"torat-chaim\" data-id=\"2300670445\">תו\"ח בראשית כו, ד</a> הערה 44. לקמן פ' וארא עה, ג. בשלח קצג, ד. רכז, ג."],["1253","161","<b>נ\"נ. . וכרע וסגיד</b>: ראה דניאל ד, לא. מאמרי אדה\"א דברים ח\"ג ע' א'ס."],["1254","162","<b>שמשפיעים</b>: גח: שמשפיע."],["1255","163","<b>הקה\"מ</b>: גח: הקו המדה."]]],[2300540449,"דקדושה במלאכים ונשמות דג' עולמות בי\"ע והכל לפי המדה דוקא כנ\"ל, אבל בסט\"א בהיכלות הקליפות שמוסתר שם האור האלקי בתכלית כנ\"ל הרי ודאי לא יומשך ויגיע להם אליהם<sup data-n=\"1256\">164</sup> האור האלקי כלל וכמ\"ש וכבודי לאחר לא אתן<sup data-n=\"1257\">165</sup> כו' וכמ\"ש לא יגורך רע<sup data-n=\"1258\">166</sup> כו' ותועבת ה' כל גבה לב<sup data-n=\"1259\">167</sup> כו' (וכמו בנפש אדם רשע שפורק עומ\"ש לגמרי והוא עושה כל רע במרד אין פחד אלקי' בלבו כלל כו' ואינו עושה תשובה לעולם ודאי לא יאיר בו גילוי אור האלקי כלל כמ\"ש נר רשעים ידעך<sup data-n=\"1260\">168</sup> כו') וע\"כ נא' רם על כל גוים ה'<sup data-n=\"1261\">169</sup> כו' שהוא רם ומתנשא ומסתלק מהם כו' וכן אמר גאה גאה<sup data-n=\"1262\">170</sup> כו'. אך מה שנמשך ונשפע להם רוב שפע וברכה גשמיי' היינו כמ\"ש משלם לשונאיו<sup data-n=\"1263\">171</sup> אל פניו להאבידו כו' וכן אמר בפרוח רשעים<sup data-n=\"1264\">172</sup> כו' כדי להשמידם כו' וכן אמר אם רעב שונאך<sup data-n=\"1265\">173</sup> כו' שזהו מ\"ש אשר שלט האדם<sup data-n=\"1266\">174</sup> [באדם] כו' לרע לו כו', והוא לברר מהם כל חלק הטוב דקדושה שנפל בהן עי\"ז דוקא, וזהו כללות ענין גלות השכינה בע' שרים<sup data-n=\"1267\">175</sup> דק\"נ כו' כידוע שזהו כל ענין ד' גליות<sup data-n=\"1268\">176</sup> דד' מלכיות כו' וד\"ל. אך עכ\"ז יש להבין מאין יומשך להם אור ושפע רב הזה אחר שאור האלקי מוסתר בהם בתכלית דהיינו רק מחיצוניות [דחיצוני'] דכלים דמל' דעשי' כו', הענין הוא דבזמן הגלות נא' אלביש שמים קדרות<sup data-n=\"1269\">177</sup> ושק אשים כסותם כו', פי' שמים העליונים הוא בחי' מקיפים העליונים שהן למעלה מבחי' או\"פ בכלים דבחי' התיקון וכנ\"ל במשל העלם כחות הנפש בעצמיות שלה שהם כלולים כא' בלי התחלקות עדיין בכלים כו', משא\"כ כאשר תתפשט הנפש בכלי הגוף שכל אור מיוחד בכלי שלו כו'. וכך הוא למעלה בבחי' מקיפים דע\"ס דאצי'<sup data-n=\"1270\">178</sup> טרם שנמשכו בקו\"ח להתצמצם בכלים מכלים שונים כו' שאין שם בחי' כלים כלל וע\"כ שם הכל יכולים לקבל שפע גם מי שאינו ראוי כראוי כו', דהיינו גם היותר אחרונים בהשתלשלו' דקו\"ח שהן היכלות דק\"נ יכולים גם הם לקבל משם, דשם שוין היותר עליון עם היותר תחתון וכמ\"ש [קמי'] כחשיכה כאורה<sup data-n=\"1271\">179</sup> כו' וכן אמר קטן וגדול שם הוא<sup data-n=\"1272\">180</sup> כו', מאחר שבחי' המקיפים העליונים הוא",[["1256","164","<b>להם אליהם</b>: גח: עליהם."],["1257","165","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח. מח, יא."],["1258","166","<b>לא יגורך רע</b>: תהלים ה, ה."],["1259","167","<b>ותועבת ה' כל גבה לב</b>: משלי טז, ה."],["1260","168","<b>נר רשעים ידעך</b>: איוב כא, יז."],["1261","169","<b>רם על כל גוים ה'</b>: תהלים קיג, ד."],["1262","170","<b>גאה גאה</b>: בשלח טו, א."],["1263","171","<b>משלם לשונאיו</b>: ואתחנן ז, י [ושם: ומשלם — ראה לקמן פ' בשלח קלד, ד. מאמרי אדה\"א דברים ח\"ב ע' תסח]. ראה אמ\"ב שער הק\"ש עח, א. שער התפילין קמ, ב. וש\"נ."],["1264","172","<b>בפרוח רשעים</b>: תהלים צב, ח."],["1265","173","<b>אם רעב שונאך</b>: משלי כה, כא. ראה ביאוה\"ז חוקת צו, ב. שע\"ת קכח, א ובהערה 4."],["1266","174","<b>אשר שלט האדם</b>: קהלת ח, ט. ראה מאמרי אדה\"א ויקרא ח\"א ע' עג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670231\" data-slug=\"torat-chaim\" data-id=\"2300670231\">תו\"ח בראשית לג, ב</a> בהערה 11. לקמן סד, ד. קכז, א. רעג, א. שנב, ב. סידור קול יעקב (לר\"י קאפיל) ח\"א מצות מזוזה ע' קכז."],["1267","175","<b>בע' שרים</b>: נסמן לקמן לז, ג."],["1268","176","<b>ד' גליות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161091\" data-slug=\"likkutei-sichot\" data-id=\"1300161091\">לקו\"ש וארא (כרך טז) ע' 91</a>."],["1269","177","<b>אלביש שמים קדרות</b>: נסמן לעיל א, ד."],["1270","178","<b>דאצי'</b>: גח: דעצמות."],["1271","179","<b>[קמי'] כחשיכה כאורה</b>: כ\"ה גם בשה\"א כב, א. מאמרי אדה\"א נ\"ך ע' שסו. וש\"נ. קונטרסים ע' תל. ראה תהלים קלט, יב. עט\"ר ע' נא."],["1272","180","<b>קטן וגדול שם הוא</b>: איוב ג, יח."]]],[2300540469,"למעלה מעלה מכל ההשתלשלו' דקו\"ח ומקיף לכל כללות ההשתל' דקו\"ח מראשו לסופו כא' ממש בשוה כו'. משא\"כ בבחי' קו\"ח שנמשך לירד בבחי' ההשתלשלו' להיות או\"פ מוגבל <span data-k=\"pg\">מג</span> ּ בכלים כפי קו המדה בגילוי אור מקרוב ולא מרחוק בהעלם כו' שאז לא יגיע האור רק כפי הראוי לפ\"ע הגילוי בהשתלשלו' בד' עולמות אבי\"ע בכל עולם ועולם כפי המדה [דשם] בבחי' הביטול לאין כו', וע\"כ לא יבא האור רק בסט' דקדושה עכ\"פ ולא בסט\"א כלל שלא יוכל להיות שם גילוי אור האלקי כלל וכלל כנ\"ל. אבל בבחי' העיגולים ומקיפים שהן בבחי' ההעלם מרחוק בבחי' סובב הכללי שלא יומשך משם גילוי אור בכלי כלל, שם הכל יכולים לקבל שלא כפי המדה כלל, והכל שוין גם מי שאינו ראוי כראוי כו', וז\"ש אלביש שמים בחי' המקיפים קדרות וחושך להשפיע גם לע' שרים והוא לבוש שק כו', ונק' אהלי קדר<sup data-n=\"1273\">181</sup> כו' וד\"ל.\n<b>וזהו</b> להודיע כמה ארך אפים לפניו<sup data-n=\"1274\">182</sup> כו' כמו דורו של אנוש שהיו עובדים ע\"ז וניזוני' בחסדו<sup data-n=\"1275\">183</sup> כו', שמאריך אף לרשעים<sup data-n=\"1276\">184</sup> כמו לצדיקים כו', ע\"כ ביקש משה שלא תשרה שכינתו באוה\"ע<sup data-n=\"1277\">185</sup> כמ\"ש ונפלינו אני ועמך<sup data-n=\"1278\">186</sup> כו', משום ששם הכל יכולים לקבל כו' וראי' מבלעם שגם הוא אמר מחזה שדי יחזה<sup data-n=\"1279\">187</sup> כו'. ויובן זה עד\"מ גשמי בחבית מליאה שמוציאים ממנה דרך פי הברזא לכלים גדולים וקטנים אז ודאי לא ילך לאיבוד או בכלי מכוער כלל (רק השמרים ופסולת הנשאר באחרונה), אבל כשאין בה ברזא ועומדת בתהום ופתוחה מכל צד שנמשך ממנה מכל צד ודאי א\"ש<sup data-n=\"1280\">188</sup> ליציאת המים ממנה מכל צד שלא כפי המדה וגם בכלים מכוערים בלי דקדוק בזה כלל כו' והכל פונין לשם גם שאינו ראוי כראוי כו'. והנמשל מובן דקודם שירד האור בקו המדה הרי הכל יכולים לקבל כו', וזהו שגם דור אנוש היו ניזונין כו', וכך הוא בכל זמן גלות השכינה בע' שרים דכתיב אלביש שמים קדרות<sup data-n=\"1281\">189</sup> כו' (ולע\"ל יתגלה אור המקיף העליון דשמים ולא יולבש בקדרות (וכמו כיריעות שלמה<sup data-n=\"1282\">190</sup> כו') ו[י]הי' להיפך שגם הגוים יעבדו שכם א'<sup data-n=\"1283\">191</sup> כו' כי גם הע' שרים דק\"נ יקבלו בבחי' גילוי אור מקרוב כו' אשר לא היו יכולים לקבל כלל מבחי' או\"פ מצד בחי' עוצם הצמצום כנ\"ל. וכדוגמא זו הי' באברהם שנק' אב המון גוים<sup data-n=\"1284\">192</sup> שגייר לאוה\"ע<sup data-n=\"1285\">193</sup>, וע\"כ ביקש לו ישמעאל יחי' לפניך<sup data-n=\"1286\">194</sup>, שרצה שגם ישמעאל בחי' חסד דקליפה<sup data-n=\"1287\">195</sup> ממותרי החסד דקדושה יעלה למעלה כו' לפי שהי'",[["1273","181","<b>אהלי קדר</b>: תהלים קכ, ה. ראה גם מאמרי אדה\"א נ\"ך ע' שס."],["1274","182","<b>להודיע כמה ארך אפים לפניו</b>: אבות פ\"ה, מ\"ב. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קמו ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">תו\"א בשלח סא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370127\" data-slug=\"torah-or\" data-id=\"3901370127\">וישב כז, א</a>. לקמן פ' בשלח קלד, ד."],["1275","183","<b>דורו של אנוש. . בחסדו</b>: נסמן לעיל כד, ד."],["1276","184","<b>שמאריך אף לרשעים</b>: סנהדרין קיא, סע\"א. יומא סט, ב. ראה גם לקמן פ' בא קכג, ב. בשלח קלד, ד ואילך."],["1277","185","<b>ביקש משה. . שכינתו באוה\"ע</b>: ראה ברכות ז, א. לקמן פ' וארא סד, א. בא קכג, ב. בשלח קלה, א. מאמרי אדה\"א דברים ח\"ד ע' א'תיב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670128\" data-slug=\"torat-chaim\" data-id=\"2300670128\">תו\"ח לך צב, ג</a> הערה 30."],["1278","186","<b>ונפלינו אני ועמך</b>: תשא לג, טז."],["1279","187","<b>מחזה שדי יחזה</b>: בלק כד, ד."],["1280","188","<b>א\"ש</b>: גח: אין שיעור."],["1281","189","<b>קדרות</b>: גח: ליתא."],["1282","190","<b>כיריעות שלמה</b>: שה\"ש א, ה."],["1283","191","<b>הגוים יעבדו שכם א'</b>: צפני' ג, ט."],["1284","192","<b>אב המון גוים</b>: לך יז, ה."],["1285","193","<b>באברהם. . שגייר לאוה\"ע</b>: ראה ב\"ר פל\"ט, יד. מאמרי אדה\"א שמות ח\"ב ע' שמט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670170\" data-slug=\"torat-chaim\" data-id=\"2300670170\">תו\"ח בראשית לב, ב</a> ובהערה 20."],["1286","194","<b>לו ישמעאל יחי' לפניך</b>: לך יז, יח."],["1287","195","<b>ישמעאל בחי' חסד דקליפה</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תקלח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201102\" data-slug=\"likkutei-sichot\" data-id=\"1300201102\">לקו\"ש תולדות (כרך כ) ע' 102</a> בהערות. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670458\" data-slug=\"torat-chaim\" data-id=\"2300670458\">תו\"ח לך פח, ב</a> ובהערה 7."]]],[2300540487,"מעין עוה\"ב<sup data-n=\"1288\">196</sup> כו', ואמנם השיבו ה' כי זה יהי' לע\"ל [דוקא] לאחר בירור דעה\"ד כו' אבל עכשיו ביצחק דוקא יקרא לך זרע<sup data-n=\"1289\">197</sup> כו' (שזהו בחי' התיקון דיושר כו' וד\"ל).\n[י] <b>וזהו</b> כללות ענין גלות מצרים שהי' בבחי' ירידה וצמצום האור האלקי כ\"כ להתלבש בלבוש שק דק\"נ בשר של מצרים בבחי' גלות השכינה וכנ\"ל וכמ\"ש ליעקב אנכי ארד עמך מצרימה<sup data-n=\"1290\">198</sup> כו' שירד[ה] שכינה עמו כידוע עד שיכול למרוד והוא מ\"ש פרעה מי הוי'<sup data-n=\"1291\">199</sup> אשר אשמע בקולו כו', והענין הוא כנ\"ל דע\"י ריבוי הצמצומי' דאור בכלי<sup data-n=\"1292\">200</sup> במיעוט אחר מיעוט לא הי' מגיע שום שפע האלקי' לחיצוני' כלל רק שבזמן הגלות הן מקבלים מבחי' המקיפים העליונים ששם הכל יכולים לקבל כנ\"ל, וע\"כ אין הקליפות חפצים לקבל מבחי' הכלים דא\"פ דבחי' יושר דתיקון לפי שמשם לא יקבלו רק בחי' החיצוני' ביותר לפי שאין בהם בחי' הביטול ואינם רוצים בזה כי רצונם להיות בבחי' יש ודבר בפ\"ע דוקא (וכאנשי הפלגה שאמרו ונעשה לנו שם<sup data-n=\"1293\">201</sup> כו' כמ\"ש במ\"א), ע\"כ אינם חפצים בהמשכות גילוי האור [ה]אלקי בכלים מכלים שונים כו' שהוא בקרוב שאז לא יגיע השפע אלקי' רק בסט' דקדושה <span data-k=\"pg\">88</span> ּ כמלאכים ונשמות שהן בבחי' ביטול היש לאין כו' כנ\"ל, אלא הן חפצים יותר בבחי' הארת אור המקיפים העליונים דבחי' עיגולים שהוא בבחי' ההעלם מרחוק ה' נראה עליהם כענין רם על כל גוים כו' שמשם יוכלו גם הם לקבל יניקה ושפע מטעם הנ\"ל. וז\"ש פרעה מי הוי' אשר כו', פי' שם הוי' הוא בחי' גילוי אוא\"ס שבא באותיות הללו דשם הוי' מקרוב שהוא גילוי האור בכלי והן יו\"ד צמצום<sup data-n=\"1294\">202</sup> ה' התפשטות וי\"ו המשכה כו', ודרך כלל היינו ע\"ס דאצי' יו\"ד בחכ'<sup data-n=\"1295\">203</sup> ה' בבינה וי\"ו מדות כו', ובכללות יותר היינו ד' עולמות דאבי\"ע יו\"ד באצי'<sup data-n=\"1296\">204</sup> ה' בבריאה כו' עד ה' אחרונה בעשי', שבכ\"ז לא יוכלו החיצונים לקבל שום יניקה כלל וכמ\"ש וכבודי לאחר לא אתן כו'. וע\"כ שם הוי' מובדל ומרומם מע\"ש דק\"נ כמ\"ש רם על כל כו' לזה אמר פרעה מי הוי' כו' שלא ידע כלל משם הוי' זה, וגם אינו חפץ בגילוי אור אלקי מקרוב בבחי' כלי שצ\"ל בבחי' ביטול עצמי<sup data-n=\"1297\">205</sup> והוא בבחי' הפירוד כו' ורצונו לקבל מבחי' מקיפים עליונים שלמעלה מגילוי האור באותיות דשם הוי' דאבי\"ע כו' ע\"כ אמר מי הוי' אשר אשמע בקולו לא ידעתי כו'. אך זה הי' כל ענין האותות והמופתים במצרים שידע[ו] משם הוי' דוקא וכמ\"ש וידעו מצרים כי אני הוי'<sup data-n=\"1298\">206</sup> [דוקא] כו' וכמ\"ש במ\"א.",[["1288","196","<b>שהי' מעין עוה\"ב</b>: בבא בתרא טז, סע\"ב ואילך."],["1289","197","<b>ביצחק. . יקרא לך זרע</b>: וירא כא, יב."],["1290","198","<b>אנכי ארד עמך מצרימה</b>: ויגש מו, ד. ראה לקמן פ' וארא פו, ב."],["1291","199","<b>מי הוי'</b>: שמות ה, ב."],["1292","200","<b>דאור בכלי</b>: ג: דאבי\"ע כו'."],["1293","201","<b>ונעשה לנו שם</b>: נח יא, ד. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' עב ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370045\" data-slug=\"torah-or\" data-id=\"3901370045\">תו\"א נח יא, א</a>. מאמרי אדה\"א שמות ח\"א ע' כה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670078\" data-slug=\"torat-chaim\" data-id=\"2300670078\">תו\"ח נח סד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670545\" data-slug=\"torat-chaim\" data-id=\"2300670545\">עד, ב</a> ואילך."],["1294","202","<b>הוי'. . יו\"ד צמצום</b>: ראה אגה\"ת פ\"ד. לקמן פ' בשלח קנ, ב ואילך."],["1295","203","<b>הוי'. . יו\"ד בחכ'</b>: נסמן לעיל יב, ד."],["1296","204","<b>הוי'. . דאבי\"ע יו\"ד באצי'</b>: נסמן לעיל כד, ד."],["1297","205","<b>עצמי</b>: גח: עצמותו."],["1298","206","<b>וידעו מצרים כי אני הוי'</b>: ראה לעיל כ, ב. וש\"נ."]]],[2300540505,"<b>ואע\"פ</b> שלפי סדר ההשתלשלו' דאבי\"ע הרי אמר בע\"ח דמעמד ומצב היכלות הקליפות<sup data-n=\"1299\">207</sup> הוא בין האו\"פ דיושר ובין המקיפי' דעיגולי' אחוריהם אל המקיף ופניהם אל האו\"פ כו' לפי שא\"א להם להסתכל במקיפי' שלא יתבטלו ממציאותם לגמרי (כמו ענין התכלת שבציצית שמסמא עיני החיצונים<sup data-n=\"1300\">208</sup> כידוע) וזהו לכאו' היפך ענין הנ\"ל. הענין הוא דגם לפי סדר ההשתל' דקו\"ח באבי\"ע יש להם קצת יניקה מחיצוני' הכלים דמל' דעשי' להיותם לפרקים בבחי' ביטול והתכללות וקרו לי' אלקא דאלקייא כמו בלעם שאמר לא אוכל לעשות<sup data-n=\"1301\">209</sup> כו' וכנ\"נ כנ\"ל אע\"פ שאינו כביטול המלאכים כו', שהרי ע\"ש אומרי' שירה ואינם בעלי בחירה למרוד לגמרי לפי שהם כמו הגרזן [ביד החוצב]<sup data-n=\"1302\">210</sup> כו' וכמ\"ש הנה ה' רוכב על עב קל ובא מצרים<sup data-n=\"1303\">211</sup> כו', ע\"כ<sup data-n=\"1304\">212</sup> יש להם קצת יניקה מאלקות רק שהוא מעט מזעיר מצומצם מאד כו', לזאת גם שירד האור האלקי בריבוי הצמצומי' עד למטה מטה בעשי' דעשי' יש להם אחיזה שם מעט וע\"כ פניהם אל האו\"פ לקבל חיותם ויניקתם מחיצוני' הכלים דעשי' דעשי' כו' בקצה האחרון שלזה הם בבחי' יש ופירוד אבל אינו יכול למרוד לגמרי כנ\"ל וא\"א להם לקבל מן המקיף כלל מטעם הנ\"ל. אבל בזמן הגלות כתיב אלביש שמים קדרות אז הן מקבלים מבחי' המקיף דוקא, משום דנתלבש המקיף להיות בקדרות דלבוש שק להשפיע לע\"ש למטה, מפני שאז הוא באופן ששוה לפניו הכל שאינו ראוי כראוי מצד בחי' עוצם הרוממות ביותר (כמשי\"ת בסמוך בענין השינה) אז הן מקבלים בתוס' עילוי רב וגם כמו שהן בבחי' פירוד גמור בחוצפא והתנשאות לומר לי יאורי כו' וכמ\"ש מי הוי' לא ידעתי כו' להיותו מקבל<sup data-n=\"1305\">213</sup> משם הוי' [כו'].\n[יא] <b>והנה</b> להבין זה בתוס' ביאור יש להקדים [בשרש] ענין הגלות שנמשל בב' ענינים א' בבחי' שינה כמו עורה למה תישן ה' והב' בבחי' עיבור<sup data-n=\"1306\">214</sup> כמ\"ש אפי' בשעה שאתה מתמלא עליהם עברה כאשה עוברה יהי' כל צרכיהם<sup data-n=\"1307\">215</sup> לפניך וכמ\"ש כמו הרה תקריב ללדת<sup data-n=\"1308\">216</sup> כו', שהגאולה נק' לידה<sup data-n=\"1309\">217</sup> והגלות נק' עיבור כו', והכל ענין א' דהיינו עד\"מ בעיבור הולד בבטן אמו שמקופל ראשו בין ברכיו<sup data-n=\"1310\">218</sup> תלת כלילן גו תלת<sup data-n=\"1311\">219</sup> כו' שבחי' המוחין שלו בתכלית ההעלם בתוך העלם <span data-k=\"pg\">מד</span> ּ שהוא רק<sup data-n=\"1312\">220</sup> בבחי' נה\"י שבו בלבד כו' ([ו]אוכל מה שאמו אוכלת<sup data-n=\"1313\">221</sup> כו') כי נסתלק[ו] כל בחי' כחות הנפש בעצמות הנפש שכל ומדות שבו ולא נשאר בגילוי רק בחי' נו\"ה שנק' ברכים (ונחשב גם זה כירך",[["1299","207","<b>בע\"ח דמעמד. . הקליפות</b>: ראה לעיל כג, ד. וש\"נ."],["1300","208","<b>התכלת. . שמסמא עיני החיצונים</b>: ראה זהר שלח קסג, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670074\" data-slug=\"torat-chaim\" data-id=\"2300670074\">תו\"ח בראשית ל, ד</a> <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670492\" data-slug=\"torat-chaim\" data-id=\"2300670492\">הערה 24. נח נה, ג</a> הערה 40."],["1301","209","<b>לא אוכל לעשות</b>: בלק כב, יח. כד, יג [בדילוג]."],["1302","210","<b>כמו הגרזן [ביד החוצב]</b>: נסמן לעיל ב, א."],["1303","211","<b>הנה ה' רוכב. . מצרים</b>: ישעי' יט, א."],["1304","212","<b>ע\"כ</b>: גח: ועכ\"פ."],["1305","213","<b>להיותו מקבל</b>: גח: מפני שמקבל מלמעלה. ג: ניתוסף: היותו למעלה."],["1306","214","<b>הגלות. . שינה. . עיבור</b>: נסמן לעיל כה, א."],["1307","215","<b>אפי' בשעה. . צרכיהם</b>: לקמן פ' וארא סו, ג. בא קכח, ב. ועד\"ז תצוה שלג, ד (ושם הוגה מגוכי\"ק). ויקהל שצט, ב: במשנה. ראה ברכות כח, ב. כט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680080\" data-slug=\"torat-chaim\" data-id=\"2300680080\">תו\"ח וישב קצח, ד</a> ובהערה 80."],["1308","216","<b>כמו הרה תקריב ללדת</b>: ישעי' כו, יז."],["1309","217","<b>שהגאולה נק' לידה</b>: נסמן לעיל יז, ג."],["1310","218","<b>הולד. . ראשו בין ברכיו</b>: נדה ל, ב. ראה גם לקמן פ' בא קכח, א."],["1311","219","<b>תלת כלילן גו תלת</b>: נסמן לקמן לח, ד."],["1312","220","<b>רק</b>: גח: ליתא."],["1313","221","<b>([ו]אוכל מה שאמו אוכלת]</b>: נדה ל, ב."]]],[2300540523,"אמו<sup data-n=\"1314\">222</sup> בכיסוי והעלם גדול). אך בזה עצמו יש יתרון מעלה<sup data-n=\"1315\">223</sup> גדולה והוא מה שנתעלו הכחות הפנימי' דמוחין ומדות בעצמות הנפש שלמעלה מהגבלת הכלים דמוחין חו\"ב<sup data-n=\"1316\">224</sup> כו', וז\"ש מלמדין אותו כל התורה<sup data-n=\"1317\">225</sup> כו' וכתיב מי יתנני כירחי קדם<sup data-n=\"1318\">226</sup> כו' להיותו אז גדול בגדלות עליונה<sup data-n=\"1319\">227</sup> המקיפי' דיחידה שנכללו ונתעלו בה בחי' נר\"ן כו' שהוא נעלה הרבה מכל בחי' גדלות המוחין דזקן שקנה חכמה<sup data-n=\"1320\">228</sup> בהיותו בן ע'<sup data-n=\"1321\">229</sup> כו'. וכך הוא ענין הב' דבחי' שינה שמסתלקים כל המוחין ומדות למעלה בעצמות הנפש דבחי' יחידה כו' ולא נשאר בגילוי רק אור רושם בעלמא בלב ואברים כמו הנשימה בדפק שבלב כו' ותנועה חיצוני' שבאברים כו', ויש בזה יתרון מעלה למוחין ומדות כו' במה שנתעלו ונכללו במקורם מקור השכל ומקור המדות כו' שזהו בחי' עלי' גדולה לשכל ורצון ומדות הרבה יותר מכמו שהן בגילוי אור למטה בכלים המגבילים [ב]מוח ולב כו', הגם שיגדלו בגדלות ביותר אין להם ערך כלל כמו שהן כלולים בעצמות הנפש ממש שהן שם בלי צמצום והגבלה כלל ובעילוי היותר עליון כו' עד שנחשב ירידתם בכלים בבחי' שפלות וצמצום גדול בשינוי המהות לגמרי כו', וכנ\"ל בענין כחות הנפש כמו שהן כלולים בעצמות שנעלה הרבה מכמו שהן מתפשטים באברי הגוף כו' וד\"ל. והנמשל מב' ענינים אלו בחי' עיבור ובחי' שינה יובן למעלה בענין הגלות דודאי זהו בחי' הסתלקות אור ומוחין עליונים וגם מדות דאצי' וכמ\"ש בזהר דקוב\"ה בגלותא אסתלק לעילא<sup data-n=\"1322\">230</sup> כו'<sup data-n=\"1323\">231</sup> וכמ\"ש אסתיר פני ביום ההוא<sup data-n=\"1324\">232</sup> כו', פי' לעילא לעילא היינו עד\"מ בשינה שנכללים חב\"ד ומדות בעצמות הנפש ממש כך נתעלו כח חו\"ב ורצון ומדות העליונים בעצמות המאציל ממש שזהו בחי' עלי' גדולה שהן כלולים שם בבחי' א\"ס ממש למעלה מהגבלת הכלים כו' כמו קודם שנאצלו כו' ואין ערוך כלל לגילוי אור דכח\"ב וחג\"ת בכלים הנאצלי' הגם שיהי' בגדלות המוחין כו' לגבי עצם מקורן ושרשן כמו שהן כלולים בעצמות ממש וכנ\"ל במשל כחות הנפש הכלולים בעצמות כו', וזהו יתרון מעלה דבחי' שינה ועיבור הגם דתלת כלילן גו תלת כו' שהמוחין בהעלם גדול אבל העלם זה הוא עילוי גדול בעצמות ממש וד\"ל. וזהו שרש ענין הגלות שמצד עוצם הרוממות והעילוי דמוחין ומדות כו' בעצמות ממש יכולים הכל לקבל גם היותר תחתון כמו היותר עליון בשוה ממש, כי שוין שם הראש וסוף, להיותו נבדל בערך מכל ההשתל' דקו\"ח שבא בגילוי אור בכלי כו' כנ\"ל, ולכך גם קליפה דפרעה יוכל לקבל שם וע\"כ אמר מי הוי' כו' אשר אשמע בקולו כו', כי שרש פרעה",[["1314","222","<b>כירך אמו</b>: גיטין כג, ב."],["1315","223","<b>יש יתרון מעלה</b>: ראה גם לקמן לח, ד. וש\"נ."],["1316","224","<b>דמוחין חו\"ב</b>: גח: דמוח ולב."],["1317","225","<b>מלמדין אותו כל התורה</b>: נדה שם."],["1318","226","<b>מי יתנני כירחי קדם</b>: איוב כט, ב."],["1319","227","<b>עליונה</b>: גח: עצם."],["1320","228","<b>דזקן שקנה חכמה</b>: תו\"כ קדושים יט, לב. קידושין לב, ב. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשמ. לקמן פ' משפטים ש, ב."],["1321","229","<b>חכמה בהיותו בן ע'</b>: ראה סידור שער הלולב רסג, ב ואילך. מאמרי אדה\"א נ\"ך ע' תמג. וש\"נ. קונטרסים ע' רז."],["1322","230","<b>דקוב\"ה. . לעילא</b>: נסמן לקמן לט, א."],["1323","231","<b>כו'</b>: גח: לעילא."],["1324","232","<b>אסתיר פני ביום ההוא</b>: וילך לא, יח."]]],[2300540541,"מקבל בזמה\"ג מבחי' המקיף העליון ביותר שנכללו שם כל האורות שבהשתל' לפי שאינו בא בגדר השתלשלו' והתחלקות בכלי כלל להיותם כלולים בעצמות ממש, הרי אז גם הוא מקבל מלמעלה משם הוי' שהוא רק גילוי האותיות<sup data-n=\"1325\">233</sup> דחו\"ב ומדות בכלים כו', ולכך אמר לא ידעתי את הוי' שאינו מכיר ומשיג אותו כלל להיותו מקבל [מ]למעלה ממנו כו' לפי שבזמה\"ג שנק' שינה או עיבור כנ\"ל שאז נאמר אלביש שמים קדרות כו' כנ\"ל וד\"ל. <span data-k=\"pg\">90</span> ּ וזהו כל ענין הפירוד ומרד דע' שרים בזמן הגלות דוקא לפי שחפצ[י]ם יותר בהסתלקו' האורות במאציל עצמו שמשם יוכלו גם הם לקבל ברכה ושפע יניקה אף בהיותם בבחי' הפירוד ממש, משום דשם הוא למעלה מבחי' גילוי האור בכלי מקרוב כו' רק מרחוק כו' ואינם חפצים כלל בבחי' התיקון [ד]בחי' גילוי האור בכלים מכלים שונים ע\"י קו המדה כנ\"ל שאז לא יגיע אליהם שפע האלקי' כלל להיותם בבחי' הפירוד ממש כו' לא יוכלו לקבל רק מעט מזעיר בחיצוני' דחיצוני' לבד כנ\"ל (וזה הי' כוונת בונ[י] המגדל ראשו בשמים<sup data-n=\"1326\">234</sup> בבחי' [מקיפים] שיוכלו להיות בבחי' פירוד ויקבלו גם הם כו', והוא מ\"ש ונעשה לנו שם כו' דהיינו שם דמקיף שאינו בא בכלי כלל. וכן הנפילים אשר היו בארץ<sup data-n=\"1327\">235</sup> אשר מעולם אנשי השם, רצונם<sup data-n=\"1328\">236</sup> הם להיות בבחי' הפירוד [ו]לקבל שפע האלקי' מטעם הנ\"ל<sup data-n=\"1329\">237</sup> וד\"ל.\n[יב] <b>וזהו</b> ויאמר מלך מצרים למילדות העבריות כו', דהנה ידוע שהאותיות נק' בשם כלים<sup data-n=\"1330\">238</sup>, דפי' אות לשון אתא תרגום בא<sup data-n=\"1331\">239</sup> כמו אתא בקר<sup data-n=\"1332\">240</sup> כו' והוא מה שבא מבחי' ההעלם הפשוט לגילוי נק' אות (וגם נק' ע\"ש האות<sup data-n=\"1333\">241</sup> וציון וסימן ועד כו' כמו אות היא ביני<sup data-n=\"1334\">242</sup> כו' וכמו והיו לאותות<sup data-n=\"1335\">243</sup> כו' שזהו הוראה על דבר הפנימי ועצמי לזכרון אות ברית עולם כו' כציון המצויינת<sup data-n=\"1336\">244</sup> כו'). וכידוע שיש ג'<sup data-n=\"1337\">245</sup> מיני כלים, כלים פנימי' שהן בחי' כלי קיבול לפנימי' ועצמיות, וכלים חיצונים שהן רק המביאים את ההעלם לגילוי אור ושפע מעליון לתחתון כו', והן ב' מיני אותיות דמח' ודבור כו', דאותיות המח' שרשם במהות ועצמות הנפש שהן כ\"ב אותיות הקבועים בנפש<sup data-n=\"1338\">246</sup> ממש שנק' אותיות עצמיים ממש שבהן כל עצמיות הנפש כלולה שמורין על העצם ופנימי' כמו שהוא ממש ולא שהן בשביל המשכה ושפע, וכמו שם העצם וכצלם אדם שהוא בחי' צורה עצמיות כו' וזהו נק' כלים פנימי'. וכמו\"כ למעלה הוא ענין ובחי' האותיות עצמיי' שבעצמות ומהות א\"ס ב\"ה שאמר ע\"ז גליף גליפו בטה\"ע<sup data-n=\"1339\">247</sup>",[["1325","233","<b>האותיות</b>: גח: האורות."],["1326","234","<b>המגדל ראשו בשמים</b>: נח יא, ד."],["1327","235","<b>הנפילים אשר </b>[גח: ליתא]<b> היו בארץ</b>: בראשית ו, ד [בדילוג]."],["1328","236","<b>רצונם</b>: גח: כו' רצו גם."],["1329","237","<b>הנ\"ל</b>: כנצ\"ל: הנ\"ל)."],["1330","238","<b>שהאותיות נק' בשם כלים</b>: נסמן לעיל כה, ג."],["1331","239","<b>אתא תרגום בא</b>: ת\"א ות\"י לך יד, ה."],["1332","240","<b>שהאותיות. . אתא בקר</b>: נסמן לעיל שם."],["1333","241","<b>שהאותיות. . נק' ע\"ש האות</b>: ראה גם לקמן פ' בשלח קמח, א. מאמרי אדה\"א שמות ח\"ב ע' תרנח."],["1334","242","<b>אות היא ביני</b>: תשא לא, יג."],["1335","243","<b>והיו לאותות</b>: בראשית א, יד. ג: והי' לאות — לך יז, יא."],["1336","244","<b>כציון המצויינת</b>: נסמן בהערה 249."],["1337","245","<b>ג'</b>: גח: ב'."],["1338","246","<b>כ\"ב אותיות הקבועים בנפש</b>: ראה אגה\"ק ס\"ה. שעה\"י קלה, ב. ש\"א ו, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670371\" data-slug=\"torat-chaim\" data-id=\"2300670371\">תו\"ח נח נב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670420\" data-slug=\"torat-chaim\" data-id=\"2300670420\">נג, סע\"ג</a>. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ."],["1339","247","<b>גליף גליפו בטה\"ע</b>: זהר בראשית טו, א."]]],[2300540558,"חקיקת האותיות עצמיי' שבהן כלול כל בחי' הפנימי' ועצמיות דא\"ס ב\"ה שנק' שם העצם כו', ואותיות הללו שרשם של נש\"י שעלו במחשבה<sup data-n=\"1340\">248</sup> בבחי' אותיות עצמיי' (שנק' אות ע\"ש הפנימי' כמו אות הוא ביני כו' ולכך נק' ציון המצויינת<sup data-n=\"1341\">249</sup> כו'<sup data-n=\"1342\">250</sup>, כאותיות החותם החקוק בעצם כמ\"ש שימני כחותם על לבך<sup data-n=\"1343\">251</sup> כו' (כמ\"ש במ\"א בענין זאת חקת התורה<sup data-n=\"1344\">252</sup> כו' שמשם שרש אותיות התורה ג\"כ, וזהו ענין זה ספר תולדות אדם<sup data-n=\"1345\">253</sup> כללו' נש\"י שחקוקי' באותיות עצמיי' ונק' ישראל לי ראש<sup data-n=\"1346\">254</sup> והוא ג\"כ ענין ס\"ר אותיות דתושב\"כ<sup data-n=\"1347\">255</sup> שנק' ספר תולדות אדם דג' קשרים הן<sup data-n=\"1348\">256</sup> ישראל מתקשראין באורייתא ואורייתא כו' וכמ\"ש אז ראה ויספרה<sup data-n=\"1349\">257</sup> כו' שהן בג' דברים בספר<sup data-n=\"1350\">258</sup> וסופר וסיפור כו' הכינה באותיות המח' העצמיי' וגם חקרה באותיות הדבור ואח\"כ ויאמר לאדם שהן כנ\"י בתו\"מ בבחי' יושר דתיקון אורות בכלים דוקא הן יראת ה'<sup data-n=\"1351\">259</sup> היא חכמה כו'). ובחי' כלים החיצונים הן אותיות שבאים בשביל המשכה ושפע גילוי אור מן ההעלם לחבר העליון בתחתון כאותיות המח' שמגלים אור הרצון והשכל או המדות שבלב בכמה אופנים שונים ובלתי האותיות לא הי' נמשך גילוי האור מן ההעלם, וכמו אותיות הכתב ואותיות הדבור שהן בבחי' בליטה לחוץ כך יש גם במחשבה <span data-k=\"pg\">מה</span> ּ בחי' אותיות שמגלים אור השכל והרצון ותענוג שמגבילים אותו ומביאים להתחבר למטה כמו מאותיות הרצון לשכל ומן אותיות השכל בא למדות וכן אותיות המדות למחשבה להרהר במח' מה שחפץ וחושק בלבו כמו שאותיות המח' [י]בא לחשוק בלבו כנ\"ל. ודרך כלל הנה יובן עכ\"פ שהאותיות נק' כלים שבהן מתחלק האור הפשוט לחלקים מוגבלים, ע\"ד דוגמא הנה אור האהבה ותשוקה שבלב האדם הרי היא פשוטה ותקועה בלב בבחי' כח רוחני בלתי מתחלק לחלקים כלל וכלל ומיד שבא לכלל הרהור ומח' במוח שנק' הרהורי לבו שמהרהר וחושב לאות[ה] האהבה ותשוקה במחשבתו הרי נמשך אור אהבה ותשוקה זו הרוחני' הפשוטה ומתחלקת לחלקי' רבים ושונים דהיינו לכמה מיני המשכות רבות מחולקות בכמה מיני אופנים שונים שהן אופני צירופי אותיות המח' והרהור שמהרהר וחושב באהבה זו כו'. ונמצא שצירופי אותיות דמח' והרהור הללו נעשים בחי' כלים רבים להכיל אור האהבה הפשוטה שהיתה תחלה בכמה חל[ו]קי אופנים שונים כו' כמים הפשוטים שנמשכים בכלים רבים כו'. וזהו ענין הכלים שהוא ענין א' עם האותיות, וכללותם הוא רק ענין א' והוא מה שמביאים לאור הפשוט לחלק אותו לחלקים רבים ולהיות בכמה מיני המשכות",[["1340","248","<b>נש\"י שעלו במחשבה</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. ש\"א פ, א. מאמרי אדה\"א דברים ח\"ד ע' א'קע. וש\"נ. שה\"א לז, ב ובהערה 25. לקמן פ' בא צה, ג. בשלח קסב, א. פקודי תנד, ד."],["1341","249","<b>ציון המצויינת</b>: לשון הושענא אבן שתי' (ליום ב')."],["1342","250","<b>כו'</b>: אוצ\"ל: כו')."],["1343","251","<b>שימני כחותם על לבך</b>: שה\"ש ח, ו."],["1344","252","<b>זאת חוקת התורה</b>: חוקת יט, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תערב וע' תרפט ואילך. לקו\"ת חוקת נו, א. נט, ג. לקמן פ' בשלח קפג, ג."],["1345","253","<b>זה ספר תולדות אדם</b>: בראשית ה, א. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תיז. ח\"ג ע' תתקעט. נ\"ך ע' נה."],["1346","254","<b>ישראל לי ראש</b>: נסמן לעיל יח, ב."],["1347","255","<b>ס\"ר אותיות דתושב\"כ</b>: ראה ז\"ח שה\"ש עד, ד. מג\"ע אופן קפו. שה\"א צז, א הערה 14. לעיל ב, ד."],["1348","256","<b>דג' קשרים הן</b>: נסמן לעיל ב, ד."],["1349","257","<b>אז ראה ויספרה</b>: איוב כח, כז."],["1350","258","<b>בג' דברים בספר</b>: ראה ס\"י פ\"א, מ\"א."],["1351","259","<b>ויאמר לאדם. . הן יראת ה'</b>: איוב שם, כח."]]],[2300540575,"והתפשטות רבות [ו]בכמה מיני אופני' שונים כו', וזהו פי' אות לשון אתא בקר כו' שההעלם הפשוט בא לידי גילוי כנ\"ל (אך יש בזה ב' מדרגות כלים פנימי' וכלים חיצונים שהן ב' מיני אותיות הנ\"ל אותיות עצמיי' ואותיות שעל ידן יבא האור הפשוט לחלקים כו' ולהתחבר מעליון לתחתון כו' כנ\"ל, והוא ההפרש בין אותיות וכלים דתורה וישראל שעלו בפנימיות ועצמיות לאותיות וכלים חיצונים דרצון וחכמה דמע\"ב כו' וד\"ל). וכמו\"כ כאשר אור השכל הרוחני הפשוט בא להתחלקות אותיות המח' בצירופי' רבים ושונים או אור הרצון ותענוג הפשוט שמורכבי' גם הן באותיות כו'), והנה מוכרח לומר שיש כח עליון ביותר שהוא במקור המדות או השכל שהוא הכח המוציא את האותיות הנ\"ל שיוכל לבא מן ההעלם דאור האהבה ושכל הפשוט לידי גילוי והוא להיות המשכות והתהוות האותיות מן המדות דאוי\"ר שבלב או מן השכל הרוחני שבמוח יש ודאי איזה כח ומקור שבאמצעותו יתהוו האותיות הללו (והוא בחי' מקור<sup data-n=\"1352\">260</sup> השכל עצמו שמיד שיוציא לגילוי השכל מן העלם השכל יוציא עמו גם בחי' אותיות שלו שהוא מה שיבוא על ידו אור גילוי שכל זה בצירופי אותיות מח' ודבור, וכמו שאנו רואים שמיד שישכיל אדם איזה שכל מיד יולד בו בחי' האותיות והוא [מה] שיביאו לשכל זה בגילוי אותיות המח' ודבור נק' אותיות השכל, וכן בהרהורי לבו באוי\"ר שבלב יש בחי' מקור<sup data-n=\"1353\">261</sup> המוליד לבחי' אותיות המח' והרהור זה ממקור האהוי\"ר כו', דאל\"כ לא הי' אור פשוט ורוחני מתפשט ונמשך לחלקים דאותיות כלל, כי מצד עצם האור הרי הוא פשוט ורוחני בלתי מתחלק כלל וד\"ל.\n[יג] <b>וזהו</b> הנק' מיילדות העבריות, פי' עד\"מ הולד הנולד מבטן אמו שבא מן ההעלם לגילוי לחוץ הרי יש מיילדת שממשיכו ומביאו שיצא מן ההעלם לגילוי ונק' מיילדת, כך יובן ברוחניות בבחי' תולדות האותיות שהתהוות שלהם הוא מן ההעלם דאור הפשוט לגילוי כנ\"ל, זהו כולד הנולד כו' נק' עבריות (שהן נש\"י וכמו אותיות התורה שהן נולדים בבחי' גילוי אותיות מח' עליונה שנק' כלים פנימי' דייקא והן אותיות עצמיי' וכמ\"ש בזהר ע\"פ בעבר הנהר כו' ההוא נהר דאשתמודע<sup data-n=\"1354\">262</sup> כו' <span data-k=\"pg\">92</span> ּ שהוא למעלה הרבה מאותיות המח' דבינה שנק' אותיות וכלים חיצונים בשביל שפע והמשכה לבד כנ\"ל), והמיילדות את בחי' העבריות הללו הוא בחי' כח עליון המקשר ומביא וממשיך את אור הפשוט דשכל ומדות לבא לבחי' אותיות דמח' כנ\"ל, והוא בחי' הכח ומקור להתהוות הכלים שהן האותיות כו', והוא כח [ו]מקור המולידי' וממשיכים את התהוות האותיות שיבואו מן",[["1352","260","<b>בחי' מקור</b>: ג: כח ומקור."],["1353","261","<b>בחי' מקור</b>: גח: כח ומקור."],["1354","262","<b>בעבר הנהר. . דאשתמודע</b>: יהושע כד, ב. ראה זהר אמור צט, א. לקמן פ' משפטים רפד, ד."]]],[2300540591,"ההעלם לבחי' גילוי להיות כלי לאור בכמה אופנים שונים כנ\"ל וד\"ל. וע\"כ נק' מיילדות העבריות שמולידים לאותיות פנימי' שנק' עבריות להיות בבחי' התיקון ברבוי הכלים מכלים שונים לאורות שנק' אדם דיושר כו' והיינו ב' מיני אותיות דמח' ודבור (כמ\"ש למעלה בענין מי שם פה לאדם<sup data-n=\"1355\">263</sup> כו'). והנה ידוע בענין ג' קשרים ישראל ואוריי' כו' שהן בב' מדרגות דסתים וגליא והן כמו ב' מיני אותיות דמח' ודבור כו' והיינו כמו שנש\"י עלו במח' הקדומה בבחי' פנימי' ועצמיי' והן<sup data-n=\"1356\">264</sup> בחי' סתים וכן האותיות דתורה הקדומה כו' שמתקשרא' בעצמות א\"ס ב\"ה סדכ\"ס כו', וע\"כ גם בריא'<sup data-n=\"1357\">265</sup> אותן הנשמות בגופים למטה שהן ת\"ר אלף שעמדו במ\"ת<sup data-n=\"1358\">266</sup> כו' נעשים בחי' כלים פנימי' לקבלת אותיות התורה די' הדברות בבחי' גילוי אור בדבור בפה כו' גם לדורות הבאים עד ימוהמ\"ש, שכנ\"י הן בחי' כלים ממש בבחי' אדם לקבלת התומ\"צ שנק' מצות ה'<sup data-n=\"1359\">267</sup> ממש כמו שאו' אשר קדשנו<sup data-n=\"1360\">268</sup> במצותיו ממש כו' בבחי' ביטול פנימי מיש לאין כו', שאין זה הכח דכלים בזולתם כלל לפי שבאור פניך ממש נתת לנו<sup data-n=\"1361\">269</sup> תורת חיים כו' ואנו או' נותן התורה לשון הוה<sup data-n=\"1362\">270</sup> לפי שדבריו חיים וקיימים<sup data-n=\"1363\">271</sup> וכמאמר מה להלן באימה<sup data-n=\"1364\">272</sup> כו' (וזהו אז ראה ויספרה בספר וסופר כו' כנ\"ל).\n<b>והנה</b> מבואר למעלה דבזמן הגלות שנק' שינה או עיבור כו' שהוא הסתלקות האורות במקורא דכולא<sup data-n=\"1365\">273</sup> כו', אז יכולים גם החיצוני' לקבל יניקה מבחי' מקיף הכללי כו', וע\"כ אין החיצוני' חפצים כלל בבחי' גילוי האורות בכלים מכלים שונים כו' שזהו בחי' התיקון דאורות בכלים שהן האותיות דמח' ודבור כו', מפני שמבחי' כלים דאורות שיאיר אור האלקי בגילוי לא יוכלו לקבל רק התמצית וחיצוניות לבד כנ\"ל. ולזאת התחכם פרעה מלך מצרים שהוא בחי' כתר דקליפה<sup data-n=\"1366\">274</sup> פרעה העליון שבבחי' עורף ואחוריים דכתר עליון כו' למיילדות העבריות שהן אותם שרשים וכחות העליונים המיילדות את התהוות המשכות האותיות והכלים פנימי' שנק' עבריות כו' ואפי' ב\"ז<sup data-n=\"1367\">275</sup> הוא והמתן אותו כו' לפי שאינו רוצה שיבוא האור העליון בבחי' כלי כלל מטעם הנ\"ל וד\"ל (ומה גם שידע פרעה שישראל הן בחי' כלים פנימי' לקבלת תו\"מ למעלה שעי\"ז לא יגיע לו שום שפע ולא עוד אלא שיוציאו ממנו כל הטוב כו'). וזהו ויאמר מלך מצרים למילדות העבריות אשר שם האחת שפרה כו', והוא ב' מיני מיילדות לאותיות המח' ואותיות הדבור להיות בחי'<sup data-n=\"1368\">276</sup> מן ההעלם לגילוי כנ\"ל, וזהו שם האחת שפרה וארז\"ל שמשפרת את הולד, ושם השנית פועה<sup data-n=\"1369\">277</sup> שפועה (מדברת<sup data-n=\"1370\">278</sup> ) עם הולד כו',",[["1355","263","<b>למעלה בענין מי שם פה לאדם</b>: כט, א."],["1356","264","<b>והן</b>: גח: זהו."],["1357","265","<b>בריא'</b>: גח: בבוא."],["1358","266","<b>ת\"ר אלף שעמדו במ\"ת</b>: ראה שבת פח, א. לקמן פ' תרומה שיא, ד הערה 33."],["1359","267","<b>מצות ה'</b>: ויקרא ד, ב. יג. כב. ועוד."],["1360","268","<b>שאו' אשר קדשנו</b>: נוסח ברכת המצות."],["1361","269","<b>שבאור פניך. . נתת לנו</b>: תפלת העמידה."],["1362","270","<b>נותן התורה לשון הוה</b>: ראה של\"ה כה, א. קצב, א. לקמן פ' יתרו רנד, א. רנו, ב. רסג, א. מאמרי אדה\"א שמות ח\"א ע' קעה־ דברים ח\"ג ס\"ע תתכא ואילך־ הנחות תקע\"ז ע' שז ובהנסמן בהנ\"ל."],["1363","271","<b>שדבריו חיים וקיימים</b>: ברכת אמת ויציב."],["1364","272","<b>מה להלן באימה</b>: ברכות כב, א. ראה לקמן פ' יתרו רנג, ד."],["1365","273","<b>במקורא דכולא</b>: זהר בראשית לג, א."],["1366","274","<b>פרעה. . כתר דקליפה</b>: ראה זהר בא לד, א ובהגהת הרח\"ו שם. מאמרי אדה\"א דברים ח\"ב ע' תקמג. בראשית ע' תצא ובהנסמן בהנ\"ל. שה\"א מט, א. לעיל יט, ב. לקמן פ' וארא עא, ג. בא קי, ב. בשלח קלו, ג. תצוה שדמ, ג."],["1367","275","<b>ואפי' ב\"ז</b>: גח: (ו)אם בן."],["1368","276","<b>בחי'</b>: גח: באין."],["1369","277","<b>שפרה. . פועה</b>: סוטה יא, ב."],["1370","278","<b>פועה. . (מדברת)</b>: ראה רש\"י סוטה שם. ועה\"פ כאן (שמות א, טו)."]]],[2300540606,"וכללות הענין היינו ענין ב' ההי\"ן דשם הוי' ה\"א ראשונה דבחי' אותיות המח' דבינה זהו שם הא' שפרה כו', וה\"א אחרונה דש' הוי' בחי' אותיות הדבור זהו שם השנית פועה<sup data-n=\"1371\">279</sup> שמדברת עם הולד כו' והיינו בחי' בינה ומל' תרין נוק' כו' והיינו ב' מיני עלמין, עלמין דאתכסיין ועלמין דאתגליין<sup data-n=\"1372\">280</sup> וכמ\"ש ברוך ה' אלקי ישראל<sup data-n=\"1373\">281</sup> דוקא מן העולם ועד <span data-k=\"pg\">מו</span> ּ העולם דפי' עולם הוא בחי' כלי המגביל בו\"ק מעלה ומטה וד' סטרין, והן בב' מדרגות דאותיות הנק' כלים כנ\"ל שהן מגבילים לאורות<sup data-n=\"1374\">282</sup> דחכ' ומדות עליונות, והן ב' מיני אותיות [אותיות] דמח' בהעלם ואותיות דדבור בגילוי כו', והיינו ענין ב' [ה]מיילדות העבריות בכלל אשר שם הא' שפרה כו' וד\"ל.\n[יד] <b>ולהבין</b> ביאור הדברים, הנה להבין ענין עלמין סתימין הנ\"ל יש להקדים [ענין] מארז\"ל עתיד הקב\"ה להנחיל<sup data-n=\"1375\">283</sup> לכל צדיק וצדיק ש\"י עולמות כמ\"ש להנחיל אוהבי יש<sup data-n=\"1376\">285</sup>, ובזהר א' שהן ת' עלמין<sup data-n=\"1377\">284</sup> דכסופין<sup data-n=\"1378\">286</sup> שהן ענין ד' מאות שקל כסף<sup data-n=\"1379\">287</sup> עובר לסוחר כו'. וביאור זה הנה יש להקדים הידוע שיש ב' מיני עונג א' עונג המורגש והוא עונג המורכב, והב' עונג הפשוט שהוא עונג הנעלם, והענין הוא דבחכ' יש ג\"כ ב' מדרגות כאלה א' [החכמה] שבבחי' אין והעלם שנק' ח\"ס תעלומות חכ'<sup data-n=\"1380\">288</sup> ונק' שכל הנעלם מכל רעיון<sup data-n=\"1381\">289</sup> שכל מופלא<sup data-n=\"1382\">290</sup> בבחי' פלא דאין שבלתי יכול לבוא לגילוי אור מציאות שכל וחכמה עדיין כמ\"ש והחכ' מאין<sup data-n=\"1383\">291</sup> כמו שהיא בבחי' אין דכתר כו' ונק' כח מ\"ה דחכ'<sup data-n=\"1384\">292</sup> כמו מה פשפשת<sup data-n=\"1385\">293</sup> כו' כידוע, ושם נמשך בחי' העונג הנעלם שהוא עונג הפשוט בלתי מורכב בדבר מה [ו]בלתי מורגש כלל והוא הנק' עדן סתימאה<sup data-n=\"1386\">294</sup> דעין לא ראתה<sup data-n=\"1387\">295</sup> בהשגה [ד]חכ' רק בעוה\"ב יתגלה, והוא בחי' תענוג הפשוט שבעצמות א\"ס ב\"ה שנק' בחי' שעשועי' העצמי'<sup data-n=\"1388\">296</sup> שבח\"ע דתורה הקדומה וכמ\"ש ואהי' אצלו<sup data-n=\"1389\">297</sup> כו' שעשועים וכן אני תורתך שעשעתי<sup data-n=\"1390\">298</sup> כו' וכן לנשמות בעוה\"ב יקבלו משעשועים דפנימי' התורה וכמ\"ש ושעשועי את בנ\"א<sup data-n=\"1391\">299</sup> כו'. ואפס קצהו מאיר בכל שבת לנשמות בג\"ע כו' כידוע אך שהן באים לזה בבחי' עלי' וביטול במציאות ממש וכמ\"ש והי' מדי חדש ושבת<sup data-n=\"1392\">300</sup> כו' להשתחוות לפני ה' כו'. וכדוגמא זו הי' בכמה",[["1371","279","<b>ב' ההי\"ן. . שפרה. . פועה</b>: ראה גם לעיל כה, סע\"ג ואילך. וש\"נ."],["1372","280","<b>עלמין דאתכסיין. . דאתגליין</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה (א, סע\"א ואילך)."],["1373","281","<b>ברוך ה' אלקי ישראל</b>: ראה גם לעיל יח, ג. וש\"נ."],["1374","282","<b>מגבילים לאורות</b>: ח: מקבלים מאורות."],["1375","283","<b>עתיד הקב\"ה להנחיל</b>: עוקצי' בסופה."],["1376","285","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1377","284","<b>ש\"י עולמות. . ת' עלמין</b>: ראה אוה\"ת שמות (כרך ח) ע' ב'תתמה."],["1378","286","<b>ת' עלמין דכסופין</b>: נסמן לעיל כה, ד."],["1379","287","<b>ד' מאות שקל כסף</b>: ח\"ש כג, טז."],["1380","288","<b>תעלומות חכ'</b>: איוב יא, ו. ראה גם לקמן פ' וארא פב, א. יתרו רסז, א. משפטים ש, ג. תצוה שמא, ג. שמז, א. ויקהל תג, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670541\" data-slug=\"torat-chaim\" data-id=\"2300670541\">תו\"ח בראשית יז, ד</a> ובהערה 21. שעה\"י קט, ב. קכז, ב. ש\"א מב, ב."],["1381","289","<b>שכל הנעלם מכל רעיון</b>: נסמן לקמן מז, ג."],["1382","290","<b>שכל מופלא</b>: ראה הקדמת הראב\"ד לס\"י ”הנתיב הא'\". מאמרי אדה\"א בראשית ע' ח בהערה."],["1383","291","<b>והחכ' מאין </b>[ג: ניתוסף: תמצא]: איוב כח, יב. ראה גם לקמן לו, ב. נ, ד."],["1384","292","<b>כח מ\"ה דחכ'</b>: זהר (רע\"מ) צו כח, א. לד, א. ראה גם לקמן פ' בשלח קסב, ג. רי, א. תרומה שיב, ב. פקודי תמג, ב."],["1385","293","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["1386","294","<b>עדן סתימאה</b>: נסמן לעיל ה, ג."],["1387","295","<b>עדן. . דעין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["1388","296","<b>שעשועי' העצמי'</b>: נסמן לקמן פ' בא צב, ד."],["1389","297","<b>ואהי' אצלו</b>: משלי ח, ל."],["1390","298","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["1391","299","<b>ושעשועי את בנ\"א</b>: משלי ח, לא."],["1392","300","<b>והי' מדי חדש ושבת</b>: ישעי' סו, כג [ושם: בחדשו ומדי שבת — ראה לקמן פ' ויקהל שצה, ד [ושם הוגה מגוכתי\"ק]. מאמרי אדה\"א נ\"ך ע' שכ —. . אמר ה']."]]],[2300540620,"נשמות שנסתלקו מעוצם הפלא' ערך העונג האלקי העליון המופלא כזה שזהו כמו ענין מיתת נשיקין ע\"פ ה' כמשה<sup data-n=\"1393\">301</sup> והיינו כמו ג' סבות שנסתלקו<sup data-n=\"1394\">302</sup> באדר\"ז<sup data-n=\"1395\">303</sup> וכה\"ג וד\"ל. והב' בחי' חכמה שמאין תמצא בבחי' יש להיות בגילוי אור עכ\"פ עד שיבא לכלל השגה ותפיסא בבינה שזהו מאין ליש ממש כידוע, וזהו ענין נהר שיוצא מעדן<sup data-n=\"1396\">304</sup> סתימאה הנ\"ל שהוא גילוי אור עונג המורגש בשכל והשגה שנק' עונג המורכב שמורכב בדבר מה והוא באופן ההשגה אלקי' בטוב טעם כמ\"ש טעמו וראו<sup data-n=\"1397\">305</sup> כו', עד\"מ אדם שמשיג בשכלו דבר חכמה יתענג בה במורגש דוקא והוא שטועם טעם ועונג גדול, וכל שמשיג[ו] יותר, יותר [י]רגיש העונג כו' (אבל בשכל המופלא מן ההשגה לגמרי לא יתענג כלל במורגש מאחר שאינו משיגו ותופסו ממה יתפעל בתענוג, אע\"פ שהוא חכ' ושכל נפלא ביותר, אין התפעלות העונג באה במורגש כלל ממנו רק בבחי' ההעלם ומקיף לבד כמו שבתענוג בהעלם בחכמה הנעלמה שבבחי' אין כנ\"ל). וזהו ענין התענוג האלקי הבא במורגש לנשמות בג\"ע שנהנין מזיו השכינה שהוא עונג המורכב בתוך כלי השגתם האלקי' בכאו\"א לפי ערכו כו', שבודאי אין ערוך כלל וכלל לעונג אלקי זה הבא בצמצום כלי ההשגה לגבי עצם אור התענוג הפשוט שבח\"ע שנק' ח\"ס שבבחי' אין האלקי ממש הנ\"ל.\n<b>אך</b> א\"כ יש להבין דהלא ידוע דעצמות א\"ס ב\"ה נק' סדכ\"ס<sup data-n=\"1398\">306</sup> דלית מח' תפיסא בי' כלל<sup data-n=\"1399\">307</sup> אפי' מח' סתימאה<sup data-n=\"1400\">308</sup>, ומאחר שאינו נתפס בשום <span data-k=\"pg\">94</span> ּ השגה ושכל כלל איך יוכלו להתענג על ה' במורגש כנשמות שנהנין מזיו כו', שהרי אין התפעלות התענוג במורגש בא רק בהשגה ותפיסא דוקא כנ\"ל וכתיב אז תתענג על ה'<sup data-n=\"1401\">309</sup> כו' שמשמעו שהתענוג והדביקות הוא בעצמות א\"ס ממש וכמ\"ש לדבקה בו<sup data-n=\"1402\">310</sup> ממש ואין דביקות אמיתית רק ע\"י התפעלות הנפש בתענוג מורגש בעונג האלקי עד כלותה כו' כמו נכספה וגם כלתה נפשי<sup data-n=\"1403\">311</sup> כו' [ו]בתענוג שבהשג' א\"א להשיג ולידבק בזה לעצמות א\"ס דלית מח' תפיסא בי' כלל. אלא צריך לומר שכדי שיוכלו הנשמות לדבקה בו ית' ממש שזהו דוקא בתענוג הפשוט ועצמי שאינו מורכב בהשגה כלל כנ\"ל, הוצרך להיות בחי' ירידה והמשכה מעצמות התענוג הפשוט העליון שנק'",[["1393","301","<b>מיתת נשיקין. . כמשה</b>: ראה בבא בתרא יז, א."],["1394","302","<b>ג' סבות שנסתלקו</b>: זהר (אד\"ר) נשא קמד, א-ב."],["1395","303","<b>באדר\"ז</b>: כ\"ה גם במאמרי אדה\"א ויקרא ח\"א ע' מה בהערה. ח\"ב ע' תצג. אבל בשע\"ת צד, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670390\" data-slug=\"torat-chaim\" data-id=\"2300670390\">תו\"ח בראשית מ, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680362\" data-slug=\"torat-chaim\" data-id=\"2300680362\">וישלח קצד, ב</a>. מאמרי אדה\"א דברים ח\"ג ע' א'קלא. נ\"ך ע' תסו וע' תצא. לקמן פ' ויקהל תיד, א ”באד\"ר\"."],["1396","304","<b>נהר שיוצא מעדן</b>: בראשית ב, י."],["1397","305","<b>טעמו וראו</b>: תהלים לד, ט."],["1398","306","<b>סדכ\"ס</b>: זהר בהקדמה ב, א. ועוד."],["1399","307","<b>דלית מח' תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["1400","308","<b>אפי' מח' סתימאה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680128\" data-slug=\"torat-chaim\" data-id=\"2300680128\">תו\"ח וישב קצט, ג</a>."],["1401","309","<b>אז תתענג על ה'</b>: נסמן בהערה 314."],["1402","310","<b>לדבקה בו</b>: עקב יא, כב־ נצבים ל, כ־ יהושע כב, ה [ושם: ולדבקה — ראה לקמן עז, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקפא. שע\"ת פ, ד. ש\"א לז, ב. מאמרי אדה\"א קונטרסים ע' תלו]."],["1403","311","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."]]],[2300540634,"שעשועים העצמי' כו' לבא בבחי' התגלות דוקא בהשגה ותפיסא לנשמות שיוכלו להתענג בה' [ב]תענוג מורגש כמו שיתענגו בשכל והשגה שנק' עונג מורגש ממש, והרי מבחי' העלם עצמות התענוג וחכ' דבחי' אין ממש הוא עצמו שירד ובא למטה בהתלבשות בלבוש דשכל והשגה דוקא עד שיהנו ויתענגו כמו בעונג מורגש (כמו ישבעו ויתענגו מטובך<sup data-n=\"1404\">312</sup> כו' שבשבת יורד עונג הנעלם ובא בהתלבשות בבחי' עונג מורגש וכמ\"ש וקראת לשבת ענג<sup data-n=\"1405\">313</sup> וכמו עונג המאכלי' דשבת, וז\"ש אז תתענג על ה' צלותא דשבת<sup data-n=\"1406\">314</sup> שבזה יתרון מעלתו מכל עונג האלקי שמורכב בהשגה במה שהוא על ה', דהיינו שעונג הפשוט הוא שנעשה כמו מורגש ממש, מפני שבכל שבת הוא מעין יום שכולו שבת<sup data-n=\"1407\">315</sup> שהוא העוה\"ב שנא' בו להנחיל אוהבי יש, פי' בחי' עצמות העונג הפשוט שנק' עדן העליון כנ\"ל בא בהתלבשות להיות בבחי' עונג מורגש שנק' יש ממש, וכך הוא גם בג\"ע בכל שבת שנהנים ומרגישי' בעונג העליון הנעלם הנ\"ל וד\"ל) (וכמ\"ש במ\"א בענין הסעודה לצדיקים לע\"ל בלויתן ושור הבר<sup data-n=\"1408\">316</sup> כו' וכן ענין לחם פנג<sup data-n=\"1409\">317</sup> וכלחם הפנים<sup data-n=\"1410\">318</sup> ומזון המן שבא בהגשמה ממש כו', וכך יהי' בעוה\"ב שגופי' גשמיי' יקבלו חיותם בהגשמה מחיי עולם כמ\"ש ונחי' לפניו<sup data-n=\"1411\">319</sup> ממש, וז\"ש להנחיל אוהבי יש מטעם הנ\"ל).\n[טו] <b>וזהו</b> ענין מארז\"ל שיהי' לכל צדיק ש\"י עולמות כו', דהנה בחי' ירידה זו שיורד עונג העליון הנעלם לבא בלבוש השגה להיות כמו עונג מורגש ממש כנ\"ל זהו הנק' עולם, דהיינו כמו עולם בגשמיות שכלול מו\"ק מעלה ומטה מזרח ומערב צפון ודרום כו' כך הוא בחי' ההמשכה שנמשך מבחי' העונג העליון הנעלם הנ\"ל להיות תענוג לנשמות בבחי' יש מורגש הרי זה בא בבחי' גבול ומדה לפי ערך כלי השגתם, וע\"כ יורד ומתצמצם עליהם בבחי' מקיף כרקיע הנטוי על ראשי החיות כעין הקרח<sup data-n=\"1412\">320</sup> כו' והוא הרקיע שבג\"ע כו' וכידוע בענין אור מים רקיע<sup data-n=\"1413\">321</sup> כו', ומתפשט בהשגתם לקבל העונג במורגש כנ\"ל שהוא בבחי' הגבלה ממש לכל נשמת צדיק כפום שיעורא דילי'<sup data-n=\"1414\">322</sup> כן הוא מתענג על ה' ממש כו' ומקיף אותו כהיכל ודירה כו' והוא הנק' עולם שהוא כמו עולם כלול מו\"ק כו'. ויש באופן זה ש\"י עולמות שהן בחי' ש\"י מדריגות מיני המשכות עונג עליון הבא בבחי' עולם כו' (וטעם מספר ש\"י דוקא ידוע שזהו נגד ב' מדרגות דחו\"ב קנה חכ' קנה בינה<sup data-n=\"1415\">323</sup> כו' ב\"פ קנה גימט' ש\"י<sup data-n=\"1416\">324</sup>",[["1404","312","<b>ישבעו ויתענגו מטובך</b>: תפלת העמידה לשבת (ישמחו במלכותך) ראה גם לקמן פ' ויקהל תכב, א."],["1405","313","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["1406","314","<b>אז תתענג. . צלותא דשבת</b>: ישעי' נח, יד. ראה גם מאמרי אדה\"א שמות ח\"א ע' קצא ואילך. ובהנסמן שם בע' קפה."],["1407","315","<b>שבכל שבת. . שכולו שבת</b>: סוף תמיד. ראה מכילתא תשא לא, יג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730144\" data-slug=\"likkutei-sichot\" data-id=\"1301730144\">לקו\"ש בשלח (כרך לו) ע' 75</a> הערה 57. מאמרי אדה\"א נ\"ך ע' תעא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670219\" data-slug=\"torat-chaim\" data-id=\"2300670219\">תו\"ח נח סא, ד</a> ובהערה 35."],["1408","316","<b>הסעודה. . ושור הבר</b>: נסמן לעיל ו, ד."],["1409","317","<b>לחם פנג</b>: ראה גם לעיל כג, ב. וש\"נ."],["1410","318","<b>וכלחם הפנים</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' קצא ובהנסמן שם."],["1411","319","<b>ונחי' לפניו</b>: הושע ו, ב."],["1412","320","<b>כרקיע. . כעין הקרח</b>: יחזקאל א, כב."],["1413","321","<b>אור מים רקיע</b>: ראה זהר תרומה קלו, ב. קסז, א. ע\"ח (שער המלכים) שי\"א, פ\"ו. סידור שחרית ע, א. מאמרי אדה\"א שמות ח\"ב ע' שצד ואילך. וש\"נ. שעה\"י קמ, א. ש\"א מז, א. לקמן לו, א."],["1414","322","<b>כפום שיעורא דילי'</b>: ראה זהר וירא קג, ריש ע\"ב."],["1415","323","<b>קנה חכ' קנה בינה</b>: משלי ד, ה."],["1416","324","<b>ב\"פ קנה גימט' ש\"י</b>: ראה פע\"ח (שער תפלות ר\"ה) שכ\"ה, פ\"ג. הנסמן במאמרי אדה\"ז תקע\"א ע' עה. מאמרי אדה\"א דברים ח\"א ע' טז. ח\"ג ע' תשצ."]]],[2300540647,"והוא מ\"ש להנחיל אוהבי יש כו', וב\"פ ש\"י גימ' תר\"ך<sup data-n=\"1417\">325</sup> והוא בחי' המקיף דכתר שכולל ב' מזלות דונוצר ונקה כו'). ואמנם מה שנק' בשם יש היינו כמו שידוע שהעוה\"ב נק' יש שהוא עיקר קבלת השכר מעונג הפשוט שבעצמות א\"ס ב\"ה לנשמות בגופים שאינו בא רק מן המעשה דמצות<sup data-n=\"1418\">*326</sup> בבחי' כלי ממש דשכר מצוה <span data-k=\"pg\">מז</span> ּ מצוה<sup data-n=\"1419\">326</sup> וכמ\"ש כל ישראל יש להם כו' שנא' ועמך כולם צדיקים<sup data-n=\"1420\">327</sup>, וע\"כ [ל]כל צדיק כפי הבירורים שלו במצות מעשיות כל ימיו כך ניתן לו מספר עולמות מעולם התענוג העליון והוא שנק' עלמין דכסופין כו', ולמעלה מעלה מן האצי' נקראו עלמין דכסופין שבבחי' פנימי' ע\"י כו' שהן בבחי' מקיפי' העליונים דפנימי' הכתר כו' שלמעלה מעלה עדיין מהיות גם מקור להמשכות עונג בחו\"ב ומדות דאצי' ומכ\"ש שלא יוכלו לבא בהגבלת תענוג לנשמות בג\"ע כו'. אך שעכ\"ז יורדים למטה ומתלבשים להיות בבחי' עולמות לנשמות הצדיקים שנק' יש גמור וזהו כמו העוה\"ב שהוא בחי' המשכות העונג העצמו' לנשמות בבחי' יש גמור כמ\"ש להנחיל אוהבי יש כו' וכמ\"ש ויהי נועם ה' עלינו<sup data-n=\"1421\">328</sup> ממש וכמ\"ש דוד אחת שאלתי שבתי בבית ה' כו' לחזות בנועם ה' ולבקר בהיכלו<sup data-n=\"1422\">329</sup> כו', פי' לחזות ממש בראי' והשגה ממש שזה אינו אלא כאשר נמשך ובא בבחי' עולם והיכל כו' כמ\"ש לבקר בהיכלו כו' וד\"ל.\n<b>וזהו</b> שם האחת שפרה שמשפרת את הולד כו' שזהו בחי' ה\"א ראשונה דשם הוי' הנ\"ל והוא בחי' עלמין סתימין הנ\"ל, והענין הוא כנ\"ל בפי' מיילדות העבריות שהן הכחות עליונים שהן מקור המיילדי' וממשיכים לבחי' האותיות שנק' כלים פנימי' מן ההעלם דאור הפשוט שהוא עצמות התענוג הפשוט כו' (כאותיות דתורה הקדומה ששם שרש נש\"י שעלו במח' [כ]נ\"ל<sup data-n=\"1423\">330</sup>, והוא ענין בחי' עלמין דכסופי' שיוכלו הנשמות לקבל עונג במורגש כנהר שיוצא מעדן סתימאה הנ\"ל שהוא בבחי' בינה והשגה [שזהו<sup data-n=\"1424\">331</sup> בחי' גילוי ע\"י בבינה<sup data-n=\"1425\">332</sup> ] דוקא כנ\"ל [ש]זהו ה\"א ראשונה כידוע, ונק' שפרה ע\"ש היופי כמו שופרא<sup data-n=\"1426\">333</sup> כו' לפי שבהגלות אור עצמות התענוג בבינה והשגה כנ\"ל (שזהו בחי' גילוי [ע\"י] בבינה דוקא כנ\"ל<sup data-n=\"1427\">334</sup> ) אז יש בזה בחי' היופי והתפארת מבחי' תפארת דעונג הפשוט ממש כענין לאסתכלא ביקרא דמלכא<sup data-n=\"1428\">335</sup> כמ\"ש מלך ביפיו<sup data-n=\"1429\">336</sup> כו', וכידוע שיש ב' מיני הארת פנים, הא' מצד החכמה כמ\"ש חכמת אדם תאיר פניו<sup data-n=\"1430\">337</sup>, והב'",[["1417","325","<b>וב\"פ ש\"י גימ' תר\"ך</b>: נסמן לעיל ט, א."],["1418","*326","<b>שהעוה\"ב. . המעשה דמצות</b>: נסמן לעיל ז, א."],["1419","326","<b>דשכר מצוה מצוה</b>: נסמן לעיל ז, ב."],["1420","327","<b>כל ישראל. . ועמך כולם צדיקים</b>: סנהדרין ר\"פ חלק (צ, א). ישעי' ס, כא."],["1421","328","<b>ויהי נועם ה' עלינו</b>: תהלים צ, יז."],["1422","329","<b>אחת שאלתי </b>[ג: ניתוסף: מאת ה' כו']<b>. . בהיכלו</b>: תהלים כז, ד."],["1423","330","<b>[כ]נ\"ל</b>: אוצ\"ל: [כ]נ\"ל)."],["1424","331","<b>[שזהו. . בבינה]</b>: ניתוסף ע\"פ ח. וראה הערה 334."],["1425","332","<b>גילוי ע\"י בבינה]</b>: מובא בכ\"מ בשם הע\"ח. ראה מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["1426","333","<b>שופרא</b>: נסמן לעיל כו, א."],["1427","334","<b>(שזהו. . כנ\"ל)</b>: ח: ליתא. וראה לעיל הערה 331."],["1428","335","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["1429","336","<b>מלך ביפיו</b>: ישעי' לג, יז."],["1430","337","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."]]],[2300540659,"למעלה מזה והיינו מצד בחי' הפנימי' ועצמות התענוג הפשוט כו'. וז\"ש והשביע בצחצחות נפשך<sup data-n=\"1431\">338</sup> אורות מצוחצחים מאד מבהירות אור התענוג העצמו'. וזהו שמשפרת את הולד שהוא הנשמה שנק' עבריות שנולדה מהעלם העצמו' להאירה ג\"כ ולייפותה באור תפארת העונג העצמו' לצחצח גם בחי' ההשגה דנשמה בהתענגה על ה' [ממש] וכמשה שקרן עור פניו<sup data-n=\"1432\">339</sup> כו' וכן כמו<sup data-n=\"1433\">340</sup> באור פניך נתת לנו<sup data-n=\"1434\">341</sup> כו' וד\"ל.\n[טז] <b>ושם</b> השנית פועה שמדברת עם הולד כו', פי' שם השנית הוא בחי' ה\"א אחרונה דשם הוי' בחי' עלמין דאתגליין שהוא בחי' עולם הדבור בחי' מל'<sup data-n=\"1435\">342</sup> כידוע בפי' בהבראם בה' בראם<sup data-n=\"1436\">343</sup> שהן ה' מוצאות הפה וכמ\"ש בס\"י וקבען בפה<sup data-n=\"1437\">344</sup> כו' שנק' עלמא דאתגלייא בכלל כו', וביאור הענין הנה מבואר למעלה שיש ב' מיני כלים, כלים פנימי' וכלים חיצוני' שהן ב' מיני אותיות א' אותיות עצמיי' שבעצמות הנפש כו' והוא השרש של נשמות ישראל כמו שעלו במח' הקדומה כו', והן הנק' עלמין סתימין דלא אתגליין כנ\"ל בענין עלמין דכסופי' שמבחי' פנימי' ועצמות התענוג כו', דהגם שיורד ונמשך בלבוש דהשגה דבינה שה[י]א [ה\"א] ראשונה שנק' שפרה כו' הרי הוא עדיין בבחי' הסתימות וההעלם בעצמות שא\"א <span data-k=\"pg\">96</span> ּ לבוא לגילוי בדבור בפה כלל, להיות ידוע בענין מ\"ש בזהר ע\"פ ועבד הלוי הוא דא הוא ע\"י<sup data-n=\"1438\">345</sup> כו' דבחי' התגלות ע\"י בבינה הוא יותר מבחכ', וזהו ענין הג' קוצין שביו\"ד<sup data-n=\"1439\">346</sup> דקוץ התחתון שמתפשט בבינה הוא קוץ העליון כו' וכמו הבן בחכ' וחכם בבינה<sup data-n=\"1440\">347</sup> שזהו בחי' התפשטות התענוג העצמי בבינה יותר בהתרחבות מפני שהוא למעלה בשרשו מן החכ' שאינו רק נקודה די' לבד ושרש השגה דבינה הוא בעצמות התענוג ממש שלמעלה ממקור החכ' כו'. וראיה לזה ממה שאנו רואים בהתפעלות התענוג בהשגה יוכל להתפשט הרבה יותר מעונג זה שמורכב בהשגה, והיינו שיבא להתפעלות כל עצמות הנפש ממש עד כלותה כענין השיר של הלוים<sup data-n=\"1441\">348</sup> שז\"ש ועבד הלוי הוא כו' כמו בשירת הים שהי' בהם התפעלות עצמות הנפש ממש כו'. וזהו עיקר ענין העוה\"ב שנק'",[["1431","338","<b>והשביע בצחצחות נפשך</b>: ישעי' נח, יא."],["1432","339","<b>וכמשה שקרן עור פניו</b>: תשא לד, כט ואילך."],["1433","340","<b>כמו</b>: גח: במ\"ת."],["1434","341","<b>באור פניך נתת לנו</b>: סיום תפלת העמידה."],["1435","342","<b>הדבור בחי' מל'</b>: ראה זהר לך פו, ב. ע\"ח (שער מוחין דצלם) שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["1436","343","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. שע\"ת צא, ג. שה\"א לב, ב. לקמן פ' וארא פא, ב. תצוה שסז, א."],["1437","344","<b>וכמ\"ש בס\"י וקבען בפה</b>: ראה שם פ\"ב, מ\"ג."],["1438","345","<b>ועבד הלוי. . ע\"י</b>: קרח יח, כג. ראה זהר שם קעח, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370049\" data-slug=\"torah-or\" data-id=\"3901370049\">תו\"א לך יא, ב</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע פד ואילך. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שעה. לקמן פ' בשלח קצח, א. תצוה שסז, ג."],["1439","346","<b>הג' קוצין שביו\"ד</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670175\" data-slug=\"torat-chaim\" data-id=\"2300670175\">תו\"ח לך פב, ב</a> ובהערה 11. לקמן פ' בשלח קצח, א. תצוה שסז, ג."],["1440","347","<b>הבן בחכ' וחכם בבינה</b>: ס\"י פ\"א, מ\"ד."],["1441","348","<b>השיר של הלוים</b>: ראה סידור שער הפורים רפא, סע\"ד."]]],[2300540671,"יש<sup data-n=\"1442\">349</sup> הגם שהוא יש דהשגה אבל הוא בעצמות התענוג ממש (ונק' נהרי אפרסמונא דכיא<sup data-n=\"1443\">350</sup> כו') וכמ\"ש ואמר ביום ההוא הנה אלקינו זה<sup data-n=\"1444\">351</sup> וכמו זה אלי<sup data-n=\"1445\">352</sup> כו', וע\"כ נק' עלמא דאתכסייא דוקא כי הוא בבחי' פנימי' בינה שא\"א לבוא בגילוי דיבור כלל רק בשיר וניגון<sup data-n=\"1446\">353</sup> וכה\"ג וכמ\"ש במ\"א וד\"ל. אבל כדי שיוכל לבא בבחי' אותיות הדבור צריך להיות ע\"י כח ומקור מיוחד לזה שמביא וממשיך התענוג העצמי' שבפנימי' בינה לידי גילוי אותיות הדבור, והוא גילוי אהבה רבה בתענוגים שבלב באותיות הדבור בפה שהן כלים יותר נמוכים ונק' כלים חיצונים כו', והיינו מ\"ש ושם השנית פועה שמדברת עם הולד שמביאה לבחי' גילוי הדבור אחר שכבר נהנה ומתענג בתענוג העצמיי'<sup data-n=\"1447\">354</sup> בפנימית בינה יוכל לבא [ל]גילוי בדבור דוקא שזהו הנק' עלמין דאתגליין דוקא והוא מבחי' שם ה\"א אחרונה דשם הוי' שהוא בחי' הדבור (כמו דוד המלך שהי' מבחי' המל'<sup data-n=\"1448\">355</sup> עלמא דאתגלייא הי' אומר [תמיד] שירות ותשבחות בדבור<sup data-n=\"1449\">356</sup> בפה דוקא וכמלאכים שאומרי' שירה בפה), (והוא מ\"ש שינחיל לצדיקי' ש\"י עולמות שהן עלמין דאתגליין שהוא בבחי' יש ודבר ממש, משא\"כ עלמין דכסופין שנק' עלמין סתימין) (והגם שהדיבור הוא בבחי' יש אבל שרשו נעלה יותר מתענוג שבהשגה הסתום שבבחי' אין כו' כנ\"ל בענין מי שם פה לאדם<sup data-n=\"1450\">357</sup> כו' וכמ\"ש במ\"א בענין עומק חכ' שבלב<sup data-n=\"1451\">358</sup> שיסוד אימא מסתיים בחזה<sup data-n=\"1452\">359</sup> ויסוד אבא נמשך בדבור<sup data-n=\"1453\">*360</sup>, דאבא יסד ברתא<sup data-n=\"1454\">360</sup> כו', והוא בחי' [ש]וב ששרשו למעלה מרצוא<sup data-n=\"1455\">361</sup> דעומק בינה כו', והוא בחי' בן דמסט' דאבא<sup data-n=\"1456\">362</sup> כו').\n[יז] <b>וזהו</b> שאמר למיילדות העבריות אשר שם האחת שפרה שמשפרת את הולד כנ\"ל, ושם השנית פועה שמדברת כו' שהן ב' ההי\"ן דהוי' כו' בילדכן את העבריות מן ההעלם דעצמות כו' וראיתן על האבנים אם בן הוא והמיתן אותו ואם בת היא וחיה, פי' בן מלשון בנין<sup data-n=\"1457\">363</sup> כמו עולם חסד יבנה<sup data-n=\"1458\">364</sup> בחכ' יבנה<sup data-n=\"1459\">365</sup> כו' וגם הוא מלשון בינה שנק' בן י\"ה<sup data-n=\"1460\">366</sup> כמו יבוננהו<sup data-n=\"1461\">367</sup> כו' והכל א', דהנה בן הוא בחי' דכר שבנינו מבחי'",[["1442","349","<b>העוה\"ב שנק' יש</b>: ראה גם לקמן פ' וארא נ, ג. פקודי תמג, ב. תנג, ד. שע\"ת סז, ב. צא, ב."],["1443","350","<b>נהרי אפרסמונא דכיא</b>: ראה תענית כה, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670124\" data-slug=\"torat-chaim\" data-id=\"2300670124\">תו\"ח נח מז, ג</a>. ש\"א ז, א. מאמרי אדה\"א נ\"ך ע' תקצו. וש\"נ. דרושי חתונה ח\"א ע' קלט. וש\"נ. לקמן פ' וארא נא, ג. בשלח קצז, סע\"ד. משפטים רצד, ב. ויקהל תח, ב."],["1444","351","<b>ואמר. . אלקינו זה</b>: ישעי' כה, ט."],["1445","352","<b>זה אלי</b>: בשלח טו, ב."],["1446","353","<b>בשיר וניגון</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670159\" data-slug=\"torat-chaim\" data-id=\"2300670159\">תו\"ח לך פב, סע\"א</a>."],["1447","354","<b>העצמיי'</b>: ג: ליתא. ח: העצמות."],["1448","355","<b>דוד. . המל'</b>: ראה לקמן פ' וארא נו, ג. וש\"נ."],["1449","356","<b>דוד. . עלמא דאתגלייא. . בדבור</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' נו. כתובים ח\"א ע' כג. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תרפט ואילך."],["1450","357","<b>בענין מי שם פה לאדם</b>: לעיל כט, א."],["1451","358","<b>בענין עומק חכ' שבלב</b>: ראה גם מאמרי אדה\"א בראשית ע' רצד."],["1452","359","<b>שיסוד אימא מסתיים בחזה</b>: ראה ע\"ח (שער לידת המוחין) שכ\"א, פ\"ג. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ. לקמן פ' וארא עא, א."],["1453","*360","<b>ויסוד אבא נמשך בדבור</b>: ראה ש\"א ו, א ובהערה 6."],["1454","360","<b>דאבא יסד ברתא</b>: נסמן לקמן מז, ב."],["1455","361","<b>[ש]וב ששרשו למעלה מרצוא</b>: ראה גם לעיל ז, ג."],["1456","362","<b>בן דמסט' דאבא</b>: ראה זהר במדבר קכ, א. מאמרי אדה\"א בראשית ע' תקלד. וש\"נ. אמ\"ב קכג, ג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670517\" data-slug=\"torat-chaim\" data-id=\"2300670517\">תו\"ח בראשית כח, ד</a>."],["1457","363","<b>בן מלשון בנין</b>: ראה אבן עזרא לך טז, ב. ב\"ר פמ\"ה, ב. ערכי הכינויים לבעל סדה\"ד מערכת בנים (מארי קבלה). לעיל כו, א. אוה\"ת שמות ע' ב'תקח."],["1458","364","<b>עולם חסד יבנה</b>: נסמן בהערה 374."],["1459","365","<b>בחכ' יבנה</b>: משלי כד, ג."],["1460","366","<b>בינה בן. . י\"ה</b>: זהר (רע\"מ) תרומה קנח, א. נשא קכג, סע\"א. ראה אגה\"ת פ\"ח. מאמרי אדה\"ז תקס\"ו שבהערה הבאה. מאמרי אדה\"א דברים ח\"א ע' קלא."],["1461","367","<b>יבוננהו</b>: האזינו לב, י. ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתצז. תקס\"ו ע' שסו. מאמרי אדה\"א הנחות תקע\"ז ע' שלט."]]],[2300540683,"החסדי'<sup data-n=\"1462\">368</sup> דאבא דוקא כידוע בזהר דבן מסט' דאבא קאתי כו' שרובו חסדים ומיעוטו גבורות כו' וכמ\"ש כי זכר חסדו<sup data-n=\"1463\">369</sup> כו', שהחסד הוא בבחי' זכר<sup data-n=\"1464\">370</sup> מזכרון דאור אבא כו' (כי הבן בדומה לאב יותר כמו כי אתה אבינו<sup data-n=\"1465\">371</sup> כו') שהוא עיקר בחי' אדם דשם מ\"ה<sup data-n=\"1466\">372</sup> כמ\"ש מה שמו ומה שם בנו<sup data-n=\"1467\">373</sup> כו', וע\"כ טבעו להשפיע חסדים למקבלים שזהו מטבע הזכר דוקא שהוא בחי' משפיע דוקא, והיינו ג\"כ ענין בנין שטבע החסד לבנות בנין כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"1468\">374</sup> שבחסדי' דוקא יבנה כל בנין העולמות. דבאמת <span data-k=\"pg\">מח</span> ּ אין ערוך כלל לעולמות בע\"ג לבחי' עצמות אלקות כידוע רק ע\"י בחי' החסדים העליונים שבאור חסד דאצי' שטבע הטוב להטיב<sup data-n=\"1469\">375</sup> ולהשפיע כו', ע\"כ מזה הי' בחי' הצמצום וירידת האור האלקי להמשיך שפע אור העליון שיבוא בבחי' כלים מכלים שונים גם באצי' עצמו כמו במח' ודבור כנ\"ל שהן למ\"ד כלים<sup data-n=\"1470\">376</sup> ראש תוך סוף כו', שעי\"ז יומשך עוד למטה מטה להיות בחי' בנין העולמות הנפרדי' בע\"ג מאין ליש ממש כו' כמים שיורדים מגבוה לנמוך<sup data-n=\"1471\">377</sup> ביותר כו' עד התהוות עולם השפל הזה כו', שכ\"ז הוא רק מצד ריבוי הכלים שעי\"ז יהי' ההשתלשלו' מעילה לעלול להיות גילוי אור בכלים מכלים שונים עד שיהי' מציאת בנין עולם הנפרד ליש גמור כו'. ואמנם מבואר למעלה שירידה זו לצורך עלי' והוא שיהי' בחי' ביטול היש לאין עד שגם צבא השמים התחתוני' שאע\"פ שהן בבחי' יש גמור אומרים שירה ומשתחוים כנ\"ל, וגם בצמצום האחרון ביותר דק\"נ דאת זלעו\"ז עשה<sup data-n=\"1472\">378</sup> כו' גם הם מתבטלים מגסות שלהם לפרקים כשיאיר עליהם גילוי אור האלקי כמו בלעם שא' לא אוכל לעבור<sup data-n=\"1473\">379</sup> כו' וכנ\"ל לפי שגם בהם יש האר' אור האלקי רק שמצומצם מאד כנ\"ל.\n<b>והנה</b> מבואר למעלה שלזאת אין החיצוני' רוצים בהמשכת האורות בריבוי הכלים מכלים שונים שזהו בחי' התיקון דאדם דיושר (שזהו בחי' ב\"ן כנ\"ל) מטעם שעי\"ז לא יגיע אליהם השפע רק מחיצוני' דחיצוני' הכלים כו', וע\"כ ציוה פרעה שהוא כתר דקליפה למיילדות העבריות הנ\"ל שימיתו לבן הילוד כו', לפי שבחי' בן הוא בחי' התלבשות אור בכלי בבחי' גילוי אור בקירוב שהוא בחי' ביטול היש לאין כו' בכלים מכלים שונים שזהו עיקר בחי' הבנין דעולם חסד יבנה כנ\"ל, ופרעה ראה בשרש נש\"י למעלה בבחי' עלמין סתימין ועלמין דאתגליין שהן",[["1462","368","<b>דכר שבנינו מבחי' החסדי'</b>: ראה זהר תזריע מח, ב. נשא קמה, ב. ע\"ח שער (מ\"ן ומ\"ד) שט\"ל, דרוש י."],["1463","369","<b>כי זכר חסדו</b>: תהלים צח, ג [ותיבת ”כי\" מובא בפסוק א. — ראה גם סידור שער החנוכה רפ, ד. מאמרי אדה\"ז תקס\"ו ע' שפח. ש\"א לב, ב. מאמרי אדה\"א בראשית ע' תקלד. ויקרא ח\"א ע' ל. נ\"ך ע' יז. ובהנסמן בהנ\"ל. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670441\" data-slug=\"torat-chaim\" data-id=\"2300670441\">תו\"ח וירא קד, ד</a> ובהערה 34. לקמן פ' וארא פד, ד. בא פח, א. פט, רע\"ג. משפטים רצו, ד]."],["1464","370","<b>שהחסד הוא בבחי' זכר</b>: נסמן לעיל כו, א הערה 93."],["1465","371","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["1466","372","<b>אדם דשם מ\"ה</b>: נסמן לעיל ד, ב הערה 186."],["1467","373","<b>מה שמו ומה שם בנו</b>: משלי ל, ד. ג: מה — נסמן לעיל א, ג הערה 28."],["1468","374","<b>כי אמרתי. . יבנה</b>: תהלים פט, ג."],["1469","375","<b>שטבע הטוב להטיב</b>: מובא לקמן פ' בשלח קנב, ג. ריח, א. רמח, ג. ויקהל תמב, א בשם הע\"ח. ראה שהיחוה\"א פ\"ד. מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670042\" data-slug=\"torat-chaim\" data-id=\"2300670042\">תו\"ח בראשית ל, ב</a> הערה 4."],["1470","376","<b>שהן למ\"ד כלים</b>: ראה ע\"ח (שער הפרצופים) ש\"ל, דרוש ב."],["1471","377","<b>כמים שיורדים מגבוה לנמוך</b>: ראה תענית ז, א."],["1472","378","<b>דאת זלעו\"ז עשה</b>: קהלת ז, יד. ראה ביאוה\"ז פקודי נט, ב. מאמרי אדה\"א שמות ח\"ב ע' תצה. וש\"נ. שע\"ת סט, א הערה 10."],["1473","379","<b>לא אוכל לעבור </b>[ג: ניתוסף: את פי ה']: בלק כב, יח."]]],[2300540695,"באים בבחי' כלים רבים לגילוי אלקות שמחמת זה לא יגיע לו רק בחי' התמצית ופסולת ביותר (וכמ\"ש הן עם בנ\"י<sup data-n=\"1474\">380</sup> רב ועצום ממנו כו'), ע\"כ ציוה שימיתו לכל בן זכר דוקא שלא יהי' בחי' כלי לאור העליון בעלמין סתימין ועלמין דאתגליין כלל כו', אלא יחזרו כל אור למקורו בבחי' העלם המקיף הכללי בעצמות המאציל כמו שהי' תחלה (כדוגמא דמיתה בגשמיות שמסתלק הנפש שהוא הצורה מן החומר דגוף ואין לו בחי' כלי כו') שאז גם הוא יכול ליקח יניקה ושפע רב מאד מטעם הנ\"ל שבבחי' המקיף העליון הכל יכולים לקבל משום שהוא למעלה מבחי' ההשתלשלו' דאו\"כ לגמרי כנ\"ל (ובפרט בחי' עלמין דאתגליין בדבור שהוא בא בבחי' כלי ממש ואינו נפרד כלל וכלל אדרבה נק' אדם בדומה לעליון ממש כמו במשיח כו'<sup data-n=\"1475\">381</sup> (וכנ\"ל בג' מדרגות דיש ואין ויש שהוא בדומה ליש האמיתי כו'). וז\"ש אם בן הוא דוקא אז והמיתן אותו מטעם הנ\"ל, אבל אם בת היא וחיה והטעם הוא כידוע דבחי' נוק' שרשה מבחי' גבורות<sup data-n=\"1476\">382</sup> דאימא ומיעוט[ה] מחסד כו' וכמ\"ש כאמה בתה<sup data-n=\"1477\">383</sup> כו' דבת מסט' דאימא<sup data-n=\"1478\">384</sup> כו', ובחי' גבורות הוא בחי' הצמצומי' ודינין שהוא בחי' ההסתלקו' דאו\"ח כו' היפך גמור מחסדים דאו\"י דדכר כו', וכאשר עולה האור למעלה בבחי' או\"ח חוזר הוא למקורו ממש בעצמו' המאציל ואז גם החיצונים יכולים לקבל יניקה משם כנ\"ל וז\"ש <span data-k=\"pg\">98</span> ּ ואם בת היא וחיה וד\"ל. ולא עוד אלא שיומשך להם רוב שפע ביותר מכפי מדתם, להיות שבחי' הצמצום גבורות דנוק' הוא הגורם להיות עוד ריבוי [ה]צמצו[מי]ם והסתלקו' אור האלקי כ\"כ עד שיתצמצם האור להיות<sup data-n=\"1479\">385</sup> בסתר המדרגות גם למטה מטה ביותר והיינו גם בחיצוני' ואחוריי' דאחוריי' דמל' דמל' דעשי' במ\"ח צירופי' האחרונים דש' אלקי' דהיינו ענין את זה לעו\"ז כו' עד שיוכלו להיות בבחי' פירוד גמור ויקבלו רוב שפע יתירה כו' כידוע בענין גלות השכינה בע' שרים דנוגה כו', לפי שגם מבחי' כלים החיצונים דאו\"פ דיושר יכולים לקבל גם ביתר מקו המדה כאשר יורד האור בסוד גלות כו' (וזהו ההפרש בין בחי' רצוא דיראה שנק' בת לשוב דאהבה בהמשכות גילוי אלקו' בכלים שנק' בן וד\"ל).\n[יח] <b>ותיראן </b>המילדות את האלקי' ולא עשו כו', פי' שם אלקים הוא בחי' הצמצום<sup data-n=\"1480\">386</sup> שמצמצם על שם הוי' כמ\"ש כי שמש ומגן<sup data-n=\"1481\">387</sup> הוי' אלקי' כו' כידוע דצמצום זה הוא",[["1474","380","<b>הן עם בנ\"י</b>: שמות א, ט [ושם: הנה]."],["1475","381","<b>כו'</b>: אוצ\"ל: כו')."],["1476","382","<b>נוק' שרשה מבחי' גבורות</b>: ראה זהר בראשית מח, ב. אחרי סה, א. ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ד. לעיל הערה 368. לקמן פ' בא פט, ג."],["1477","383","<b>כאמה בתה</b>: יחזקאל טז, מד."],["1478","384","<b>דבת מסט' דאימא</b>: ראה זהר במדבר קכ, א. ביאוה\"ז שם קמו, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרכג."],["1479","385","<b>להיות</b>: גח: להתלבש."],["1480","386","<b>אלקים. . הצמצום</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב כמ\"ש בלק\"א — שהיחוה\"א רפ\"ו. מאמרי אדה\"א בראשית ע' קעג. דברים ח\"ב ע' תרנא ובהנסמן בהנ\"ל. לקמן פ' בא קיב, ד. יתרו רסג, ג. רסו, ב. תרומה דש, ד. תצוה שכח, ב. שלא, ב. שע, ד."],["1481","387","<b>כי שמש ומגן</b>: תהלים פד, יב."]]],[2300540707,"בין באו\"כ דאצי' בין מאצי' בבי\"ע והוא להפסיק אור האצי' ולהסתירו כדי שיוכל להיות ירידת והמשכת השפע אלקי' מאין ליש דוקא ואם לא בחי' הצמצום הזה לא הי' התהוות יש מאין עד רום המעלות, וכידוע שזהו ג\"כ ענין צמצום הראשון שיהי' המשכות האור דקו\"ח באורות דע\"ס דאצי' כו', ומבואר למעלה שעיקר המכוון הי' בצמצום זה דאלקי' שהוא בחי' קו המדה למדוד כל או\"כ כו', היינו שיהי' בחי' ביטול היש לאין ע\"י גילוי אור האלקי מקרוב בכלים מכלים שונים כמו ע\"י תומ\"צ ביחו\"ע דאו\"כ דאצי' עד למטה מטה ג\"כ במלאכים ונשמות דבי\"ע כו' [ש]זהו ענין דירה בתחתונים. ואין הצמצום הזה ענין צמצום גמור להסתיר לגמרי רק כדי שיהי' גילוי האור במדה ושיעור בבחי' אין ויש שהוא בחי' או\"כ בכל ענין<sup data-n=\"1482\">388</sup> לפי ערכו כו' וכמ\"ש בראשית ברא אלקים דוקא כנ\"ל וכן אמר ביום עשות ה' אלקים<sup data-n=\"1483\">389</sup> ארץ כו'. ונמצא שעיקר הכוונה הי' בחסד דבנין העולמות [ש]אמר עולם חסד יבנה [שיהי'] בבחי' בנין דוקא שהוא בחי' בן אור בכלי (בבחי' שוב דהמשכת אלק[ו]' בכלים דוקא). וע\"כ ותיראן המיילדות את האלקי' דוקא שלא יעשו נגד הרצון והכוונה דשם אלקי' המצמצם האורות בכלים כו', ולא עשו כדבר פרעה להמית הבן הנולד שזהו היפך כוונת ורצון דשם אלקי' (וגם המיילדות העבריות שרשם בשם אלקים שהרי הן בחי' המקור והכח להוליד את בחי' האותיות דמח' ודבור שהוא ג\"כ כדי שיהי' המשכת האורות בכלים דוקא וד\"ל.\n<b>והנה</b> כאשר ראה פרעה העליון שהוא בחי' כתר דקליפה שהמיילדות העבריות יראו את שם האלקים כנ\"ל התחכם בעצמו לבטל יראת אלקי' דמיילדות וצוה לכל עמו כל הבן הילוד היאורה תשליכוהו (ומה גם שקיבל טענות המילדות דלא כנשים המצריות העבריות<sup data-n=\"1484\">390</sup> כי חיות הנה בטרם תבוא אליהן המיילדת וילדו כי בחי' אותיות דמח' ודבור שהן בבחי' עצמיי' יוצאי' ונולדי' מאליהן כמו אותיות התורה ושרש נש\"י במח' הקדומה כו'). וביאור הענין הנה יש להקדים תחלה בשרש ענין ד' נהרות שיוצאים מג\"ע דכתי' ונהר יוצא מעדן<sup data-n=\"1485\">391</sup> כו' ומשם יפרד והי' לד' ראשים שם האחד פישון<sup data-n=\"1486\">392</sup> הוא הסובב כו' וידוע דפישון הוא נהר נילוס<sup data-n=\"1487\">393</sup> וז\"ש היאורה תשליכוהו כו', להיות ידוע בענין נהר זה שיוצא מעדן שהוא בחי' מקור הראשון לכל ההשתלשלו' דאו\"כ שמסתעפים <span data-k=\"pg\">מט</span> ּ מאור הכתר ומכתר לחכמה כו', לפי שבחי' עדן זה הוא בחי' התענוג הפשוט שבעצמו' המאציל שנק' עדן סתימאה והוא מ\"ש ויטע ה' אלקי' גן בעדן מקדם מקדמונו של עולם<sup data-n=\"1488\">394</sup> שקודם לכל ההשתלשלו'",[["1482","388","<b>ענין</b>: גח: עולם."],["1483","389","<b>ביום עשות ה' אלקים</b>: בראשית ב, ד. ראה גם לעיל כו, ב."],["1484","390","<b>דלא כנשים המצריות העבריות</b>: שמות א, יט."],["1485","391","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["1486","392","<b>שם האחד פישון</b>: בראשית שם, יא."],["1487","393","<b>דפישון הוא נהר נילוס</b>: נסמן לקמן לו, ד הערה 22."],["1488","394","<b>ויטע. . מקדמונו של עולם</b>: בראשית ב, ח. ראה גם לקמן פ' בשלח קנט, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670062\" data-slug=\"torat-chaim\" data-id=\"2300670062\">תו\"ח נח סד, א</a> ובהערה 7. שם עח, ד."]]],[2300540719,"דאבי\"ע כו', ומעדן זה נמשך בבחי' ירידה והמשכה לנהר זה שהוא בחי' התענוג הבא לחכמה ובינה שעדיין הם שם בבחי' ההעלם וסתימות דבחי' עדן העליון (שהוא העוה\"ב כידוע) ושם כלולים בהעלם כל מה שמסתעפי' בפרטות מן ההעלם לגילוי שהוא גילוי אור התענוג העליון [ב]כו\"ח<sup data-n=\"1489\">395</sup> ובינה ומדות ומחודו\"מ כו' שהוא ענין הג\"ע לנשמות שיהיו נהנין ממש מזיו השכינה שהוא בחי' זיווא עילאה דע\"י<sup data-n=\"1490\">396</sup> שבבינה דמל' דאצי' כו'. וז\"ש ונהר יוצא מן ההעלם דעדן סתימאה לגילוי אור גמור להשקות את הגן כו', ועדיין הכל הוא בבחי' יחוד עליון דאצי' באו\"כ גם בנשמות שעולין מדי חדש ושבת<sup data-n=\"1491\">397</sup> להתענג על ה' מזיו<sup data-n=\"1492\">398</sup> ועונג העליון כו', אך משם יפרד<sup data-n=\"1493\">399</sup> והי' כו' לאחר יציאת הנהר מג\"ע נחלק ונפרד לד' ראשים שהוא בא בבחי' ההתחלקו' והפירוד ממקורם הראשון שאינו רק נהר אחד דבחי' עונג הנעלם שבבינה דמל' בג\"ע כנ\"ל. ועכ\"ז עדיין כל הד' נהרות בראשית יציאתם מג\"ע [מ]צד שמקבלים נביעתם מנהר שיוצא מעדן העליון הנ\"ל הרי הם בבחי' התכללות גמור בעדן ג\"כ לפי שעדיין אחוזים וקשורים במקורם בנהר זה שיוצא מעדן כו', ובפרט בנהר הראשון שא' עלי[ו] שם האחד פישון שהוא נהר נילוס להיותו קודם לראשון והאחרי'<sup data-n=\"1494\">400</sup> (וכמ\"ש הוא הסובב כו' שם הבדולח<sup data-n=\"1495\">401</sup> ואבן השוהם וכתי' כגן ה'<sup data-n=\"1496\">402</sup> כארץ מצרים כו'), ולא א' שם הראשון כמ\"ש ושם הנהר השני<sup data-n=\"1497\">403</sup> והשלישי<sup data-n=\"1498\">404</sup> כו' אלא האחד הוא להיותו בבחי' אחדות ויחוד עדיין ונק' אחד, אע\"פ שא' משם יפרד אינו בחי' פירוד ממש רק שנמשך לבא בריחוק מקום, אבל אינו נפרד ממקורו כלל, וא' האחד כוונתו שנכלל בעדן עצמו ביחוד גמור כי אחוז וקשור הוא בנהר שיוצא מעדן ממש ואינו אלא נהר אחד ממש (והוא נהר פרת כמו שאמרו והרביעי הוא נהר פרת הוא דמעיקרא<sup data-n=\"1499\">405</sup> כו').\n[יט] <b>וזהו</b> שאמר פרעה כל הבן הילוד היאורה תשליכוהו היינו בנהר נילוס שהוא היאור הכללי שכולל הכל ואחוז וקשור במקורו בעדן העליון עצמו כנ\"ל, והענין הוא שרצה פרעה העליון שמקבל מנהר נילוס (שנפל שם מניצוצו' הקדושות [ד]בחי' התהו ע\"י חטא אדה\"ר בעה\"ד כמ\"ש למעלה<sup data-n=\"1500\">406</sup> ) שכל הבן דהיינו אור העליון הבא בבחי' כלים דתיקון דאו\"פ דיושר כנ\"ל שיחזור ויוכלל למעלה במקורו הראשון להיות שם בבחי' התכללות ממש כמו בבחי' עיבור הולד בבטן אמו או כמשל השינה כנ\"ל, והוא בבחי' נהר שיוצא מעדן עליון שהוא בחי' פנימי' בינה סתימאה שיצא מעדן סתימאה כו' שהוא בחי' התענוג העליון הנעלם שלמעלה מעלה מן ההשגה (היפך ענין",[["1489","395","<b>[ב]כו\"ח</b>: ח: בכ' וחכמ'."],["1490","396","<b>נהנין. . מזיו השכינה. . זיווא עילאה דע\"י</b>: ראה ברכות יז, א. ראה גם סידור שחרית מא, ב. מאמרי אדה\"א נ\"ך ע' תסה. וש\"נ. קונטרסים ע' קפה. שע\"ת כח, ב. לקמן פ' וארא נא, ג. בשלח קמד, ב. תצוה שדמ, א."],["1491","397","<b>בנשמות שעולין מדי חדש ושבת</b>: ראה זהר תרומה קנו, ב. מאמרי אדה\"א נ\"ך ע' תסז. וש\"נ. לקמן עה, ד. צא, ב. קסז, ב. קצ, ג. רפו, א. שצה, ד. תטו, ד (שבת). תכג, ב (שבת)."],["1492","398","<b>מזיו</b>: ג: ניתוסף: השכינה."],["1493","399","<b>משם יפרד</b>: ראה גם לקמן מ, א ובהנסמן לשם."],["1494","400","<b>לראשון והאחרי'</b>: גח: וראשון להאחרי'."],["1495","401","<b>הוא הסובב. . שם הבדולח</b>: בראשית ב, יא. יב."],["1496","402","<b>כגן ה'</b>: לך יג, י."],["1497","403","<b>ושם הנהר השני</b>: בראשית ב, יג."],["1498","404","<b>והשלישי</b>: שם שם, יד [ושם: ושם הנהר השלישי]."],["1499","405","<b>והרביעי. . הוא דמעיקרא</b>: בכורות נה, ב [ושם: והנהר הרביעי הוא פרת. . הוא פרת דמעיקרא]."],["1500","406","<b>שנפל שם. . כמ\"ש למעלה</b>: לע\"ע לא נתברר לאיזה מאמר כוונתו. וראה לקמן לט, ג. והנרשם לקמן ברשימת הכת\"י בריש המאמר כאן."]]],[2300540731,"הנ\"ל במיילדות כו' שמשפרת את הולד להיות בא העונג העליון<sup data-n=\"1501\">407</sup> במורגש בכלי אותיות ההשגה ממש כו') שהוא בחי' עיבור באימא עילאה דפנימי' בינה בפנימי' אבא ששם פנימי' ע\"י כידוע שהוא העדן עילאה עצמו עד שיבא בבחי' ביטול והתכללות ממש במקור הראשון שהוא עצמות המאציל (עד\"מ מן בחי' הגלות שהוא בחי' הסתלקות המוחין ומדות בבחי' או\"ח לעצמות ממש שנמשל לעיבור ושינה כנ\"ל), וזהו היאורה תשליכוהו שלא יהי' בחי' כלים לאור העליון כלל כו', <span data-k=\"pg\">100</span> ּ לפי שאינו חפץ בגילוי האורות בכלים מטעם הנ\"ל, ואדרבה הרי בבחי' זו דהתכללות האורות בעצמות המאציל יגיע ויבא גם לפרעה דקליפה תוס' יניקה ושפע רב מטעם הנ\"ל דבבחי' המקיף הנעלם יכולים הכל לקבל כו', ובפרט בנהר זה שהוא מיוחד בעדן העליון שהוא בחי' פנימי' בינה הוא הנק' יובלא עילאה<sup data-n=\"1502\">408</sup> עולם החירות כו' כמ\"ש בזהר ששם כל העבדים יוצאים לחירות חפשי דהיינו גם י' כתרין דק\"נ שנק' עבדים<sup data-n=\"1503\">409</sup> כידוע ובפנימי' בינה שהוא עולם החירות יוצאים העבדים לחירות כו', ויכולים גם הם לקבל רב טוב ושפע העליון הרבה יותר מכפי המדה כו', מפני שהוא למעלה מעלה עדיין מבחי' קו המדה הבא בהשתלשלו' דאורות וכלים מכלים שונים כו' (טרם התפשטות הרצון וחכמה ומדות מן ההעלם לגילוי כו'), אלא כלול הכל כא' בהעלם העצמות שהוא המקיף העליון הכללי שאינו בגדר התחלקות כלל כנ\"ל, ע\"כ הכל שוין שם כחשיכה כאורה<sup data-n=\"1504\">410</sup> כו', עד שגם היותר תחתון מקבל בשוה כמו היותר עליון ממש בשוה כנ\"ל, ע\"כ גם החיצוני' יכולים לקבל שם כנ\"ל באורך וד\"ל (וכמ\"ש במ\"א בענין זכרנו את הדגה<sup data-n=\"1505\">411</sup> כו' במצרים חנם, חנם בלא מצות, לפי שאין המצות מגיעים בהעלאת מ\"ן לשם כמ\"ש אם צדקת מה תתן לו<sup data-n=\"1506\">412</sup> כו' והוא מפני בחי' עוצם הרוממות וההתנשאות שמצד עצמות א\"ס כו' שלזה ביקש משה שלא תשרה שכינה באוה\"ע כנ\"ל וד\"ל).\n<b>אך</b> עכ\"ז גם בעצם הרוממות וההתנשאו' ממש הרי נש\"י עלו במח' הקדומה וכן אותיות התורה כו' להיותם נבדלים גם שם בבחי' פנימיות ועצמיות ממש וכמ\"ש במ\"א בענין יבחר לנו את נחלתינו<sup data-n=\"1507\">413</sup> כו' וכענין במי נמלך<sup data-n=\"1508\">414</sup> בנשמתן של צדיקים כו' דסוף מעשה הצדיקים בתומ\"צ עלה במח\"ת כו'. ולזה יראו המילדות העבריות הנ\"ל שהן ב' ההי\"ן כו' ולא עשו כדבר פרעה ותחיינה את הילדים. אך כאשר ראה פרעה שיראו את שם האלקים המצמצם כדי שיבא האורות עליונים בכלים עשה להם",[["1501","407","<b>העונג העליון</b>: גח: עונג הנעלם."],["1502","408","<b>בינה. . יובלא עילאה</b>: נסמן לעיל כו, ג."],["1503","409","<b>י' כתרין דק\"נ שנק' עבדים</b>: ראה זהר וישלח קסו, ב."],["1504","410","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["1505","411","<b>זכרנו את הדגה</b>: ראה גם לעיל כו, רע\"ד. וש\"נ."],["1506","412","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["1507","413","<b>יבחר לנו את נחלתינו</b>: תהלים מז, ה. ראה סידור דרושים לחתונה קלה, ב. מאמרי אדה\"א נ\"ך ע' שסט. וש\"נ. ראה גם לקמן פ' בשלח קלה, ב."],["1508","414","<b>וכענין </b>[ח: ובענין]<b> במי נמלך</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. שע\"ת קטו, ב."]]],[2300540743,"בתים<sup data-n=\"1509\">415</sup> וצוה שכל הבן הילוד כו' שהוא למעלה משם האלקים המצמצם בשביל דירה בתחתונים והוא בבחי' עדן העליון עצמו שרש הנהרות הנ\"ל שהוא בבחי' עלי' והתכללות בעצמו' התענוג העליון הפשוט (כמו בשבת שנא' ויכל אלקים<sup data-n=\"1510\">416</sup> ביום השביעי פי' שם אלקים דמע\"ב כמו בראשית ברא אלקים<sup data-n=\"1511\">417</sup> ויאמר אלקים<sup data-n=\"1512\">418</sup> כו' שהוא בחי' הצמצום דאור הכתר בחכ' כו' מפני שעולה ונכלל למעלה מעלה בפנימי' הכתר שהוא פנימי' ועצמו' התענוג הפשוט כמ\"ש במ\"א בענין עלי' דאו\"ח דמע\"ב<sup data-n=\"1513\">419</sup> ביום השבת למקור כל התענוגי' העליונים וזהו ויכל ל' תענוג<sup data-n=\"1514\">420</sup> כו' שעולה התענוג שברצון וחכ' דמע\"ב במקור התענוגים כו', שבכל שבת יש מבחי' יום שכולו שבת שהוא העוה\"ב כידוע וד\"ל<sup data-n=\"1515\">421</sup>, וגם כאן עולה ונכלל שם אלקים המצמצם להיות המשכת התענוג ורצון להיות גילוי אורות בכלים כנ\"ל למעלה מעלה והוא בבחי' עדן העליון עצמו שהוא מקור התענוגים כו', וזהו שציוה היאורה תשליכוהו בנהר נילוס ששרשו<sup data-n=\"1516\">422</sup> בעדן עצמו שהוא למעלה משם אלקי' המצמצם כו' וד\"ל.\n[כ] <b>אך</b> מה עשה ה' לנגד כוונת פרעה למנוע תולדות נשמות ישראל כו' לפי שציוה כל הבן הילוד כו', לא די שנולדו נש\"י ויפרו וירבו מאד<sup data-n=\"1517\">423</sup> עוד עשה ה' להוציא את בנ\"י <span data-k=\"pg\">נ</span> ּ מיד פרעה וינצלו את מצרים<sup data-n=\"1518\">424</sup> מכל טוב העליון שנפל שם ע\"י מושיע זה משה שהי' שרש נשמתו דוקא<sup data-n=\"1519\">425</sup> מבחי' מקיף העליון שלמעלה מעלה מכל ההשתלשלו' דאו\"פ דיושר והוא מבחי' מ\"ע כמ\"ש כי מן המים משיתיהו<sup data-n=\"1520\">426</sup> כו'. וכל יראת פרעה הי' רק מפני בחי' בן דבחי' או\"פ בכלי דוקא מטעם הנ\"ל, ועשה ה' חסד בלידת [משה] שלמעלה מבחי' או\"פ בכלי (שלזה א' כבד פה אנכי<sup data-n=\"1521\">427</sup> כו') ע\"כ הי' לבן לבת פרעה כמ\"ש ותרד בת פרעה כו' עד ויהי לה לבן, שאע\"פ שידעו שהוא מילדי העברים<sup data-n=\"1522\">428</sup> גדלוהו בבית פרעה כמ\"ש ויגדל משה<sup data-n=\"1523\">429</sup> כו' ולא חששו אליו כלל לפי שידע פרעה וביתו [ש]שרשו למעלה בבחי' מקיף העליון שלמעלה מעלה מכל ההשתלשלו' דאו\"כ כו' ששם גם הם יכולים לקבל יניקה ושפע מטעם הנ\"ל. וזה הי' חסד ה' ונפלאותיו כדי שע\"י משה דוקא יצאו בנ\"י ממצרים ונתן להם תומ\"צ וכו' וינצלו את מצרים כו'.\n<b>וביאור</b> הענין הוא כידוע בהפרש שבין מ\"ת למ\"ע<sup data-n=\"1524\">430</sup> הוא בהבדלת הרקיע כמ\"ש יהי רקיע בתוך המים ויהי מבדיל בין<sup data-n=\"1525\">431</sup> כו' והן ב' מדרגות שבחכמה, א' בבחי' אין כח מ\"ה",[["1509","415","<b>עשה להם בתים</b>: ראה רשב\"ם־ חזקוני־ רבעה\"ת־ ר' חיים פלטיאל־ רבינו בחיי שמות א, כא."],["1510","416","<b>ויכל אלקים</b>: בראשית ב, ב."],["1511","417","<b>בראשית ברא אלקים</b>: שם א, א."],["1512","418","<b>ויאמר אלקים</b>: בראשית שם, ג. ג: וירא אלקים — שם שם, ד."],["1513","419","<b>עלי' דאו\"ח דמע\"ב</b>: ראה גם סידור עניני סעודת שבת קעד, ג. שער התקיעות רמב, ד."],["1514","420","<b>ויכל ל' תענוג</b>: ראה גם מאמרי אדה\"ז תקס\"ט ע' לה. שעה\"י קלד, ב ובהערה 43. מאמרי אדה\"א נ\"ך ע' קמח. לקמן פ' יתרו רסו, א."],["1515","421","<b>וד\"ל</b>: אוצ\"ל: וד\"ל)."],["1516","422","<b>ששרשו</b>: ג: מפני שעולה."],["1517","423","<b>ויפרו וירבו מאד</b>: לשון הפסוק ויגש מז, כז."],["1518","424","<b>וינצלו את מצרים</b>: בא יב, לו."],["1519","425","<b>דוקא</b>: ח: ליתא."],["1520","426","<b>כי </b>[ח: ליתא]<b> מן המים משיתיהו</b>: שמות ב, י. ראה גם לקמן מג, א. וש\"נ."],["1521","427","<b>כבד פה אנכי</b>: שמות ד, י [בדילוג]."],["1522","428","<b>מילדי העברים</b>: שמות ב, ו."],["1523","429","<b>ויגדל משה</b>: שמות ב, יא."],["1524","430","<b>מ\"ת למ\"ע</b>: גדח: מ\"ע למ\"ת."],["1525","431","<b>יהי רקיע. . בין </b>[גדח: ליתא]: בראשית א, ו."]]],[2300540755,"וזהו מ\"ש<sup data-n=\"1526\">432</sup> מ\"ה שמו<sup data-n=\"1527\">433</sup> כו' והוא בבחי' מ\"ע שממעל לרקיע, והב' בחי' היש דחכ' כשבא מאין ליש דבינה כמו חכמה דמע\"ב דאבא א' לאימא<sup data-n=\"1528\">434</sup> כמ\"ש בראשית ברא אלקי' כו', וכמ\"ש במ\"א בענין אור מים רקיע דמקור ושרש הראשון וחכ'<sup data-n=\"1529\">435</sup> הוא בבחי' אור כמ\"ש יהי אור<sup data-n=\"1530\">436</sup> ויהי אור<sup data-n=\"1531\">437</sup> והוא בחי' חכ' דא\"ס עצמו דלתבונתו<sup data-n=\"1532\">438</sup> אין מספר<sup data-n=\"1533\">439</sup> שכלולה במהו\"ע ממש (כמשל נפש השכלי' עצמה כו'), ומשם נמשך ובא בבחי' התפעלות<sup data-n=\"1534\">440</sup> והוא ח\"ע דתורה הקדומה שנק' ים הקדמוני<sup data-n=\"1535\">441</sup> או מים עליונים<sup data-n=\"1536\">442</sup> ושם הוא שרש נשמת משה שנא' בו כי<sup data-n=\"1537\">443</sup> מן המים משיתיהו מבחי' מ\"ע דוקא, וזהו למעלה הרבה גם מבחי' נהר שיוצא מעדן העליון<sup data-n=\"1538\">444</sup> הנ\"ל שהרי הנהר הזה הוא בבחי' מ\"ת שלאחר הבדלת הרקיע כו', והיינו כאשר החכמה באה מאין הנעלם לבחי' יש וע\"כ נק' בשם נהר עכ\"פ כמו המים המקובצים בנהר שהן במציאות דבר מה כמקוה המים שנקבצים בכלי שמגביל אותם, ואע\"פ שהמים עצמן אין להם גוון<sup data-n=\"1539\">445</sup> עצמי רק לפי הכלי אבל בהיותן נמשכים והולכים בנהר ניכרים במציאות דבר מה ובהגבלה דבחי' יש כו', רק כמו שהמים בשרשם למעלה בבחי' הרוחני' ממש אין להם גוון כו'<sup data-n=\"1540\">446</sup> רק בחי' היולי פשוט בתכלית (כמו כח המשכיל כל שכל כו' והוא בחי' מ\"ע הנ\"ל (שע\"ז א' ר\"ע כשתגיעו<sup data-n=\"1541\">447</sup> לאבני שיש טהור אל תאמרו מים מים מפני שהוא בחי' טה\"ע כו'). וז\"ש במשה ותרא אותו כי טוב<sup data-n=\"1542\">448</sup> הוא והאור נק' טוב<sup data-n=\"1543\">449</sup> כמ\"ש וירא אלקים את האור כי טוב כו' והוא<sup data-n=\"1544\">450</sup> בטי\"ת רבתי<sup data-n=\"1545\">451</sup> מבחי' רב טוב העליון שהוא [ב]תענוג הפשוט שבח\"ע הפשוט[ה] בתכלית כו' שהוא למעלה מעלה מכל ההשתלשלו' שנמשך בנהר שיוצא מעדן כו' וד\"ל. ושם יכולים הכל לקבל גם מי שאינו ראוי כראוי, להיותו בבחי' רב חסד העליון שהוא בחי' מ\"ע שמתפשט בלי שיעור כלל, והוא בחי' רב חסד דבי' אחיד אבא<sup data-n=\"1546\">452</sup> כו' שהוא למעלה מבחי' נוצר חסד כו', דנוצר אותיות צנור<sup data-n=\"1547\">453</sup> ואותיות רצון<sup data-n=\"1548\">454</sup> שזהו רק בחי' המשכה וצמצום אור השפע מכתר לחכ' כידוע דאור אבא יונק ממזל הח'<sup data-n=\"1549\">455</sup> ונוצר שהוא <span data-k=\"pg\">102</span> ּ מזל דא\"א כו', וזהו הבא למטה בבחי' מדה ושיעור דוקא",[["1526","432","<b>מ\"ש</b>: גדח: משה."],["1527","433","<b>מה שמו</b>: נסמן לקמן מג, ד."],["1528","434","<b>דאבא א' לאימא</b>: נסמן לעיל יח, ד."],["1529","435","<b>וחכ'</b>: גח: לחכ'. ד: דחכ'."],["1530","436","<b>יהי אור</b>: בראשית א, ג. ראה פרדס (שער טעם האצילות) ש\"ב, ספ\"ד. זהר בראשית ל, ב. תרומה קסז, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301550086\" data-slug=\"likkutei-sichot\" data-id=\"1301550086\">לקו\"ש דברים (כרך לד) ע' 15</a> הערה 42. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670072\" data-slug=\"torat-chaim\" data-id=\"2300670072\">תו\"ח בראשית ז, ד</a> הערה 50. סידור שחרית ע, א. מאמרי אדה\"א ויקרא ח\"ב ע' תע."],["1531","437","<b>ויהי אור</b>: ד: ליתא."],["1532","438","<b>דלתבונתו</b>: ג: ליתא."],["1533","439","<b>אין מספר</b>: ג: ליתא. ח: כו'."],["1534","440","<b>התפעלות</b>: גדח: התפשטות."],["1535","441","<b>דתורה. . ים הקדמוני</b>: ראה גם לקמן פ' בשלח קנט, ג. מאמרי אדה\"א דברים ח\"ד ע' א'תיח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670264\" data-slug=\"torat-chaim\" data-id=\"2300670264\">תו\"ח נח סב, ג</a> ובהערה 23. שם מקץ רכח, ג. שה\"א פו, א ובהערה 1."],["1536","442","<b>דתורה. . מים עליונים</b>: ראה גם מאמרי אדה\"א בראשית ע' קכג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540685\" data-slug=\"torat-chaim\" data-id=\"2300540685\">תו\"ח</a> מקץ שם. לקמן פ' וארא עט, ד."],["1537","443","<b>כי</b>: ג: ליתא."],["1538","444","<b>העליון</b>: גח: ליתא."],["1539","445","<b>שהמים. . גוון</b>: ראה פרדס (שער עצמות וכלים) ש\"ד, פ\"ד."],["1540","446","<b>כו'</b>: ח: כלל."],["1541","447","<b>א' ר\"ע כשתגיעו</b>: ראה חגיגה יד, ב. מאמרי אדה\"א במדבר ח\"ב ע' תשיט. דברים ח\"ג ע' א'ז ובהנסמן שם. ח\"ד ע' א'תיב."],["1542","448","<b>ותרא אותו כי טוב</b>: שמות ב, ב."],["1543","449","<b>והאור נק' טוב</b>: ראה גם ב\"ר פצ\"ב, ו."],["1544","450","<b>והאור. . והוא</b>: ד: ליתא. ואולי נשמט מפני תיבות הדומות: הוא. . והוא."],["1545","451","<b>במשה. . בטי\"ת רבתי</b>: נסמן לקמן מג, ד."],["1546","452","<b>רב חסד דבי' אחיד אבא</b>: ראה ע\"ח (שער או\"א) שי\"ד, פ\"א."],["1547","453","<b>נוצר חסד. . צנור</b>: נסמן לעיל יב, ב."],["1548","454","<b>דנוצר. . ואותיות רצון</b>: נסמן לעיל כו, ד."],["1549","455","<b>אור אבא יונק ממזל הח'</b>: ראה זהר (אד\"ז) האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקעד־ קונטרסים ע' תקנז. לקמן פ' בא קלא, א."]]],[2300540767,"וכמ\"ש והחכ' מאין תמצא ליש ובחי'<sup data-n=\"1550\">456</sup> מי מדד בשעלו מים<sup data-n=\"1551\">457</sup> כו' (והוא מים דאורייתא שנעשים במדה דוקא אבל בשרש החכ' דתורה הקדומה נאמר בה ארוכה מארץ מדה<sup data-n=\"1552\">458</sup> ורחבה מני ים ונק' ים הקדמוני כנ\"ל), אבל בחי' רב חסד העליון<sup data-n=\"1553\">459</sup> היינו בחי' עצמות<sup data-n=\"1554\">460</sup> החסד ורב טוב העליון שבאה מעצמות המאציל בפנימי' הכתר שהוא בחי' עדן העליון עצמו טרם שנמשך לנהר כו' ושם הכל יכולים לקבל גם מי שאינו ראוי כראוי כו', והוא ענין ועובר על פשע<sup data-n=\"1555\">461</sup> שזהו בבחי' רב חסד ארך<sup data-n=\"1556\">462</sup> אפים לכל<sup data-n=\"1557\">463</sup> לרעים כמו לטובים ממש וכמו אם צדקת כו' ואם רבו פשעיך<sup data-n=\"1558\">464</sup> כו' להיותו ברוממות העצמות ממש דכולא קמי'<sup data-n=\"1559\">465</sup> כו' כחשיכה כאורה כו' כנ\"ל באריכות וד\"ל. וזהו ענין סיבת גידולו של משה בבית פרעה דוקא הגם שהי' מילדי העברים כו' וכמו שסיפר בסיבת הדבר שהוא מ\"ש ותרד בת פרעה העליון לרחוץ על היאור דנהר נילוס כו' עד ותפתח את התיבה<sup data-n=\"1560\">466</sup> כו' ותאמר מילדי העברים הוא<sup data-n=\"1561\">467</sup>, אך עכ\"ז לפי שהכירה בשרש נשמתו שהוא מבחי' מ\"ע לקחה אותו לה לבן כנ\"ל לפי שמצד רוממות שרש נשמת משה כנ\"ל הי' יכול להיות גם לבת פרעה לבן שהוא בבחי' או\"פ בכלי בבחי' בנין כנ\"ל בענין זכר חסדו כו', לפי שממנו יכולים הכל לקבל גם בת פרעה כו' וע\"כ ויהי לה לבן ממש מאחר שהוא למעלה מעלה מכל ההשתלשלות דשם כחשיכה כאורה כו' וע\"כ גדלתו בבית פרעה ולא חששו עליו כלל מטעם הנ\"ל וד\"ל. וגם מצד עצמו<sup data-n=\"1562\">468</sup> שראו אותו שהוא כבד פה וכבד לשון כו' שזהו הוראה גמורה על שרש נשמתו למעלה שהוא מבחי' מ\"ע דח\"ע שלמעלה מהגבלה בכלי לגמרי ע\"כ לא הי' לו בחי' כלי בפה בדבור כלל ([ו]עד\"מ<sup data-n=\"1563\">469</sup> העומד<sup data-n=\"1564\">470</sup> לפני המלך שאז לא יוכל לספר ברוממות המלך עד אחר שיצא מהיכל המלך שאח\"כ יספר לזולתו עצם רוממות וגדלות המלך שראה בעודו שם כו' והנמשל מובן ממילא כו') וד\"ל.",[["1550","456","<b>ובחי'</b>: ג: וכמו. דח: וכתי'."],["1551","457","<b>מי מדד בשעלו מים</b>: ישעי' מ, יב."],["1552","458","<b>ארוכה מארץ מדה</b>: איוב יא, ט. ראה גם לקמן פ' בשלח קעג, ב. וש\"נ."],["1553","459","<b>העליון</b>: גדח: ליתא."],["1554","460","<b>עצמות</b>: ג: עצמיות. ח: ליתא."],["1555","461","<b>ועובר על פשע</b>: מיכה ז, יח."],["1556","462","<b>ארך</b>: גח: וארך. ד: דא\"א."],["1557","463","<b>אפים לכל</b>: ד: ליתא. וראה הערה שלפנ\"ז."],["1558","464","<b>ואם רבו פשעיך</b>: איוב לה, ו [ושם: אם. . ורבו פשעיך — ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשעו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670223\" data-slug=\"torat-chaim\" data-id=\"2300670223\">תו\"ח וירא ק, א</a> הערה 10]."],["1559","465","<b>דכולא קמי'</b>: נסמן לקמן לח, א."],["1560","466","<b>ותפתח את התיבה</b>: שמות ב, ו."],["1561","467","<b>הוא</b>: ד: זה."],["1562","468","<b>עצמו</b>: דח: ליתא."],["1563","469","<b>[ו]עד\"מ</b>: י: ניתוסף: וד\"ל. יא: מחק תיבת עד\"מ וכתב: כנ\"ל וד\"ל. ועה\"ג רשם: עכ\"מ ע\"כ מצאתי. וראה הנרשם ברשימת הכת\"י כאן."],["1564","470","<b>העומד</b>: מכאן ואילך ניתוסף מבוך ד."]]],[2300540047,"<b>בעזה\"ש ליל שבת פ' וארא</b>\n<span data-k=\"pg\">נא</span> ּ<b>להבין</b> כללות ענין האותות והמופתים<sup data-n=\"1565\">1</sup> שהי' במצרים כו' וענין המטה שהי' לתנין<sup data-n=\"1566\">2</sup> כו' הנה כתיב וינצלו את מצרים<sup data-n=\"1567\">3</sup> כמצולה כו' או כמצודה כו' כידוע, וע\"ד הקבלה<sup data-n=\"1568\">4</sup> הנה זה הי' ענין בירורי רפ\"ח ניצוצי'<sup data-n=\"1569\">5</sup> שנפלו אז במצרים והם ביררו והעלו אותם מכל וכל מקליפת מצרים עד שעשו אותם<sup data-n=\"1570\">6</sup> כמצולה וד\"ל. וביאור הדברים הנה תחלה יש להקדים משל א' לענין הבירורים הנ\"ל, והוא ע\"ד שאנו רואים בנשמת האדם שהיא מלובשת בחומר הגופני הנה בעודינה שהיתה [ק]שורה באוא\"ס ב\"ה קודם ירידתה להתלבש בגוף ידוע שהיתה בתכלית בחי' הביטול באוא\"ס בלתי העלם וצמצום כלל וגם מהמלאכים היתה גבוה במדרגה כו', ואחר שירדה ונתלבשה בגוף החומרי הרי נעשית בזה בבחי' פירוד גדול מאוא\"ס<sup data-n=\"1571\">7</sup> כאלו לא היתה מעולם קשורה למעלה בבחי' הביטול כו'. והוא מפני שחומר הגופני המלבישה הנה הוא המסתיר ומעלים ממנה אוא\"ס לבלתי הגלות נגלות בה כמקדם כו', וא\"כ אנו רואים שמסיבת חומר מחשך<sup data-n=\"1572\">8</sup> הגוף גם הנשמה האלקי' שמסתתרת בו נעשי' בבחי' נפרד ממש כו' היפך ממש מכמו שהיתה במקור חוצבה למעלה כו' וד\"ל. ועד\"ז יובן ג\"כ בכללות הנשמת שירדו מלמעלה כדי להתברר למטה בהיות ידוע הפסוק ונהר יוצא מעדן כו' ומשם יפרד והי' לד' ראשים<sup data-n=\"1573\">9</sup> כו', הענין<sup data-n=\"1574\">10</sup> הוא דפי' נהר הוא ענין המשכה שהוא בחי' התפשטות השפע כמ\"ש ונהרו אליו כל הגוים<sup data-n=\"1575\">11</sup> כו'. והנה בתחלת ההמשכה וההתפשטו' מאור המאציל העליון עדיין לא הי' בבחי' התחלקות ההמשכה לחלקים רבים כו', אלא היתה בבחי' היחוד וההתכללות בתכלית עד שלא הי' רק בחי' המשכה ושפע א' בלבד והוא מ\"ש ונהר יוצא מעדן<sup data-n=\"1576\">12</sup> כו' נהר א' בלבד והוא הכולל הרבה מיני המשכות והשפעות יחד כו', ואע\"פ שהנהר הזה כבר יצא מעדן העליון עכ\"ז הי' בתכלית היחוד, ומכ\"ש וק\"ו בבחי' עדן העליון עצמו שלמעלה<sup data-n=\"1577\">13</sup> שהיחוד שם יותר ויותר כו', ואחר שנמשך הנהר הזה הכללי הנה מפני שכבר נתרחק מאור המאציל לכך משם יפרד עוד בבחי' פירוד והתחלקות יותר והוא ההתחלקות לד' נהרות ד' המשכות כו'",[["1565","1","<b>להבין כללות ענין האותות והמופתים</b>: מאמר זה הוא מכ\"ק אדה\"ז מליל שבת פ' וארא תקס\"ה ונרשם בשעתו ע\"י כ\"ק אדה\"א. ובתוס' ביאור ראה המאמר שנדפס לאח\"ז (פ\"ד ואילך). והנחת הר\"מ בן כ\"ק אדה\"ז נדפסה במאמרי אדה\"ז תקס\"ה ח\"א ע' קפח [ושם מתחיל: ויאמר ה' אל משה לאמר כי ידבר אליכם פרעה תנו לכם מופת ואמרת אל אהרן קח את מטך והשלך לפני פרעה יהי לתנין]. ובשינויים נדפס ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370254\" data-slug=\"torah-or\" data-id=\"3901370254\">תו\"א וארא נו, ד</a> [ושם: ההתחלה: ויאמר ה' אל משה ואל אהרן לאמר כו' קח את מטך והשלך לפני פרעה יהי לתנין כו' עד ויבלע מטה אהרן את מטתם]. ועם הגהות וכו' באוה\"ת וארא [כרך ז] ע' ב'תרו. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["1566","2","<b>המטה שהי' לתנין</b>: וארא ז, ט ואילך."],["1567","3","<b>וינצלו את מצרים</b>: בא יב, לו. בתו\"א ואוה\"ת כאן מציין לפסחים קיט, א. וראה ברכות ט, ב."],["1568","4","<b>וע\"ד הקבלה</b>: ראה פע\"ח (שער הק\"ש) ש\"ח, פ\"ג. מ\"ע אופן רנ. עמה\"מ שער עולם התהו פמ\"ג (כד, א). שער קרית ארבע פקי\"ז (קיא, ג). לקו\"ת וספר הליקוטים ר\"פ תצא."],["1569","5","<b>רפ\"ח ניצוצי'</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ב. שע\"ת צה, ד הערה 46. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["1570","6","<b>שעשו אותם</b>: בג: שעשו אותה. אבל במאמרים שנסמנו בריש המאמר שעשאום."],["1571","7","<b>אוא\"ס</b>: ג: ניתוסף: ב\"ה."],["1572","8","<b>מחשך</b>: ב: חשך."],["1573","9","<b>ונהר יוצא. . ראשים</b>: בראשית ב, י. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680129\" data-slug=\"torat-chaim\" data-id=\"2300680129\">תו\"ח וישב רו, א</a> ואילך. לעיל כו, ג."],["1574","10","<b>הענין</b>: ב: והענין."],["1575","11","<b>ונהרו אליו כל הגוים</b>: ישעי' ב, ב ובמפרשים שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו, יז, א</a>."],["1576","12","<b>מעדן</b>: בגד: ליתא."],["1577","13","<b>שלמעלה</b>: בד: ניתוסף: הימנו."]]],[2300540085,"וד\"ל. והנה עד\"מ בנהר הגשמי אנו רואים שיש שיעור למהלכו ק' או ר' פרסאות עד שיכלה שפע המשכתן<sup data-n=\"1578\">14</sup> וזה יכלה בסך כמה פרסאות יותר כו' ועד\"ז הי' ג\"כ ברוחני' שפע המשכת הנהרות שיצא מנהר העליון שיצא מעדן, זה בכח שפע המשכה כך וכך וזה בכח רב ממנו, דהיינו שכלות שפעו יומשך יותר כו' וד\"ל. ועתה יובן ענין הבירורים הנ\"ל בהיות שירדו כללות הניצוצי' שנפלו מלמעלה מעלה דהיינו מבחי' התהו מלפני מלוך מלך<sup data-n=\"1579\">15</sup> כו' להתברר למטה כו' הנה יצאו דרך הד' נהרות הנ\"ל שיצאו מעדן העליון דהיינו שנתלבשו הניצוצות בנהרות הנ\"ל כדי להתברר וד\"ל. והענין הוא עד\"מ כמו התלבשות הנשמה האלקי' בגוף שנעשית בבחי' נפרד כנ\"ל כמ\"כ בחי' רפ\"ח ניצוצין דתהו (שנא' עליהם ורוח אלקים מרחפת רפ\"ח מ\"ת<sup data-n=\"1580\">16</sup> כו' וכמ\"ש במ\"א) כאשר ירדו למטה<sup data-n=\"1581\">17</sup> ונתלבשו בנהרות הנ\"ל שאז נעשים בבחי' נפרד כו' וד\"ל. כי הרי<sup data-n=\"1582\">18</sup> הנהרות המה היורדים להתפרד עוד למטה מטה עד בחי' הפירוד <span data-k=\"pg\">104</span> ּ הגמור שהן שרשי יניקות הד' מלכיות<sup data-n=\"1583\">19</sup> מצרים<sup data-n=\"1584\">20</sup> ובבל כו' כידוע והוא נגד בחי' ארמ\"ע<sup data-n=\"1585\">21</sup> כו' כמ\"ש בס' הקבלה וד\"ל. וא\"כ כאשר ירדו הניצוצים בנהר שיצא מעדן עדיין הי' בבחי' היחוד כנ\"ל, אך משם יפרדו כו' וירדו להיות בבחי' נפרד ממש כדוגמת התלבשות הנשמה בגוף כנ\"ל וד\"ל. וענין כחות יציאות הנהרות כמו שהי' במדה זה כך וזה כך כו' כמו\"כ בחי' התלבשות הניצוצות בהם הי' ג\"כ במדה, לנהר מצרים שהוא פישון<sup data-n=\"1586\">22</sup> כו' ירדו בו כ\"כ נשמות וניצוצות דתהו ולנהר דבבל כ\"כ ניצוצות כו' בכאו\"א לפום<sup data-n=\"1587\">23</sup> שיעור מהלכו בארץ העליונה כו' וד\"ל.\n<b>והנה</b> עיקר הירידה דניצוצות הנ\"ל היתה לצורך עלי' דוקא כידוע, והיינו שבחי' ירידת רפ\"ח ניצוצו' היתה כדי שיבואו לידי בחי' עילוי ביותר מכמו שהי' קודם ירידתו<sup data-n=\"1588\">24</sup> בנהרות הנ\"ל, וע\"ד דוגמא של ירידת הנשמה בגופו<sup data-n=\"1589\">25</sup> שהוא ג\"כ לצורך עלי' דהיינו שתתעלה הנפש האלקי' במדרגה הגבוה יותר מכמו שהיתה תחלה קשורה במקור חוצבה כו' והוא ע\"י בחי' תשובה דוקא כידוע והטעם הוא לפי שארז\"ל ז' דברים קדמו לעולם וא' מהם תשובה<sup data-n=\"1590\">26</sup> כו'. והענין הוא",[["1578","14","<b>המשכתן</b>: בג: המשכתו."],["1579","15","<b>מלפני מלוך מלך</b>: וישלח לו, לא."],["1580","16","<b>ורוח אלקים מרחפת רפ\"ח מ\"ת</b>: בראשית א, ב. ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' א ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680160\" data-slug=\"torat-chaim\" data-id=\"2300680160\">תו\"ח וישב רו, ג</a> הערה 21."],["1581","17","<b>למטה</b>: ב: ניתוסף: להתברר."],["1582","18","<b>הרי</b>: בג: ליתא."],["1583","19","<b>הנהרות. . הד' מלכיות</b>: ראה ב\"ר פט\"ז, ד. יל\"ש בראשית ב, יד (רמז כב) ושם: מלכיות."],["1584","20","<b>הד' מלכיות מצרים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161091\" data-slug=\"likkutei-sichot\" data-id=\"1300161091\">לקו\"ש וארא (כרך טז) ע' 91</a>."],["1585","21","<b>נגד בחי' ארמ\"ע</b>: במאמרי אדה\"ז תקס\"ה כאן (ע' קפט) ובאוה\"ת כאן (ע' ב'תרז) בזהר — ראה זהר בראשית כז, א."],["1586","22","<b>לנהר מצרים שהוא פישון</b>: רש\"י בראשית ב, יא. ראה הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תשח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680469\" data-slug=\"torat-chaim\" data-id=\"2300680469\">תו\"ח מקץ רכט, ב</a> הערה 18."],["1587","23","<b>לפום</b>: בגד: לפי."],["1588","24","<b>ירידתו</b>: גד: ירידתן."],["1589","25","<b>בגופו</b>: בג: בגוף. ד: בגופה."],["1590","26","<b>ז' דברים. . תשובה</b>: ראה פסחים נד, א. מאמרי אדה\"א דברים ח\"ד ע' א'קסד. וש\"נ."]]],[2300540123,"דצדיקים המה הממשיכים האורות בכלים ע\"י מע\"ט שלהם כידוע, אבל בע\"ת דמשכין לי' לקוב\"ה בחילא יתיר<sup data-n=\"1591\">27</sup> כו' היינו שמעוררי' למעלה מעלה מבחי' הקו\"ח שנמשך ומאיר האורות בכלים כו', ומה שלמעלה מבחי' הכלים ידוע שהוא בחי' מטי ולא מטי<sup data-n=\"1592\">29</sup> עדיין כלומר שעדיין אין אוא\"ס ב\"ה יורד ומאיר בנאצלים אלא הוא בבחי' הסתלקות וצמצום בעצמותו עדיין והוא לא מטי עד שאח\"כ יוכל להשפיל את אורו [ו]להאיר בבחי' הקו\"ח הנ\"ל כו' כמ\"ש בע\"ח<sup data-n=\"1593\">28</sup> כו'<sup data-n=\"1594\">30</sup> וד\"ל. וזהו בחי' התשובה ג\"כ כי בחי' תשובה הוא בחי' או\"ח כו' כידוע, וזהו פי' תשובה תשוב ה'<sup data-n=\"1595\">31</sup> דהיינו שתשוב האור<sup data-n=\"1596\">32</sup> ותחזור למקורה כו' והוא בחי' לא מטי כו' וד\"ל. ואין זה למעלה אלא ע\"י בחי' בכל מאדך כו' דבע\"ת למטה כו' לפי שהוא למעלה מבחי' הכלים כו' כמ\"כ מעורר למעלה ג\"כ מבחי' מולמ\"ט שהוא למעלה מבחי' האורות שבכלים וד\"ל. ובזה יובן הטעם שלא זכה משה לתשובה<sup data-n=\"1597\">33</sup> אלא קודם מותו אחרי שנצח מלכי עבר הירדן שאז נא' אז יבדיל משה<sup data-n=\"1598\">34</sup> שלש ערים כו' וכמ\"ש בר\"מ ע\"פ ושמתי לך מקום<sup data-n=\"1599\">35</sup> אשר ינוס כו' לך למשה דהיינו שבא והגיע לבחי' התשובה אז דוקא, מפני שהתשובה קדמה לעולם אפי' מעולם הנאצל[ים] דהיינו בחי' מטולמ\"ט הנ\"ל כי הגם שהי' משה צדיק גמור וגדול מכל הצדיקי' לא המשיך למעלה רק בבחי' הקו\"ח ולא למעלה הימנו עד שזכה לתשובה קודם מותו והגיע למדריגה שלמעלה מבחי' הקו\"ח כו' וד\"ל. והנה ארז\"ל ז' דברים קדמו לעולם ותשובה א' מהם וגם שמו של משיח א' מהם והוא לפי שנא' עליו ישכיל עבדי<sup data-n=\"1600\">36</sup> ירום ונשא וגבה מאד דהיינו ע\"י בחי' התשובה שאם ישראל עושין תשובה נגאלין<sup data-n=\"1601\">37</sup> כו' ה\"ז<sup data-n=\"1602\">38</sup> יהי' במעלה ומדריגה גבוה גם ממדריגת משה שהרי נא' בו מאד דהיינו גם ממשה שנא' בו מאד והאיש משה עניו מאד<sup data-n=\"1603\">39</sup> וד\"ל<sup data-n=\"1604\">40</sup>.\n<b>ובכל</b> הנ\"ל יובן הפסוק בשוב ה' את שיבת ציון כו' אז יאמרו בגוים<sup data-n=\"1605\">41</sup> הגדיל ה' לעשות עם אלה פי' בגוים דוקא יאמרו כו' לפי שמבואר למעלה בענין הד' נהרות שמשם יפרד למטה מטה כו' עד שנעשו שרשי' לד' מלכיות כו' ובהיות שירדו בחי' הניצוצות דתוהו ונתלבשו בהם בבחי' הברורי' דהיינו דירידה זו לצורך עלי' היא ע\"י התשובה דוקא כנ\"ל וא\"כ שהגדיל<sup data-n=\"1606\">42</sup> הוי'",[["1591","27","<b>בע\"ת. . בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. לקמן מא, א. פ' וארא סה, ד. בא קיא, ג. בשלח קעו, ד. יתרו רסו, ג. מאמרי אדה\"ז תקס\"ד ע' קמה. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. שע\"ת ח\"א כט, ד ובהנסמן במ\"מ לשם. ש\"א ט, ב."],["1592","29","<b>מטי ולא מטי</b>: נסמן לקמן מא, א."],["1593","28","<b>שלמעלה מבחי' הכלים. . מטי. . בע\"ח</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ג. מאמרי אדה\"ז אתהלך לאזניא ע' רכב."],["1594","30","<b>כו'</b>: בגד: ליתא."],["1595","31","<b>תשובה תשוב ה'</b>: ראה זהר (רע\"מ) נשא קכב, א."],["1596","32","<b>שתשוב האור</b>: בג: שהאור תשוב."],["1597","33","<b>זכה משה לתשובה</b>: ראה זהר (רע\"מ) משפטים קיד, ב. תצא רעח, ב. מאמרי אדה\"א ויקרא ח\"א ע' שיב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670173\" data-slug=\"torat-chaim\" data-id=\"2300670173\">תו\"ח נח סא, א</a> ובהערה 2. לקמן מא, א. פ' וארא סה, ד. בשלח קס, ב. קעז, ב. תצוה שמג, ד."],["1598","34","<b>אז יבדיל משה</b>: ואתחנן ד, מא."],["1599","35","<b>ושמתי לך מקום</b>: משפטים כא, יג."],["1600","36","<b>משיח. . ישכיל עבדי</b>: נסמן לקמן מג, ד."],["1601","37","<b>שאם ישראל עושין תשובה נגאלין</b>: ראה סנהדרין צז, סע\"ב. לקמן פ' וארא סה, ד. פקודי תנז, ד. מאמרי אדה\"א דברים ח\"א ע' א ואילך. תו\"ח ויצא קסו, ב ובהערה 17."],["1602","38","<b>ה\"ז</b>: בגד: ולכך."],["1603","39","<b>והאיש משה עניו מאד</b>: בהעלותך יב, ג."],["1604","40","<b>וד\"ל</b>: ע\"כ נמצא בתו\"ח. מכאן ואילך נדפס מבוך ד."],["1605","41","<b>בשוב ה'. . אז יאמרו בגוים</b>: תהלים קכו, א-ב. — בליל שבת זה נאמרו ב' דרושים ד\"ה זה וד\"ה שיר המעלות בשוב שנאמר לפנ\"ז — נדפס במאמרי אדה\"ז תקס\"ה (הנחת הר\"מ) ע' קפד וב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370133\" data-slug=\"torah-or\" data-id=\"3901370133\">תו\"א פ' וישב כח, ג</a>. ענין זה מובא במאמרי אדה\"ז שם ע' קפז."],["1606","42","<b>שהגדיל</b>: ג: מה שהגדיל."]]],[2300540161,"לעשות בניצוצו' הללו לא הי' רק מפני סיבת ההתלבשות שלהם בד' נהרות הנ\"ל שרש וראש להגוים וא\"כ<sup data-n=\"1607\">43</sup> יחרה מאד לגוים שאמרם שמתוכם ועל ידם היתה יתרון האור בזה ועשו אותם כמצולה כו' [ו]לכך אז יאמרו בגוים דוקא הגדיל ה' לעשות [עם] אלה [כו'] פי' כי ע\"י הגוים נעשה זה לכך הם דוקא אשר יאמרו זאת ויתפעלו<sup data-n=\"1608\">44</sup> מאד ולא זולתם וד\"ל.\n<b>ועם</b> כל הנ\"ל יובן שורש ענין האותות והמופתים שהיו במצרים כו', כי הנה מבואר למעלה דעד\"מ התלבשות הנשמה בגוף כן ירידות אורות וניצוצים העליוני' בד' מלכיות דשעבוד הגליות כדי להתברר ולהיות מזה יתרון אור בהם הרבה, כי הנה עד\"מ הפרי כמו האגוז וכדומה אשר בקליפתה היא מכוסה ונעלמה מאד בשביל שתתברר בה ותצא ממנה כל פסולתה ותהי' נקי' בתכלית ובתכלית הטעם והטוב משא\"כ בלתי קליפה סביב לה כו', וכאשר יוגמר הפרי בשלימות הבירור אז צריכי' לשבר הקליפה הסביב לה ולהוציא הטוב הגנוז בה שהוא הפרי ובלעדי זאת השבירה לא הי' באפשרי להגיע לטוב טעם הפרי וכו'. והנמשל יובן בהיות שבחי' רפ\"ח ניצוצות שנתלבשו בד' מלכיות כנ\"ל ה\"ז כדוגמת התלבשות הפרי בקליפה כדי שיתברר בכי טוב כו' וכנ\"ל שירידה זו לצורך עלי' היתה כו' ואמנם לאחר שנשלם הבירור שלהם וצריך שיתגלו לחוץ צריכי' לשבור הקליפה שלהם והוא קליפות מצרי\"ם מצ\"ר<sup data-n=\"1609\">45</sup> מ\"י<sup data-n=\"1610\">46</sup> כו' שתשבר בתחלה ואז יתגלו הניצוצות כו'. והשבירה היתה בענין האותות והמופתי' שהיו במצרי', שהרי האות והמופת הוא בחי' היפוך דרכי הטבע שהוא היפוך סדר ההשתלשלות דד' נהרות הנ\"ל כמו שנהפך היאור לדם וכדומה כו'. ובזה נשבר שרש יניקות קליפות מצרים למעלה ויצא האור הגנוז בהם שהן בחי' הניצוצות הנ\"ל, וזהו וינצלו את מצרי' כמצולה כו' או כמצודה והכל ענין אחד שנתברר מהם הטוב ונשארו ריקם מכל כו'. וזהו סוס ורוכבו רמה בים<sup data-n=\"1611\">47</sup> כו' פי' ורוכבו הם בחי' השרש שרשו<sup data-n=\"1612\">48</sup> מצרים הנק' רוכב ע\"ש שמלביש ורוכב על הטוב כו' וזהו מרכבות פרעה<sup data-n=\"1613\">49</sup> כו' וד\"ל.\n<b>והנה</b> האות<sup data-n=\"1614\">50</sup> הראשון הי' בהפיכת המטה לתנין<sup data-n=\"1615\">51</sup>, והענין הוא להורות בזה על כללות ירידת והתלבשות האורות בכלי'",[["1607","43","<b>וא\"כ</b>: בג: וע\"כ."],["1608","44","<b>ויתפעלו</b>: ג: ויתפלאו."],["1609","45","<b>מצרים מצ\"ר מ\"י</b>: לעיל יט, א מציין כמבואר בכוונות דעבדים היינו. ראה סידור האריז\"ל פיסקא עבדים היינו. פע\"ח (שער חה\"מ) שכ\"א, פ\"ז. לקמן פ' בא קא, ב. קי, ב. קכה, ד. בשלח קסד, א."],["1610","46","<b>מצ\"ר מ\"י</b>: ג: מצ\"ר י\"ם — נסמן בהערה שלפנ\"ז."],["1611","47","<b>סוס ורוכבו רמה בים</b>: בשלח טו, א. וראה גם שער האמונה לו, ב ובהערה 10. לקמן פ' בשלח קסט, א."],["1612","48","<b>שרשו</b>: ג: של שר."],["1613","49","<b>מרכבות פרעה</b>: בשלח שם, ד. ראה גם מאמרי אדה\"ז תקס\"ה כאן (ע' רצא)."],["1614","50","<b>האות</b>: וכ\"ה לקמן מא, ד (אבל ראה בהערה לשם). ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370255\" data-slug=\"torah-or\" data-id=\"3901370255\">תו\"א כאן (נז, סע\"א</a>) ובמאמרי אדה\"ז תקס\"ה כאן (ע' רצא): המופת."],["1615","51","<b>בהפיכת המטה לתנין</b>: וארא ז, ב ואילך."]]],[2300540198,"מכלי' שונים עד שמשם יפרד כו' לע' שרים<sup data-n=\"1616\">52</sup>, שאינו בבחי' פירוד ממש אלא עדיין אחוז וקשור באור המאציל בבלתי פירוד כלל, ואין לך דבר חוץ ממנו כלל כב' רשויות<sup data-n=\"1617\">53</sup> ח\"ו כו', והגם שמאד נתצמצם ונתלבש בכמה מיני ריבוי רבבות צמצוצי' כו'. וזהו ענין המטה שנהפך לתנין כו' פי' מטה הוא לשון הטיי'<sup data-n=\"1618\">54</sup> כמו מטה כלפי חסד<sup data-n=\"1619\">55</sup> והוא ענפי האילן שנוטין מן האילן למטה כו', וכן שבט מן הענף הוא ענין נטיי' פרטי' יותר כמו לשון שובט ומדקדק<sup data-n=\"1620\">56</sup> כו' וה\"ז כענין כוכבי דשביט<sup data-n=\"1621\">57</sup> כו', שכל אלה הוא ענין המשכה למטה כידוע. והראה להם משה שבחי' מט\"ה העליון דהיינו נטיי' והמשכו' האורות בכלי' מכלי' שוני' כו' יהפוך לתנין הוא הסתרו האחרון שיהי' לראש ולחיות לקליפות מצרים הנק' תנין כמ\"ש התנין הגדול הרובץ<sup data-n=\"1622\">58</sup> כו' כידוע, גם אז איננו בבחי' נפרד ממש ואע\"פ שיאמר לי יאורי<sup data-n=\"1623\">59</sup> כו' בחי' גסות רוחו וחוצפו כו' אלא הוא בטל ונעשה בחי' [מטה] ממש כמו שהוא למעלה בשרש שרשו בקדושה העליונה הנק' מטה וזה כשנהפוך תחילה לתנין ואח\"כ מתנין למטה להורות על שאינה בבחי' פירוד כלל אלא המטה עצמו הוא התנין והתנין הוא המטה [כו'] והכל א' כי הכל א' מפני שנכללי' גם הנפרדי' ביחודו ית' שהרי קרו לי' אלקא דאלקיי'<sup data-n=\"1624\">60</sup> כו' וד\"ל. ואעפ\"י שהחרטומי מצרים עשו כמ\"כ להפוך המטה לנחש<sup data-n=\"1625\">61</sup> כו', כי הראה להם עוד שאינן נפרדין בזה כלל והוא במה שבלע מטה אהרן<sup data-n=\"1626\">62</sup> את מטותם פי' גם בחי' המטה שלהם שהוא בחי' שורש שרשם בקדושה העליונה ניכללי' הם ומתייחדי' בבחי' הביטול במציאות ממש כו' בתוך מט\"ה אהר\"ן שהוא המטה הנכללת בקדושת ההמשכה הראשונה שעדיין בבחי' היחוד האמיתי כו' והוא כמו בחי' נה\"ר שיצא מעדן הנ\"ל וזה הנק' מטה אהרן כמ\"ש מט\"ה חס\"ד<sup data-n=\"1627\">63</sup> כלפי חסד שהחסד מדריגתו של אהר\"ן<sup data-n=\"1628\">64</sup> כו' וזהו ויבלע שבלעם וכללם בו כנ\"ל מטעם הנ\"ל וד\"ל.",[["1616","52","<b>לע' שרים</b>: ראה זהר בראשית מו, סע\"ב. סידור שער המילה קמה, ג. מכתב כ\"ב כסלו תשט\"ז נדפס באג\"ק חי\"ב ע' קסה ואילך. הנסמן במ\"מ לשערי תשובה עד, א."],["1617","53","<b>כב' רשויות</b>: חגיגה טו, א."],["1618","54","<b>מטה הוא לשון הטיי'</b>: ראה גם לקמן פ' בשלח קמז, ב. וש\"נ."],["1619","55","<b>מטה כלפי חסד</b>: ר\"ה יז, א."],["1620","56","<b>שובט ומדקדק</b>: ראה שבת עה, ב. צז, ב."],["1621","57","<b>כוכבי דשביט</b>: ברכות נח, ב."],["1622","58","<b>התנין הגדול הרובץ</b>: יחזקאל כט, ג [ושם: התנים וכ\"ה בתו\"א כאן. לקמן מב, א. אבל במאמרי אדה\"ז תקס\"ה כאן (ע' קצא) הובא כבפנים. וראה גם לקמן פ' וארא פב, ד הערה 703]."],["1623","59","<b>לי יאורי</b>: יחזקאל שם."],["1624","60","<b>קרו לי' אלקא דאלקיי'</b>: מנחות בסופה."],["1625","61","<b>שהחרטומי מצרים. . המטה לנחש</b>: וארא ז, יא-יב."],["1626","62","<b>שבלע מטה אהרן</b>: וארא שם, יב."],["1627","63","<b>חס\"ד</b>: בג: ליתא."],["1628","64","<b>שהחסד מדריגתו של אהר\"ן</b>: ראה ת\"י ברכה לג, ח. שמו\"ר פ\"ה, י. תנחומא שמות כח. מאמרי אדה\"ז תקס\"ה ח\"א ע' דש. מאמרי אדה\"א שמות ח\"ב ע' שלח. וש\"נ. לקמן מב, ד."]]],[2300540048,"<b>בעז\"ה שדרש אדמו\"ר שליט\"א בק' באברוייסק תקפ\"ב לפ\"ק </b>\nר\"ח טבת\n<span data-k=\"pg\">נב</span> ּ<b>ויאמר</b><sup data-n=\"1629\">1</sup> ה' אל משה<sup data-n=\"1630\">*2</sup> מזה בידך ויאמר מטה ויאמר השליכהו ארצה<sup data-n=\"1631\">2</sup> כו' ויהי לנחש כו'. הנה להבין ענין כללות האותות והמופתים שהי' במצרים וענין האות הראשון דהפיכת המטה לתנין ומתנין למטה כו', הנה יש להקדים כללות ענין הגלות שנק' שינה וכמ\"ש אני ישינה<sup data-n=\"1632\">3</sup> ולבי ער כו' ואי' בזהר אני ישינה בגלותא<sup data-n=\"1633\">4</sup> כו'. וזהו מ\"ש בשוב ה' את שיבת ציון<sup data-n=\"1634\">5</sup> היינו כחולמים, שכאשר ישיב ה' את שבות<sup data-n=\"1635\">6</sup> ציון יכירו על שהי' בגלות בבחי' שינה וזהו היינו כחולמים כו'. והנה עד\"מ החולם חלום אנו רואים שיחלום אדם בחלומותיו ענינים הפכים מן הקצה לקצה ובנושא אחד ממש, כמו שיחלום דבר שמחה ורוב טובה ונחמה מאיזה ענין מאורע כמו שנעשה לשר גדול או עשיר ומצליח, וברגע זו עצמה בא ענין החלום בהיפוכו שהוא ענין רע ו[דבר] עצב ביותר שנגע בו עד הנפש למות, וכה\"ג בעניני ביתו ובניו וזולתם יבא בחלום ענינים הפכים מחדוה לצער ומצער לחדוה דבר והיפוכו ממש שלא יכילנו השכל<sup data-n=\"1636\">7</sup> שיוכל להיות ב' הענינים כא' בזמן אחד (לבד ענין החלום עצמו שהוא כוזב ומגזם דבר שלא יוכל להיות כו' כמו פורח באויר וכה\"ג, מלבד עניני שטות<sup data-n=\"1637\">8</sup> הרבה שהי' מתבייש לספרם בדבור, הנה יבוא בחלום דבר והיפוכו כא'). אך הנה הגם שבא החלום בעניני[ם] הכוזבים מאד ובפרט בדבר והיפוכו בנושא אחד שהוא מן הנמנעות, מ\"מ אין זה שקר מעיקרו אלא כל ענין בפ\"ע יכול להיות אמת גמור [ו]הוא מפני שענין זה כבר הי' לעולמים [א]ו כיוצא בו הי' או בדוגמא דדוגמא עכ\"פ הי' הדבר בעולם, וגם ענין השני היפוכו יכול להיות אמת בפ\"ע שהוא ג\"כ הי' במציאות בעולם או מעין ודוגמא שלו, רק במה שבאו ב' הענינים סמוכים וחבורים יחד בענין סיפור אחד בחלום שהן ב' הפכים דסתרי אהדדי כנ\"ל, זה<sup data-n=\"1638\">9</sup> מכח החולם כל החלומות שהוא כח המדמה<sup data-n=\"1639\">10</sup> בשינה שהוא מחבר ומקשר כמה דברים וענינים הפכים מנגדים יחד בסיפור ענין אחד, אע\"פ שהן ב' הפכים בתכלית כו' (וכמו",[["1629","1","<b>ויאמר ה' אל משה מזה בידך</b>: מאמר זה מיוסד על שני מאמרים דלהלן: חלק ראשון של המאמר [עד אמצע פ\"ד — לקמן לט, ג] מיוסד על ד\"ה שיר המעלות דש\"פ וארא תקס\"ה. המאמר דתקס\"ה נמצא בג' נוסחאות א) הנחת כ\"ק אדה\"א [לא נדפסה לע\"ע ונמצאת בבוך 2076 ע' סו]. ב) <a class=\"ft-cite\" href=\"#/read/torah-or/3901370133\" data-slug=\"torah-or\" data-id=\"3901370133\">תו\"א וישב כח, ג</a>. ג) מאמרי אדה\"ז תקס\"ה ח\"א ע' קפד [הנחת הר\"מ בן כ\"ק אדה\"ז]. וראה גם ד\"ה לה\"ע החלומות באוה\"ת מקץ כרך ו ע' 2200 וד\"ה שיר המעלות בסה\"מ תשכ\"ז. וחלק השני [של המאמר] ד\"ה ומעתה [לקמן פ\"ד לט, ג] מיוסד על מאמר שנדפס לעיל לפני מאמר זה [שנאמר ג\"כ בש\"פ וארא תקס\"ה]. וש\"נ. ראה עוד ע\"ד מאמר זה וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["1630","*2","<b>ויאמר ה' אל משה</b>: שמות ד, ב [ושם: ויאמר אליו ה' — וכ\"ה בגדהזחט. י: מחק התיבות אל משה. והוסיף תיבת אליו. ראה גם לקמן מב, ב."],["1631","2","<b>ויאמר השליכהו ארצה</b>: שמות שם, ג."],["1632","3","<b>אני ישינה</b>: שה\"ש ה, ב."],["1633","4","<b>אני ישינה בגלותא</b>: ראה זהר אמור צה, א. האזינו רפו, א. מאמרי אדה\"ז תקס\"ד ע' קנה. מאמרי אדה\"א הנחות תקע\"ז ע' קפט. וש\"נ. לעיל כה, א. לקמן לט, א. פ' בשלח קפא, א. רלו, ד."],["1634","5","<b>בשוב ה' את שיבת ציון</b>: תהלים קכו, א."],["1635","6","<b>שבות</b>: ג: שיבת."],["1636","7","<b>השכל</b>: ג: ניתוסף: כלל."],["1637","8","<b>שטות</b>: תוקן ע\"פ אבג. ובתו\"ח: שמות."],["1638","9","<b>זה</b>: ג: שהוא. ט: זהו."],["1639","10","<b>כח המדמה</b>: ראה פ\"א ופ\"ח מח\"פ להרמב\"ם. הנסמן במאמרי אדה\"א דברים ח\"א ע' לד."]]],[2300540086,"שמגזם ומכזב גם בכל דבר שלא הי' ולא יהי' בעולם כו'). (ושרש הענין ידוע לפי שכל החלומות באים מעין הרהורי לבו<sup data-n=\"1640\">11</sup> ביום אך א\"כ הי' כל דברי החלומות אמת ולא ב' הפכים כא' כו' וא' החלומות שוא ידברו<sup data-n=\"1641\">12</sup> כו'. הענין הוא שאותיות הרהורי לבו שכבר הרהר פעם א' עם כל מה שמהרהר בימים רבים מאד מתחברים יחד בחלום בשינוי הסדר לגמרי עד שיוכל לחלום דבר והיפוכו ממש, אבל כל א' בפ\"ע יש לו מקום בפ\"ע שהוא מעין הרהורי לבו שכבר הי' בעולם רק שבא בדרך דוגמא וכחיבור בענין זר מאד כו' שהרי לא יחלום פילא בקופא דמחטא<sup data-n=\"1642\">13</sup> דבר שאינו יכול להעלות במחשבה ולא הי' בעולם כו', וזה כל ענין פתרון חלומות להביא כל ענין אל מקומו בסדר נכון כו' כמ\"ש במ\"א<sup data-n=\"1643\">14</sup> ).\n[ב] <b>והנה</b> ע\"ד דוגמא זאת יובן בכנס\"י שהן בגלות בבחי' שינה כמ\"ש אני ישינה כו' בכל עניני עבודת האלקי' בנשמתם וגופם שזהו בבחי' החלום ממש שיש בו דבר והיפוכו כאחד ממש כנ\"ל. דהנה אנו רואים דבר הפלא ופלא מה שהאדם יכול להתפעל בהתבוננו' בגדולת ה' כמו ביחו\"ע ויחו\"ת<sup data-n=\"1644\">15</sup> דק\"ש עד שיגיע לאהבה אלקי' באמת בכל לבו ונפשו באחד ואהבת<sup data-n=\"1645\">16</sup> את ה' בכל כו'. ואח\"ז מיד אחר התפלה כשהולך בשוק ישים לבו וכל נפשו בעסקי עוה\"ז במו\"מ וגם אחר תאוות[יו] הרעים נמשך בכל לבו ונפשו במעשים ומחשבות זרות כו' שהרי זה דבר <span data-k=\"pg\">106</span> ּ והיפוכו ממש בנושא אחד וכתרתי דסתרי אהדדי לגמרי דאם הי' התפעלות אהבה אלקי' בק\"ש ותפלה אמת שאין עוד מלבדו<sup data-n=\"1646\">17</sup> וכולא קמי' כלא<sup data-n=\"1647\">18</sup> ממש כו', האיך יהופך מן הקצה לקצה כל היום לידבק בדבר זר זולתו ית' לעשות מהטפל עיקר ומהעיקר טפל (וכמאמר ישראל שבחו\"ל<sup data-n=\"1648\">19</sup> עובדי ע\"ז בטהרה הן, לפי שבחו\"ל לבוש שק דנוגה מסתיר יותר והוא שורש דרכי טבע האנושי' ואלקי' גימט' הטבע<sup data-n=\"1649\">20</sup> לומר כחי ועוצם ידי<sup data-n=\"1650\">21</sup> כו' ועושה מטפל עיקר לחצוב לו בורות נשברים<sup data-n=\"1651\">22</sup> שהם ע\"ס<sup data-n=\"1652\">23</sup> דק\"נ כו'). וכמו שהוכיח אליהו אם ה' הוא האלקי' לכו אחריו כל היום ועד מתי<sup data-n=\"1653\">24</sup> אתם פוסחים על ב' הסעיפים כו', וכן אמר קצר המצע מהשתרע<sup data-n=\"1654\">25</sup> מהשתרר שני ריעים כו' דבר והיפוכו ממש",[["1640","11","<b>החלומות. . הרהורי לבו</b>: ראה ברכות נה, ב. לקמן פ' בא קלב, א. מאמרי אדה\"ז תקס\"ב ח\"א ע' צד. מאמרז\"ל ע' קלד. מאמרי אדה\"א הנחות תקע\"ז ע' רמד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680347\" data-slug=\"torat-chaim\" data-id=\"2300680347\">תו\"ח ויחי רמח, ג</a>."],["1641","12","<b>החלומות שוא ידברו</b>: זכרי' י, ב [ושם: וחלמות השוא — ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשג. וש\"נ. דברים ח\"א ע' לד. שעה\"י קמ, א]."],["1642","13","<b>לא יחלום פילא בקופא דמחטא</b>: ברכות שם. ראה הנסמן בשעה\"י קמ, א הערה 20."],["1643","14","<b>פתרון </b>[גט: פותר(י)]<b> חלומות. . במ\"א</b>: ראה גם מאמרי אדה\"ז על ענינים ע' תלא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680209\" data-slug=\"torat-chaim\" data-id=\"2300680209\">תו\"ח ויחי רמה, ג</a>. שם רמב, ד ובהנסמן בהערה 1. מאמרי אדה\"א הנחות תקע\"ז ע' רמו. לקמן פ' ויקהל שצט, א. תא, ד."],["1644","15","<b>ביחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."],["1645","16","<b>באחד ואהבת</b>: ואתחנן ו, ד. ה."],["1646","17","<b>שאין עוד מלבדו</b>: ואתחנן ד, לה."],["1647","18","<b>וכולא קמי' כלא</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה (שער היראה) ש\"א, פ\"א (ז, רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1648","19","<b>וכמאמר </b>[בגז: וכמארז\"ל]<b> ישראל שבחו\"ל</b>: ע\"ז ח, א. ראה מאמרי אדה\"א הנחות תקע\"ז ע' ר. וש\"נ. לעיל ב, א. לקמן פ' וארא עג, ד. בשלח קלד, א. ויקהל תיד, ג."],["1649","20","<b>ואלקי' גימט' הטבע</b>: ראה פרדס (שער הנתיבות) שי\"ב, פ\"ב. מצודת דוד לרדב\"ז מצוה קפה (לה, ד) בשם מגדולי העבודה הזאת. . אמרו המגמטרים. של\"ה (מס' פסחים מצה עשירה) קסג, סע\"ג. דבש לפי — מהחיד\"א — מערכת טבע אות א' בשם הראשונים. שהיחוה\"א רפ\"ו. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקעג. פירוש המלות צא, סע\"ד."],["1650","21","<b>כחי ועוצם ידי</b>: עקב ח, יז."],["1651","22","<b>לחצוב לו בורות נשברים</b>: ע\"פ ירמי' ב, יג."],["1652","23","<b>ע\"ס</b>: ט: ע\"ש."],["1653","24","<b>אם ה'. . ועד מתי</b>: מלכים-א יח, כא (בהיפך הסדר). ראה גם מאמרי אדה\"א שמות ח\"ב ע' שפ. שער האמונה פ, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670577\" data-slug=\"torat-chaim\" data-id=\"2300670577\">תו\"ח נח נח</a>, ב."],["1654","25","<b>קצר המצע מהשתרע</b>: ישעי' כח, כ. יומא ט, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680087\" data-slug=\"torat-chaim\" data-id=\"2300680087\">תו\"ח ויחי רמ, ג</a>. מאמרי אדה\"א הנחות תקע\"ז ע' קנז. וש\"נ. לקמן פ' וארא עז, ד."]]],[2300540124,"בלב אחד, וא\"א שבתפלה הי' ההתפעלות שקר דודאי נשמת אדם חלק אלוה<sup data-n=\"1655\">26</sup> הוא כו' וכמ\"ש נר ה' נשמת אדם<sup data-n=\"1656\">27</sup>, והתפעלותם אמת לאמתו<sup data-n=\"1657\">28</sup> וכמו באמת ויציב<sup data-n=\"1658\">29</sup> שמאמת לאמת האהבה דכל לבבך כו'. אלא צ\"ל דזה אינו כתרתי דסתרי<sup data-n=\"1659\">30</sup> כלל כי כל א' וא' בפ\"ע אמת כענין החלום הנ\"ל, [ד]מה שהי' לו מס\"נ באחד בק\"ש ותפלה ודאי אמת הוא מצד שרש הנשמה שנמשכת כניצוץ העולה מאליה למקורה כו', ומה שנמשך בכל לב ונפש בהבלי עוה\"ז אח\"כ גם זה אמת, אלא שהוא ענין בפ\"ע מצד חומר הגוף, רק שבאים ומתחברים בשעה א' תיכף אחר התפלה נמשך בעניני עוה\"ז כאלו הוא ענין אחד ממש והן דבר והיפוכו בתכלית שזהו כמו החלום שמחבר דבר והיפוכו כאחד כנ\"ל. וכך הוא בדרך פרט בכל בחי' טוב ורע שבאדם שהן ב' הפכים בתכלית, לפעמים יגב[ו]ר בו הטוב והוא להיות מתעורר בתשובה שלימה ועושה צדקה וכל המצות ולבו נשבר וחלל בקרבו כו', ולפעמים יגבור בו חלק הרע להיפוך לעשות כל רע והולך שובב בדרך לבו בלי שום התעוררות תשובה ולבו מלא מכל רע ומדות<sup data-n=\"1660\">31</sup> רעות כו' ויכול להיות שיתחברו ב' הפכים אלו בשעה א' כידוע. ועכ\"פ בכללות ימי חייו יתחבר כל בחי' טו\"ר יחד בתערובות ריבוי טוב וריבוי רע כו' דהיינו כל התפעלות אלקות אמיתי' שבתפלה ומעשה הטוב בתומ\"צ וצדקה ותשובה וגם כל הרע שנמשך בגופו במעשה ומו\"ד ומדות הכל כא' כו', וא\"כ זהו בחי' השינה ממש (וכנ\"ל<sup data-n=\"1661\">32</sup> דהחלומות השוא ידברו ולא מצד עצם ענין החלום שכל א' אמת בפ\"ע גם מה שמגזם וכוזב יש בזה מעין ודוגמא דהרהורי לבו כו', [כ]ך הנשמה מצד שרשה למעלה יהי' בה התפעלות אהוי\"ר רק שהוא מעין ודוגמא שהי' לה למעלה כו', וגם מה שיפול ברע מצד הגוף אמת מצד שרשה בק\"נ, רק שבאים כאחד, והוא לפי שבשינה עולים אידים<sup data-n=\"1662\">34</sup> מחומר גסות המאכלים שבקיבה ועושים דמיונות שוא בבלבולים גדולים לשנות סדר הצרופים דהרהורי לבו בכל ימיו כו', ע\"כ יש מהם אמת ויש שקר בכל תערובות טו\"ר. וראי' מנביאים שמופשטים מחומר הגוף לגמרי, יהי' החלומות שלהם ברור מכל שקר ודמיון כוזב אדרבה רוח האלקי' שורה בהם ויודעי'<sup data-n=\"1663\">35</sup> עתידות כמו ביד הנביאים אדמה<sup data-n=\"1664\">36</sup> כו' כמו וארא בחלום<sup data-n=\"1665\">37</sup> כו' בחלום אדבר בו<sup data-n=\"1666\">38</sup>",[["1655","26","<b>נשמת אדם חלק אלוה</b>: נסמן לקמן נא, ד."],["1656","27","<b>נר ה' נשמת אדם</b>: משלי כ, כז. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא רפי\"ט</a>."],["1657","28","<b>לאמתו</b>: ג: ניתוסף: הוא."],["1658","29","<b>באמת ויציב</b>: ברכת אמת ויציב (שחרית). ראה לקמן פ' תצוה שעט, ג. וש\"נ."],["1659","30","<b>דסתרי</b>: ד: ניתוסף: אהדדי."],["1660","31","<b>ומדות</b>: בדהזחט: במדות."],["1661","32","<b>(וכנ\"ל</b>: גם בהכת\"י חסר סיום החצע\"ג."],["1662","34","<b>שבשינה עולים אידים</b>: ראה גם בענין אידים מאמרי אדה\"ז תקס\"ט ע' ריב וע' רלא ואילך. תו\"ח ח\"ש קכה, ב. פירוש המלות נה, ג. נו, ג. אמרי בינה קט, ב. קל, ג. מאמרי אדה\"א דברים ח\"א ע' לד. הנחות תקע\"ז ע' קצא. סה\"מ תרע\"ח ע' קלא."],["1663","35","<b>ויודעי'</b>: אבגה: להגיד."],["1664","36","<b>ביד הנביאים אדמה</b>: נסמן לקמן פ' בא צט, ב הערה 136."],["1665","37","<b>וארא בחלום</b>: ויצא לא, י."],["1666","38","<b>בחלום אדבר בו</b>: בהעלותך יב, ו."]]],[2300540162,"כו' (וכמ\"ש<sup data-n=\"1667\">33</sup> בזהר דהחלום מסוף מדרגת הנבואה<sup data-n=\"1668\">39</sup> כו'). וזהו דוקא בגלות שנק' שינה, אבל בזמן בהמ\"ק לא הי' ענין ב' הפכים הנ\"ל בכנס\"י שהרי הגם שהיו עוסקים בפרנסה ומו\"מ אחר מס\"נ בק\"ש לא הי' מסתיר להם לאור האלקי שבעבודתם בתפלה <span data-k=\"pg\">נג</span> ּ ותו\"מ כלל כי הי' זה העסק אצלם בדרך עובדא כמעשה המצות ממש הגם שהי' לצורכי חיי גופם<sup data-n=\"1669\">40</sup> כשיהי'<sup data-n=\"1670\">41</sup> בטחונם חזק רק על ה' לבדו שהוא הממשיך ברכה במעשה ידיהם ואליו נושאים נפשם בעסקם כו' כענין השלך על ה' יהבך<sup data-n=\"1671\">42</sup> כו', ואינם בטוחים בכח ועוצם ידם כלל רק שצריכים לעסוק בדרך ציווי שיהי' במה לשכון אור השפע האלקי' וכמ\"ש וברכך ה' בכל אשר תעשה<sup data-n=\"1672\">43</sup> כו'. ונמצא לא הי' עסקם גם<sup data-n=\"1673\">44</sup> בגשמיות בבחי' נפרד מאלקים כלל, וכמ\"ש לאהבה את ה' בכל לבבכם ובכל נפשכם<sup data-n=\"1674\">45</sup> ממש וסמיך לי' ואספת דגנך<sup data-n=\"1675\">46</sup> כו' ואין זה כתרתי דסתרי כלל, משא\"כ בזמן הגלות דמס\"נ בתפלה ועסק הפרנסה המה דבר והיפוכו ממש כנ\"ל וד\"ל.\n[ג] <b>וזהו</b> בשוב ה' שבות ציון היינו כחולמים, פי' כאשר יבא משיח ב\"ב ויתגלה אור האלקי כמו שהוא באמיתתו בכאו\"א כמ\"ש כולם ידעו אותי מקטנם<sup data-n=\"1676\">47</sup> ועד גדולם כו', אז יכירו ויבינו על כל אשר הי' בכאו\"א בזמן הגלות בכל דור וזמן ימי חיי האדם כל מעשה הטוב בתפלה ותשובה ותו\"מ כו' הכל הי' דרך חלום שמעורב בזה דבר והיפוכו כאחד, כי מיד אחר הטוב דתפלה ותומ\"צ רע דמדות רעות והמשכת עניני עוה\"ז החומרי ואחר הרע דק\"נ במדות ומו\"ד כו' טוב דהתפעלות אלקות בתפלה ותומ\"צ ותשובה כו' כמו בחלום שיהופך בענינים הפכיים מנגדיים מאד והכל בדרך סיפור ענין א' שלא יכילנו השכל. משא\"כ לע\"ל יהי' אור ה' מאיר בנשמות כמו שאדם ניעור מן השינה שאין בו דבר והיפוכו בשום אופן כמו וידע כל פעול<sup data-n=\"1677\">48</sup> כו' וד\"ל. והנה הגם שהחלומות בשינה הוא בתחתית המדרגה שבמח' שבמוח, והוא כח הדמיון לבד ע\"כ מדמה דבר וכוזב<sup data-n=\"1678\">49</sup> וגוזמא שלא יוכל להיות וכן ב' הפכים כנ\"ל לפי שבשעת השינה מסתלקים כל כחות פנימי' הנפש למעלה בעצמות הנפש בעילוי אחר עילוי כו' עד שלא נשאר גם במחשבה שבמוח רק הכח המדמה לבד ובלב לא נשאר רק קיסטא דחיותא<sup data-n=\"1679\">50</sup> בדפק שבלב וע\"כ בטל כל הרגשה ותנועה רצונית וכ\"ש המדות והשכל ורצון שמדות אוי\"ר וכה\"ג מסתלקי' בשכל והשכל שבמוח מסתלק ועולה בכח המשכיל וכן כח הרצון עולה בעצמות הנפש כו'. הנה עכ\"ז יש בחלום יתרון מעלה בשרשו מזה עצמו שהשכל<sup data-n=\"1680\">51</sup>",[["1667","33","<b>והוא. . (וכמ\"ש</b>: בגדה: (והוא. . אגדה: וכמ\"ש."],["1668","39","<b>דהחלום. . הנבואה</b>: ראה זהר ויצא קמט, א. ס\"ת שם. וישב קפג, א. קצא, ב. ויחי רלח, א. ברכות נז, ב."],["1669","40","<b>גופם</b>: א: הגוף. גד: הגוף ממש."],["1670","41","<b>כשיהי'</b>: אבד: כי הי'."],["1671","42","<b>השלך על ה' יהבך</b>: תהלים נה, כג."],["1672","43","<b>וברכך. . אשר תעשה</b>: פ' ראה טו, יח [ושם ה\"א]. ראה ד\"ה זה במאמרי אדה\"ז תקס\"ה ח\"ב ע' תרנו. לעיל ב, א. לקמן פ' ויקהל תיד, ב."],["1673","44","<b>גם</b>: בגדז: ליתא."],["1674","45","<b>לאהבה. . ובכל נפשכם</b>: עקב יא, יג [בדילוג]."],["1675","46","<b>ואספת דגנך</b>: עקב שם, יד."],["1676","47","<b>כולם ידעו אותי מקטנם</b>: ירמי' לא, לג [ושם: למקטנם — ראה לקמן פ' בשלח קצד, ב. רכד, ב. רלב, ג. תצוה של, ד. ויקהל שצט, ב. שער האמונה לד, א ובהערה 19]. ראה גם שער האמונה צג, א."],["1677","48","<b>וידע כל פעול</b>: תפלת העמידה לר\"ה."],["1678","49","<b>וכוזב</b>: אגז: כוזב."],["1679","50","<b>קיסטא דחיותא</b>: ראה זהר לך פג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380211\" data-slug=\"likkutei-torah\" data-id=\"4001380211\">לקו\"ת אמור לא, ב</a> ובהנסמן במ\"מ לשם."],["1680","51","<b>שהשכל</b>: אגז: שהכל."]]],[2300540199,"עולים בפנימי' ועצמי' הנפש שנק' יחידה דוקא כי מאחר שכל פנימי' הכחות דרצון ושכל ומצות ומחו\"ד הכל עלו לפנימי' דבחי' יחידה שזהו עילוי מופלג לנר\"נ שבמוח ולב וכבד כו' בעת השינה דוקא כו' (כידוע ומבואר במ\"א שזהו כמו בחי' עיבור דתלת כלול גו תלת<sup data-n=\"1681\">53</sup> חב\"ד בחג\"ת וחג\"ת בנה\"י שיש יתרון מעלה<sup data-n=\"1682\">52</sup> אז מצד עליות המוחי' ומדות בבחי' יחידה שזהו שאמר תינוק בבטן אמו<sup data-n=\"1683\">54</sup> מלמדים אותו כל התורה וכתי' מי יתנני כירחי קדם<sup data-n=\"1684\">55</sup> דוקא כו' וד\"ל). וא\"כ כאשר יחלום חלום בשינה אף שהוא בא מכח המדמה הרי שרשו הוא מאיר בהעלם מבחי' יחידה דעצמות הנפש שלמעלה מהרצון ושכל כו' (וע\"כ יבא בחלום כמה עניני רצון ושכל שבאו במו\"ד בהרהורי לבו כל הימים יחדיו ישכנו לפי שאין סדר בזה כלל וכלל כנ\"ל מטעם שבחי' יחידה הוא בחי' העצמיות דנפש הכולל כל פרטי הסתעפות כמה מיני רצון ושכל ומדות ומו\"ד יחד ממש גם שיש בהן דבר והיפוכו כחו\"ג שברצון ותענוג וחו\"ג שבשכל ומדות כמו צער וחדוה התנשאות ושפלות כו' באים כא' ברגע א' בחלום מצד בחי' יחידה כו'. ודוגמא לדבר כל ימי האדם נחלקו לחלקים פרטיים יש ימים שהוא <span data-k=\"pg\">108</span> ּ בבחי' חסד וטוב [ב]עושר והצלחה ויש ימים שהוא בימי רעה עני ומדוכא כו', וכאשר הנפש באה בעולם כוללת היא כל הימים שקצובין לו במספר שיש בהן דבר והיפוכו טו\"ר יחד ממש, וכך הוא בחי' התחלקות דטו\"ר שברצון ושכל ומדות ומו\"ד לגבי עצם הנפש שכוללם יחד בסקירה א' מבלי התחלקות כלל כולם כא' יוסקרו בה כו'). ומטעם זה יובן עכ\"פ שאע\"פ שהחלומות הן בבחי' דמיון שרשם בעצם הנפש שהוא בחי' יחידה, ע\"כ בא בהן דבר והיפוכו יחד (רק הכוזב והשוא שבהן הוא בא מעיכור אידי המאכל שמבלבלים הצירופי' ונעשה ענין זר וכוזב לגמרי, אבל כאו\"א בפ\"ע הוא אמת כנ\"ל, וגם שינוי זה הסדר בא מלמעלה דוקא, והוא מכח החולם שמשנה כל סדר עניני הצירופים כו'). ויובן מזה שהחלומות שרשם בבחי' עיגולים מקיפים כמו העיגול שאין בו מעלה ומטה<sup data-n=\"1685\">56</sup> והתחלקות קוין לחלקים מיוחדים כלל רק הכל כא' ממש כי הוא סובב כולו כאחד בב\"א ולא ניכר בו התחלקות כלל להיותו למעלה עדיין מבחי' התחלקות המשכת קוין כי כולל הוא כו', משא\"כ באמצע[י]ת העיגול יומשך בו קוין בהתחלקות פרטיים לימין ושמאל ואמצע כו' ומעלה ומטה הכל כידוע. והנמשל מזה יובן שזהו בחי' מקיפי' דתהו שהן כמו עיגולים למעלה [מ]התחלקות בחי' קוין [ד]בחי' התיקון דציור אדם בנר\"ן [ב]רצון ושכל מחשבה ודבור כו'. ויובן זה בציור קומה דכנס\"י כשהן בגלות הנק' שינה",[["1681","53","<b>דתלת כלול גו תלת</b>: ראה זהר (תוספתא) בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ג. הנסמן בשעה\"י קל, ב הערה 18."],["1682","52","<b>במ\"א. . שיש יתרון מעלה</b>: ראה גם מאמרי אדה\"ז על ענינים ע' תיד. לעיל כה, א. לא, ד. לקמן שכ, א. שצט, ד. תא, א."],["1683","54","<b>תינוק בבטן אמו</b>: ראה נדה ל, ב. לקמן פ' בשלח קפ, ג. וש\"נ."],["1684","55","<b>מי יתנני כירחי קדם</b>: איוב כט, ב. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שעו. וש\"נ."],["1685","56","<b>העיגול שאין בו מעלה ומטה</b>: ראה לקמן פ' בא קטו, א. יתרו רנג, ב. פקודי תמט, ד. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שכד. מאמרי אדה\"א נ\"ך ע' תמז. וש\"נ. שער האמונה יג, ב ובהערה 25."]]],[2300540232,"הגם שהוא בבחי' הדמיון ובא בהתחברות דבר והיפוכו טו\"ר יחד כנ\"ל, עכ\"ז שרש זה דוקא הוא בבחי' המקיף הכללי דבחי' יחידה שבנפשם [ב]כלל שכולל כל פרטי התחלקות דמוחין ומדות כו' שמתחלקי' בפרט שיוצאים מן הכלל כנ\"ל, וע\"כ גם שיש בעבודתם בכל דור [ו]זמן מעורב יחד טו\"ר (מחמת העלאת חומר הגופני כו') שרשו נעלה מאד והוא ביחידה דכנס\"י שהוא למעלה מהתחלקות דנר\"ן בציור אדם כו', רק שעתה הם בהתלבשות דמיונות החלומות ולע\"ל יתעלו לשרשם שבבחי' מקיפים (וכמ\"ש ותחלימני ותחייני<sup data-n=\"1686\">57</sup> כו' כמו שאחר השינה יתחזק כח השכל והגוף מפני הבירור כו', וזהו שהראו לחוני המעגל שישן ע' שנה<sup data-n=\"1687\">58</sup> כמו גלות בבל ע' שנה<sup data-n=\"1688\">59</sup> כו'). וזהו שאו' אז היינו כחולמים שכל עבודת האלקי הי' בבחי' חלום כלול מב' הפכים, אבל החלומות הללו עצמם יתעלו לשרשם בעצמות אלקות (והוא ע\"י יוסף פותר חלומות שהוא בחי' צ\"ע כמשי\"ת). וכך הוא בשרש כנס\"י למעלה דכתי' ותקם בעוד לילה<sup data-n=\"1689\">60</sup> דוקא ותתן טרף רפ\"ח<sup data-n=\"1690\">61</sup> כו' עד\"מ באדם בעת השינה דוקא יותר יעוכל המאכל ויבורר וע\"כ יתחזק יותר בהקיצו כו', וזהו שבחי' ב\"ן מברר בירורים דרפ\"ח כו' מהיכלות החיצוני' כו' ואע\"פ שנק' חלום מ\"מ יש בזה יתרון מעלה להיותו בבחי' מקיפי' דעיגולים דתהו שלמעלה מבחי' הקוין דתיקון כנ\"ל. וזהו בזמן הגלות שנק' לילה<sup data-n=\"1691\">62</sup> שהשכינה בגלות בע\"ש<sup data-n=\"1692\">63</sup> ונק' שינה וכמ\"ש אני ישינה ולבי ער כו' בשרשו במקיף הכללי דבחי' יחידה דכנס\"י וד\"ל.\n[ד] <b>והנה</b> כמו\"כ יובן בבחי' אדם העליון שעל הכסא<sup data-n=\"1693\">64</sup> כו' הגם שאין לו גוף<sup data-n=\"1694\">65</sup> ולא דמות הגוף כו' דברה תורה כלשון בנ\"א<sup data-n=\"1695\">66</sup> כידוע, וכמ\"ש עורה למה תישן<sup data-n=\"1696\">67</sup> כו' וכן ויקץ כישן ה'<sup data-n=\"1697\">68</sup> כו', שבזמן הגלות הוא בבחי' שינה כענין תרדמה שנפלה על אדה\"ר<sup data-n=\"1698\">69</sup> כו' ונק' בחי' דורמיטא<sup data-n=\"1699\">70</sup> כו' שהוא בחי' הסתלקות פנימי' המוחין ומדות כו' למעלה מעלה בעצמות המאציל כו' ואין שפע <span data-k=\"pg\">נד</span> ּ לעולמות דבי\"ע רק מבחי' נה\"י דנה\"י כו', כמו משל השינה באדם התחתון שנשאר רק בחי' כח הדמיון במחשבה וקיסטא דחיותא בלב כו' וכמ\"ש אלכה ואשובה אל מקומי<sup data-n=\"1700\">71</sup> כו' ואיתא בזהר דקוב\"ה בגלותא אסתלק לעילא לעילא<sup data-n=\"1701\">72</sup> כו' שהוא",[["1686","57","<b>ותחלימני ותחייני</b>: ישעי' לח, טז [ושם: — והחייני — ראה לקמן פ' ויקהל תא, ג. מאמרי אדה\"ז תקס\"ז ע' קסח. מאמרי אדה\"א דברים ח\"א ע' קה. וש\"נ. הנחות תקע\"ז ע' רמד. וש\"נ]."],["1687","58","<b>לחוני המעגל שישן ע' שנה</b>: תענית כג, א. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' קי. וש\"נ."],["1688","59","<b>גלות בבל ע' שנה</b>: ירמי' כט, י. מגילה יא, ב ואילך."],["1689","60","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["1690","61","<b>טרף רפ\"ח</b>: ראה פע\"ח (שער ק\"ש שעהמ\"ט) שט\"ז, פ\"ה. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלא. מאמרי אדה\"א בראשית ע' קמו. וש\"נ."],["1691","62","<b>הגלות שנק' לילה</b>: ראה זהר אחרי סז, ריש ע\"ב. סה\"מ מלוקט ח\"ב ע' רסו הערה 16."],["1692","63","<b>בע\"ש</b>: נסמן לעיל פ' שמות לז, ג הערה 52."],["1693","64","<b>אדם העליון שעל הכסא</b>: ראה יחזקאל א, כו."],["1694","65","<b>שאין לו גוף</b>: ע\"ד פיוט יגדל."],["1695","66","<b>דברה תורה כלשון בנ\"א</b>: ברכות לא, ב. וראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670114\" data-slug=\"torat-chaim\" data-id=\"2300670114\">תו\"ח וירא צח, ב</a> [וכן צ\"ל במאמרי אדה\"א דברים ח\"א ע' לה]."],["1696","67","<b>עורה למה תישן</b>: תהלים מד, כד."],["1697","68","<b>ויקץ כישן ה'</b>: תהלים עח, סה."],["1698","69","<b>תרדמה שנפלה על אדה\"ר</b>: בראשית ב, כא."],["1699","70","<b>דורמיטא</b>: לשון הזהר ויגש רז, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680104\" data-slug=\"torat-chaim\" data-id=\"2300680104\">תו\"ח ויחי רמג, ד</a>. שעה\"י קמ, ב ובהנסמן במ\"מ להנ\"ל. לקמן פ' בשלח קפא, א."],["1700","71","<b>אלכה ואשובה אל מקומי</b>: הושע ה, טו [ושם: אלך אשובה — ראה פסדר\"כ (באבער) פי\"ג (דברי ירמי' ע' קטו). לעיל א, ג. לקמן פ' וארא סד, ב. בשלח קעט, ג. קפא, א. ד. תצוה שנא, ד. מאמרי אדה\"א דברים ח\"ג ע' תשסד. וש\"נ. שע\"ת עב, ג ובהנסמן במ\"מ לשם]."],["1701","72","<b>דקוב\"ה בגלותא. . לעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. ש\"א נא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670145\" data-slug=\"torat-chaim\" data-id=\"2300670145\">תו\"ח לך צה, א</a> ובהערה 2. מאמרי אדה\"א הנחות תקע\"ז ע' ג. וש\"נ. לעיל א, ד. לא, ד. לקמן פ' וארא סג, ד. בשלח קעט, ג. רה, ג."]]],[2300540264,"בחי' מקיפי' העליונים דבחי' עיגולים דתהו שלמעלה מעלה מבחי' התחלקות נר\"ן שבאדם העליון כו'. וזהו עורה למה תישן ה' כו', ואע\"פ שאמר וכי יש שינה<sup data-n=\"1702\">73</sup> לפני המקום כו' היינו למעלה מבחי' ציור אדם דבחי' התיקון בנר\"נ כו' (ונק' עינא פקיחא<sup data-n=\"1703\">74</sup> דלא נאים וכמ\"ש לא ינום ולא יישן<sup data-n=\"1704\">75</sup> כו' כידוע), וכמשל המאכל שבקיבה שמעלה אידים [ל]מוח והוא העושה כמו מכסה דק להגביר השינה ובאים החלומות בענינים זרים ומנגדים כו', כך הוא מבחי' בירורים דק\"נ שהן מעורבים טו\"ר עולים למעלה כו' ומזה ענין בחי' החלומות למעלה כשהוא בבחי' שינה כו' שהוא בא בבחי' התלבשות בחיצוניות דחיצוניות דמח' עליונה המצמצם לגמרי כו' (וע\"כ גם באומות העולם בא רוב שפע ביתר מכפי מדתם וגם שהם עוברי רצונו כו' כמשל הישן שאינו מרגיש בזבוב<sup data-n=\"1705\">76</sup> כו'). וזהו מ\"ש אלביש שמים קדרות<sup data-n=\"1706\">77</sup> ושק אשים כסותם פי' בחי' שמים<sup data-n=\"1707\">78</sup> העליונים שהן בחי' העיגולים דתהו ([ו]הוא מח' הכללי' שסוקר הכל כא' שלמעלה מהתחלקות דחכ' ורצון כו') אלביש להורידם למטה<sup data-n=\"1708\">79</sup> מאד והוא בבחי' קדרות וחשך בצמצומים דבחי' צרופי' האחרונים דמחשבה שהוא ענין ובחי' החלומות כו' שזהו מבחי' חיצוניות דחיצוניות דשם אלקי' המצמצם ומסתיר לגמרי, וזהו ושק אשים כסותם שהן לבוש שק דנוגה שמלובש בע' שרים כו'. וכ\"ז בזמן הגלות דוקא שנק' שינה, אבל לע\"ל כתיב ולא יכנף<sup data-n=\"1709\">80</sup> עוד מוריך כו' כמ\"ש ביום ההוא יהי'<sup data-n=\"1710\">81</sup> ה' אחד ושמו אחד דשם אלקים שנק' שמו יהי' כה' אחד יחו\"ע דאצי' שלא יסתיר כלל וכלל, [ד]עכשיו מחמת רוב הצמצומי' דאלקים באה בחי' החלומות כ\"כ למטה מטה כו', אבל לע\"ל יוציא חמה מנרתקה<sup data-n=\"1711\">82</sup> שהוא שם אלקים וכמ\"ש ונגלה כבוד הוי'<sup data-n=\"1712\">83</sup> דוקא ע\"כ יתעלו אז גם בחי' החלומות דאלביש שמים קדרות ושק דעכשיו למעלה מעלה כמו שהן בשרשן בבחי' עיגולים דתהו כנ\"ל שלמעלה מבחי' התיקון להוסיף אור גדול בשם הוי' מצד יתרון האור מן החשך<sup data-n=\"1713\">84</sup> דוקא מטעם הנ\"ל דשרש החלומות הוא בעצם הנפש כו' וד\"ל. וזהו שלע\"ל דוקא נאמר היינו כחולמים שיתעלו החלומות בשרשם ולא כעכשיו שהחלומות הן בבחי' העלם דלבוש שק דחיצוניות ואחוריים דאלקים, אבל לע\"ל שיהי' שמו דאלקים אחד יחו\"ע ממש כנ\"ל",[["1702","73","<b>וכי יש שינה</b>: סוטה מח, א."],["1703","74","<b>עינא פקיחא</b>: ראה זהר (אד\"ר) נשא קכט, סע\"ב ואילך. הנסמן במאמרי אדה\"א נ\"ך ע' תג."],["1704","75","<b>לא ינום ולא יישן</b>: תהלים קכא, ד."],["1705","76","<b>הישן שאינו מרגיש בזבוב</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' ע. פיה\"מ נו, א. מאמרי אדה\"א קונטרסים ע' תקעב. וש\"נ."],["1706","77","<b>אלביש שמים קדרות</b>: ישעי' נ, ג. ראה גם לקמן פ' בשלח קלה, ב."],["1707","78","<b>שמים</b>: תוקן ע\"פ גט. ובתו\"ח המים."],["1708","79","<b>למטה</b>: ג: ניתוסף: מטה."],["1709","80","<b>ולא יכנף</b>: ישעי' ל, כ."],["1710","81","<b>ביום ההוא יהי'</b>: זכרי' יד, ט."],["1711","82","<b>לע\"ל יוציא חמה מנרתקה</b>: ראה ע\"ז ג, סע\"ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670107\" data-slug=\"torat-chaim\" data-id=\"2300670107\">תו\"ח בראשית לה, א</a> ובהערה 12. לקמן פ' וארא סא, ד. בשלח קפט, א. יתרו ערב, ג. תצוה שכח, ג. פקודי תנה, ב."],["1712","83","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["1713","84","<b>יתרון האור מן החשך</b>: קהלת ב, יג."]]],[2300540293,"אז דוקא יבינו שורש ענין החלומות שהי' בזמן הגלות וד\"ל. והנה ענין בירור החלומות דגלות שנק' שינה הוא ע\"י יוסף דוקא, כי הוא מבחי' מלך הח'<sup data-n=\"1714\">85</sup> מלך הדר<sup data-n=\"1715\">86</sup> כו' שרש המקור לבחי' התיקון<sup data-n=\"1716\">87</sup> עד\"מ מי שיכול להעמיד כל דבר המבולבל בשינוי החלומות<sup data-n=\"1717\">88</sup> כל א' על מקומו ולעשות סדר נכון כו', וזהו ענין פותר חלומות שהולך אחר הפה<sup data-n=\"1718\">89</sup> דוקא כך החלומות עליונים שבגלות<sup data-n=\"1719\">90</sup> הולכים אחר הפה דיוסף דוקא פותר חלומות אותיות תופר<sup data-n=\"1720\">91</sup> כמ\"ש בן פורת יוסף<sup data-n=\"1721\">92</sup> כו' (כמשי\"ת), וזהו שנתעלה יוסף ע\"י פתרון החלומות דוקא כי שרשו למעלה במקור בחי' התהו ותיקון כו' וד\"ל (וזהו שבחי' יוסף צ\"ע הוא בכל גלות שנק' שינה וכ\"ש בגלות זה האחרון שהוא בחי' שינה מרובה והוא אריכות הגלות שנתארך ביותר לפ\"ע זה<sup data-n=\"1722\">93</sup> גברו החלומות ביותר עד\"מ שינה באדם שאין ריבוי החלומות בא מתוך שינה מועטת אלא מתוך שינה מרובה כו'). וזהו שבבחי' זו דפתרון חלומות גבוה יוסף <span data-k=\"pg\">110</span> ּ גם ממשה (והוא מלך המשיח<sup data-n=\"1723\">94</sup> ) שהרי יוסף הי' בו נשמת נדב ואביהו<sup data-n=\"1724\">95</sup> בבחי' רוח ונפש שבו, וע\"כ נשמת נדב שהוא בחי' רוח דיוסף לא הי' צריך אהרן<sup data-n=\"1725\">96</sup> הזאה ג' וז' כלל וז\"ש ורוח נדיבה תסמכני<sup data-n=\"1726\">97</sup> כו' רוח של נדב שאין שם אחיזה לחיצונים כלל (כמו במשיח דאז נא' ורוח הטומאה<sup data-n=\"1727\">98</sup> כו') וכמ\"ש בס' הקבלה והוא מטעם הנ\"ל וד\"ל.\n<b>ומעתה</b><sup data-n=\"1728\">99</sup> י\"ל מ\"ש אז יאמרו בגוים<sup data-n=\"1729\">100</sup> הגדיל ה' לעשות עם אלה למה יאמרו הגוים דוקא הגדיל כו', והנה תחלה י\"ל ענין גלות מצרים בכלל שנק' בשם שינה כמ\"ש למעלה, ואמנם זהו דוקא בחי' הבירורים דרפ\"ח כו' כנ\"ל והוא מ\"ש וינצלו את מצרים שעשאוה כמצולה<sup data-n=\"1730\">101</sup> כו' (וכמו שהבטיח לאברהם ואח\"כ יצאו ברכוש גדול<sup data-n=\"1731\">102</sup> כו') שזהו בחי' בירור והעלאת כל רפ\"ח ניצוצים שנפלו בשבה\"כ בחטא עה\"ד כו' מבחי' עולם התהו שלמעלה מבחי' התיקון<sup data-n=\"1732\">103</sup> ויצאו וירדו למטה מטה בהתחלקות ד' נהרות שיוצאי' מנהר שיוצא מעדן ושם הא' פישון<sup data-n=\"1733\">104</sup> הוא נהר נילוס<sup data-n=\"1734\">105</sup> (שנפלו שם כל ניצוצות דתהו<sup data-n=\"1735\">106</sup> שנפלו בדור הפלגה ועוד נשמות רבות<sup data-n=\"1736\">107</sup> ) וכאשר השאילום כלי כסף<sup data-n=\"1737\">108</sup> וכו' עשאוה כמצולה כו' שביררו והעלו גם אשר כבר",[["1714","85","<b>יוסף. . מלך הח'</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שפו. וש\"נ. שעה\"י קמ, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680079\" data-slug=\"torat-chaim\" data-id=\"2300680079\">תו\"ח וישלח קפח, ד</a> ובהערה 40. תורת לוי יצחק תענית ע' יא."],["1715","86","<b>מלך הח' מלך הדר</b>: ראה וישלח לו, לב-לט."],["1716","87","<b>הדר. . המקור לבחי' התיקון</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תפב. וש\"נ. שם ע' א'שפו."],["1717","88","<b>החלומות</b>: ג: הצירופים."],["1718","89","<b>חלומות שהולך אחר הפה</b>: ברכות נה, א."],["1719","90","<b>עליונים שבגלות</b>: ג: העליונים שהן בלבוש שק שבגלות."],["1720","91","<b>פותר. . אותיות תופר</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ס\"ע רמו. שעה\"י קמ, סע\"ב."],["1721","92","<b>בן פורת יוסף</b>: ויחי מט, כב."],["1722","93","<b>זה</b>: ג: ניתוסף: שנק' גלות."],["1723","94","<b>יוסף. . מלך המשיח</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שמה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680162\" data-slug=\"torat-chaim\" data-id=\"2300680162\">תו\"ח מקץ ריז, ב</a>. רכח, ריש ע\"ג. לקמן פ' ויקהל שצט, א. תג, א."],["1724","95","<b>יוסף. . נשמת נדב ואביהו</b>: ראה לקו\"ת להאריז\"ל פ' וארא עה\"פ (ו, כה) ואלעזר. מכתב י\"א ניסן תש\"כ נדפס באג\"ק חי\"ט ע' רסא. מאמרים שנסמנו בריש המאמר."],["1725","96","<b>אהרן</b>: בהמאמרים שם לא הובאה תיבה זו."],["1726","97","<b>ורוח נדיבה תסמכני</b>: תהלים נא, יד. לקו\"ת הנ\"ל."],["1727","98","<b>ורוח הטומאה</b>: זכרי' יג, ב [ושם: ואת רוח. ראה גם לקמן פ' וארא עד, א]."],["1728","99","<b>ומעתה</b>: מכאן מיוסד על המאמר שנדפס לפנ\"ז. וראה הנסמן בריש המאמר שם."],["1729","100","<b>אז יאמרו בגוים</b>: תהלים קכו, ב."],["1730","101","<b>וינצלו. . כמצולה</b>: נסמן לעיל לו, ג."],["1731","102","<b>ואח\"כ יצאו ברכוש גדול</b>: לך טו, יד."],["1732","103","<b>התהו. . התיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ."],["1733","104","<b>ד' נהרות. . פישון</b>: בראשית ב, י. יא."],["1734","105","<b>פישון. . נילוס</b>: נסמן לעיל לו, ד הערה 22."],["1735","106","<b>נילוס. . דתהו</b>: ראה גם לקמן מ, ב ואילך. פ' בא קטו, ב. לעיל לה, ב. מאמרי אדה\"א ויקרא ח\"א ע' עב. וש\"נ. בראשית ע' רצט. וש\"נ."],["1736","107","<b>רבות</b>: ג: גבוהות."],["1737","108","<b>השאילום כלי כסף</b>: בא יב, לה. לו."]]],[2300540321,"נמשך לשר מצרים לחיות גמור עד שנשארו ריקם מכל כו'. ולהבין ביאור הדברים הנה תחלה יש להקדים משל א' לענין הבירורים הנ\"ל [ו]הוא מנשמת האדם בגופו שאנו רואים שלבוש הזה דחומר הגופני הוא גס ועב מאד נמשך אחר תאוות כרוח הבהמה ממש, והנה גדול כחה כ\"כ עד שביכולת לבוש גס זה להחשיך גם לאור הנשמה האלקי' ששרש חוצבה ממקור החיים האלקי' והיותה כלולה וצרורה ודבוקה באלקים חיים בלי פירוד כלל וכלל אלא בבחי' הביטול בתכלית קודם בואה להתלבש בלבוש הגופני, כידוע שהנשמה כמו שהיא בשרשה גבוה גם מן המלאכים<sup data-n=\"1738\">109</sup> שנמשכים רק מבחי' ה[ב]ל הדיבור שהן בבחי' יש ודבר בפ\"ע רק שבאים ליכלל ביטול היש לאין כו', אבל הנשמ' הן ביחוד [ו]התכללות גמור במחשבה עליונה כו' כמ\"ש במ\"א, ואיך יוכל להיות שע\"י התלבשות הנשמה בגוף תחשך אורה האלקי כ\"כ עד שיוסתר ממנה אור האלקי לגמרי ותוכל להיות גם היא בבחי' פירוד מאלקות כאלו לא היתה מעולם קשורה ודבוקה בעצמות אלקות כלל, שהרי נאמר נפש כי תחטא<sup data-n=\"1739\">110</sup> כו' הרי נק' נפש החוטאת בפו\"מ שהוא הפגם שפוגם באות יו\"ד וה\"א כו' כידוע בוידוי דק\"ש שעל המטה<sup data-n=\"1740\">111</sup> שפגמתי באות יו\"ד, עד שצריכים בירור ותיקון להסיר הלבושים צואים מן החטאים<sup data-n=\"1741\">112</sup> ועון בגיהנם וכה\"ג בגלגולים כידוע, ואיך יתכן שמצד חומר הגופני תפול כ\"כ מאיגרא רמה<sup data-n=\"1742\">113</sup> כו' להיות להיפך גמור מכמו שהיתה במקור חוצבה כו'. אך הענין הוא משום דשרש לבוש גס דחומר הגופני דק\"נ ממקור חוצבו הראשון ממש כמו שהי' בבחי' שם ס\"ג דתהו<sup data-n=\"1743\">114</sup> שקדם לבחי' התיקון קודם השבירה כו' הוא אור תקיף<sup data-n=\"1744\">115</sup> וחזק הרבה יותר מאורו' דתיקון, והנשמות שרשם מבחי' אורות דתיקון שם מ\"ה<sup data-n=\"1745\">116</sup> כידוע, ע\"כ יש בכח הגוף להחשיך לאור הנשמה ולהפרידה מיחוד עליון לגמרי, וכמו הרבה נשמות גבוהות שנפלו למטה מטה בהיותם באים בגופים חומרים כו' (וראי' לזה מכח התשובה שהוא לב נשבר דגוף החומרי שעולה למעלה הרבה מצד\"ג<sup data-n=\"1746\">117</sup> כמשי\"ת בסמוך) מטעם זה <span data-k=\"pg\">נה</span> ּ דשורש בע\"ת בס\"ג דתהו שלמעלה ממ\"ה דתיקון כו'), וכמו\"כ יש כח גדול בנשמה בשרשה הראשון בעצמות אור הא\"ס ממש שלפני בחי' התהו ותיקון כו' להפוך גם חשך דק\"נ דתהו",[["1738","109","<b>שהנשמה. . גבוה. . המלאכים</b>: ראה אגה\"ת פ\"ד. שע\"ת כח, א. צב, א. מאמרי אדה\"א בראשית ע' קיב. וש\"נ. הנחות תקע\"ז ע' קכ. וש\"נ. לקמן פ' וארא עו, א. משפטים רפג, ב ואילך. רעח, א."],["1739","110","<b>נפש כי תחטא</b>: ויקרא ד, ב."],["1740","111","<b>בוידוי דק\"ש שעל המטה</b>: סידור האריז\"ל ואדה\"ז במקומו."],["1741","112","<b>החטאים</b>: גט: החטא."],["1742","113","<b>מאיגרא רמה</b>: נסמן לעיל ד, ג."],["1743","114","<b>שם ס\"ג דתהו</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ובהערה 2."],["1744","115","<b>דתהו. . אור תקיף</b>: ראה ע\"ח (שער המלכים) שי\"א, פ\"א. תו\"ח שם ובהערה 6."],["1745","116","<b>דתיקון שם מ\"ה</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"א ואילך."],["1746","117","<b>מצד\"ג</b>: ב: מצד\"ג). אבל לא העתיק התיבות ”כמשי\"ת בסמוך\". וכנצ\"ל: (כמשי\"ת בסמוך)."]]],[2300540346,"לאור כו', משא\"כ במלאכים כשנפלו למטה בנפילים<sup data-n=\"1747\">118</sup> שהיו בארץ כו' (וכמ\"ש במ\"א בענין ריח בני כריח שדה<sup data-n=\"1748\">119</sup> כו')<sup data-n=\"1749\">120</sup>, ועד\"ז יובן בענין ירידות ונפילות רפ\"ח ניצוצים דתהו הגם שהיו בתכלית הביטול וההתכללות, כשנפלו למטה ע\"י חטא עה\"ד כנ\"ל הוא שנעשו בבחי' פירוד גמור מאלקות בלבוש גופני דאדם שמחשיך לאור הנשמה האלקי' בירידתה והתלבשותה בה להיות בבחי' פירוד גמור, אך ענין ירידתם ונפילתם למטה הי' לצורך עלי' דוקא (כמשי\"ת בסמוך) וד\"ל.\n[ה] <b>וזהו</b> ענין נפילת רפ\"ח ניצוצות בד' נהרות דג\"ע כנ\"ל, דהנה ידוע בענין ונהר יוצא מעדן<sup data-n=\"1750\">121</sup> כו' שהוא בחי' התפשטות השפע דבחי' מים עליונים דחכ' שנמשך מעדן העליון שהוא בחי' התענוג העליון הנעלם שבפנימי' חכ' עילאה שהוא העוה\"ב ויתגלה לע\"ל ואפס קצהו מאיר בג\"ע מעדן זה כמ\"ש בעדן זה עין לא ראתה<sup data-n=\"1751\">122</sup> כו' ונמשך לבחי' בינה שנק' נהר<sup data-n=\"1752\">123</sup> שהוא מקור כל ההשג' אלקי' שהנשמות נהנין מזיו<sup data-n=\"1753\">124</sup> כו' שהוא בחי' העונג המורגש בהשגה כמו בחי' הרגשת התענוג אלקי שהנשמות מתענגי' על ה' בכל שבת כמ\"ש אז תתענג על ה'<sup data-n=\"1754\">125</sup> וכמו בתפלת השבת דעכשיו כידוע, וזהו ונהר יוצא מעדן העליון להשקות את הגן כו' ונק' נהר ע\"ש בחי' ההמשכה<sup data-n=\"1755\">126</sup> וריבוי השפע להשקות כו', ובג\"ע הרי הוא עדיין בבחי' היחוד גמור רק בבחי' המשכה אחת ונק' נהר א' כללי רק כשיוצא לחוץ לג\"ע הארץ א' [ו]משם יפרד והי' לד' ראשים<sup data-n=\"1756\">127</sup> כו' שיפרד זה הנהר לד' חלקי', כי בהיותו יוצא מעדן לא הי' עדיין בבחי' ההתחלקות כלל, אלא הי' נהר א' בבחי' היחוד והתכללות בעדן במקורו וכ\"ש וק\"ו בעדן העליון עצמו שהוא התענוג העליון הנעלם שם מתייחד בחי' נהר זה דבינה בתכלית (וכמו עונג המורגש בהשגה שנכלל ובטל בעצם התענוג הפשוט שבעצמות הנפש ואינו ניכר במציאות עונג כלל בפ\"ע כו'), אך משם יפרד בבחי' פירוד והתחלקות לד' ראשים כו' להיותו בא ונמשך למרחקים והוא להתפשט בכל הארץ שלמטה הרבה מג\"ע הארץ כו' ונתרחק כבר ממקומו הרבה ע\"כ משם יפרד יותר להתחלק לד' חלקים ד' מיני המשכות כלליות עכ\"פ, וכל מה שהולך ויורד ונמשך למטה מטה יותר [יותר] בא לבחי' התחלקות פרטיות, וכמו שאנו רואים",[["1747","118","<b>במלאכים כשנפלו למטה בנפילים</b>: בראשית ו, ד. ראה יל\"ש בראשית רמז מד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשס ובהנסמן במ\"מ לשם."],["1748","119","<b>ריח בני כריח שדה</b>: תולדות כז, כז. ראה גם מאמרי אדה\"א בראשית ע' קעט ואילך."],["1749","120","<b>(וכמ\"ש. . כו')</b>: ב: ליתא. בכמה כת\"י: וכמ\"ש. . כו'."],["1750","121","<b>ונהר יוצא מעדן</b>: בראשית ב, י. ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתסד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. לקמן פ' בשלח קמא, א."],["1751","122","<b>בעדן. . עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["1752","123","<b>בינה שנק' נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["1753","124","<b>שהנשמות נהנין מזיו</b>: ראה ברכות יז, א."],["1754","125","<b>אז תתענג על ה'</b>: ישעי' נח, יד."],["1755","126","<b>נהר. . ההמשכה</b>: ראה גם לעיל לו, ג."],["1756","127","<b>[ו]משם יפרד. . ראשים</b>: המשך הכתוב ונהר יוצא מעדן. ראה לעיל לה, ב. לו, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680243\" data-slug=\"torat-chaim\" data-id=\"2300680243\">תו\"ח וישב רח, א</a> ואילך."]]],[2300540369,"בנהר גשמי שיש שיעור ומדה לכל נהר בכח הילוך המשכתו כמה יומשך ק' או ר' פרסאות עד שיכלה כח שפע המשכתו ונהר השני יכלה זולתו כח שפע ירידתו והמשכתו בכמה פרסאו' יותר, ולפ\"ע כח המשכתו והילוך ביותר כך ערך התחלקותו לחלקים יותר, והוא להשקות לכל מקום ומקום לתועלת גידול דצח\"מ שבו כידוע שהמים מצמיחים הכל וכמו שאו' נהרא נהרא ופשטי'<sup data-n=\"1757\">128</sup> כו', שכל אקלים גדילי' טבעי' דצח\"מ שבו לפי אופן הנהר ההולך שם (כמו שא' ארץ מגדלת חכמים<sup data-n=\"1758\">129</sup> או טפשים, וכן מגדלת אנשי מדות טו\"ר וצו\"ד<sup data-n=\"1759\">130</sup> וכל מיני עונג הכל מן המים שבאותו נהר ששרשו בנהרות דג\"ע וכמ\"ש במ\"א<sup data-n=\"1760\">131</sup> וכמ\"ש הוא הסובב ארץ החוילה אשר שם הזהב<sup data-n=\"1761\">132</sup> ואבן הבדולח<sup data-n=\"1762\">133</sup> כו'). והנה בחטא עה\"ד ירדו ונפלו רפ\"ח ניצוצות מבחי' עולם התהו שלפני התיקון כו' בד' נהרות הללו שיוצאי' חוץ <span data-k=\"pg\">112</span> ּ לג\"ע הארץ כדי להתברר שם, והענין הוא שבתחלה היו ודאי כל הניצוצות הללו כנהר זה שיוצא מעדן בבחי' הרוחני' דאור התענוג העליון האלקי והי' שם בתכלית היחוד העליון האלקי כמו נשמת אדה\"ר בגופו קודם החטא דכתי' ויפח באפיו נשמת חיים<sup data-n=\"1763\">134</sup> שלא הי' חומר גופו מחשיך כלל לאור נשמתו דפרחא מחיי העולמים<sup data-n=\"1764\">135</sup> כו' (כמ\"ש בע\"ח שהי' ראשו בבריאה<sup data-n=\"1765\">136</sup> ורגליו בעשי' ועקבו מכהה גלגל חמה<sup data-n=\"1766\">137</sup> כו', וכדוגמא דלע\"ל שהגופים יהיו כלי' מזוכך לקבלת חיות אור האלקי ממש כחומר וצורה ממש), אך כשחטא בעה\"ד נתערב טו\"ר<sup data-n=\"1767\">138</sup> בכל העולמות ונמשך גם בנהר שיוצא מעדן כאשר בא לכלל פירוד חוץ לג\"ע בחי' הגשמה גדולה בד' נהרות הנמשכים בעולם להשפעת דצח\"מ מרוחניות לגשמיות בתערובות טו\"ר ממש עד\"מ הנ\"ל בהתלבשות הנשמה בגוף שנחשך אור הנשמה כו', ונעשית גם היא בבחי' נפרד ממש כו', כך הרפ\"ח ניצוצות שנפלו בד' נהרות שנתגשמו מחמת חטא עה\"ד נחשך אורם לגמרי כו' (והן כמו הנפילים שהיו בארץ אשר יבאו בני האלקים כו' עד המה הגבורים אשר מעולם היו אנשי השם דבחי' התהו ונפלו למטה ביותר כדור המבול ודור הפלגה וכה\"ג והי' בהן נשמות גבוהות שנתבררו ועלו משם כחנוך<sup data-n=\"1768\">139</sup> ומתושלח וכה\"ג), ודור הפלגה נפלו בנהר נילוס והוא פישון והוא<sup data-n=\"1769\">140</sup> יוצאי מצרים<sup data-n=\"1770\">141</sup> שהיו ה' פעמים<sup data-n=\"1771\">142</sup> ס\"ר<sup data-n=\"1772\">143</sup> (וכמ\"ש במ\"א עמ\"ש ליעקב אל תירא מרדה מצריימה<sup data-n=\"1773\">144</sup> כי לגוי גדול אשימך",[["1757","128","<b>נהרא נהרא ופשטי'</b>: חולין יח, ב. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשח. הנחות תקע\"ז ע' עז וע' פה."],["1758","129","<b>ארץ מגדלת חכמים</b>: כ\"ה בכ\"מ — ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרלד. וש\"נ. שעה\"י קמו, א. שע\"ת כ, א ובהנסמן במ\"מ לשם."],["1759","130","<b>וצו\"ד</b>: וצומח ודומם."],["1760","131","<b>וכמ\"ש במ\"א</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשח ואילך. בהנסמן בהערה 129."],["1761","132","<b>הוא הסובב. . הזהב</b>: בראשית ב, יא [בדילוג]."],["1762","133","<b>ואבן הבדולח</b>: בראשית שם, יב [ושם: שם הבדלח ואבן השהם]."],["1763","134","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["1764","135","<b>נשמתא דפרחא מחיי העולמים</b>: ראה זהר תרומה קלח, א. לקמן פ' בשלח קנט, ב. ויקהל תא, רע\"א."],["1765","136","<b>בע\"ח שהי' ראשו בבריאה</b>: ראה ע\"ח (שער מ\"ן ומ\"ד) של\"ט, דרוש א' (מ\"ק השני). ספר הגלגולים פי\"ח. מאמרי אדה\"א בראשית ע' עב. וש\"נ. שע\"ת קמה, א ובהערה 12. לקמן פ' בשלח קפ, ג. תרומה שיד, ב."],["1766","137","<b>ועקבו מכהה גלגל חמה</b>: ראה ויק\"ר פ\"כ, ב. זהר (רע\"מ) קדושים פג, ריש ע\"ב. מאמרי אדה\"א ויקרא ח\"ב ע' תרפו. וש\"נ. שער האמונה ק, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670154\" data-slug=\"torat-chaim\" data-id=\"2300670154\">תו\"ח בראשית לב, סע\"א</a> ואילך ובהערה 15."],["1767","138","<b>כשחטא בעה\"ד נתערב טו\"ר</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תדש. דברים ח\"א ע' סב. קונטרסים ע' תח ובהנסמן בהנ\"ל. לעיל ב, ג. לקמן פ' משפטים רפד, ד. שב, ד."],["1768","139","<b>כחנוך</b>: ב: נח."],["1769","140","<b>והוא</b>: ב: והן."],["1770","141","<b>ודור הפלגה. . נילוס. . יוצאי מצרים</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"א. לקמן פ' וארא פו, ג בשם הלק\"ת. בשלח קלג, ג. רלא, א. מאמרי אדה\"א ויקרא ח\"א ע' עג. שמות ח\"א ע' כה ובהנסמן בהנ\"ל."],["1771","142","<b>ה' פעמים</b>: ב: שם."],["1772","143","<b>יוצאי מצרים שהיו ה' פעמים ס\"ר</b>: ראה מכילתא בשלח יג, יח. ביאוה\"ז ויגש קלו, ב."],["1773","144","<b>אל תירא מרדה מצריימה</b>: ויגש מו, ג. ראה ביאוה\"ז שם. לקמן פ' בשלח קלג, ג. אוה\"ת ויגש כרך ו ע' תתשיא."]]],[2300540390,"שם, שם דוקא כל המחנה הקדושה דרפ\"ח כו' שנפלו בנילוס ולא בארץ כנען, וע\"י עבודה בחומר ו[ב]לבנים בגלות נתקנו כל הניצוצות הללו שהולידו שם בנים ובנות כו'), וזהו כללות ענין בחי' הבירורים דרפ\"ח כו' שנתלבשו בד' נהרות אחר שנתפרדו כו' והן אשר ירדו למטה בד' מלכיות מצרים<sup data-n=\"1774\">145</sup> ובבל [יון ו]אדום שהן ד' גליות ששרש יניקתם בד' נהרות<sup data-n=\"1775\">146</sup> הנ\"ל שנעשים בבחי' פירוד גמור אע\"פ שבהיותם בנהר שיוצא מעדן היו בתכלית היחוד אך משם יפרדו כו' להיות בבחי' נפרד ממש אחר החטא עה\"ד כמו דוגמת התלבשות הנשמה בגוף כנ\"ל וד\"ל.\n<b>והנה</b> כמו שמבואר למעלה בענין ד' נהרות שיצאו בבחי' פירוד מג\"ע הארץ להתפשט בכל חלקי העולם בכל א' בשיעור ומדה דוקא נהר זה הולך כך וכך פרסאות ובמקומות בארץ המיוחדות אליו שיסבב וילך שם עד כלותו זה כך וזה כך כו', כך הי' מניצוצות הקדושות שנפלו בד' נהרות מעולם התהו כנ\"ל שנתלבשו בהן הי' ג\"כ במספר שיעור ומדה לכל נהר ונהר מד' נהרות הללו, כמו לנהר מצרים שהוא פישון (והוא נהר נילוס) ירדו ונתלבשו בו כ\"כ מספר נשמות ניצוצות דאורות דתהו כו' (ונתבררו בגלות מצרים בהתלבשותם בגופים שילדו בנים כו' כמ\"ש וישב ישראל<sup data-n=\"1776\">147</sup> כו' ויפרו וירבו מאד כמ\"ש בזהר בענין ויברך יעקב את פרעה<sup data-n=\"1777\">148</sup> כו' ומבואר במ\"א באריכות) ולנהר בכל<sup data-n=\"1778\">149</sup> מספר כך וכך ניצוצות כו' (וכן ליון ואדום עד גלות זה האחרון<sup data-n=\"1779\">150</sup> כמ\"ש ויתהלכו מגוי אל גוי<sup data-n=\"1780\">151</sup> פי' ויתהלכו הניצוצות דתהו שבאים בגלגולים בגלות ישראל בין אוה\"ע ומולידים בנים תחת כל שר ושר כו' מגוי אל גוי כו' לא הניח לעשקם<sup data-n=\"1781\">152</sup> כו' כי יבוררו הכל מהם ולא ידח ממנו נדח<sup data-n=\"1782\">153</sup> כו' וכמ\"ש אשר שלט האדם באדם<sup data-n=\"1783\">154</sup> לרע לו כו' וכמו חיל בלע ויקיאנו<sup data-n=\"1784\">155</sup> כו', וזהו שא' צדקת פרזונו<sup data-n=\"1785\">156</sup> פזרונו<sup data-n=\"1786\">157</sup> צדקה עשה ה' עם ישראל שפזרן בגלות בין אומות העולם כו' וכמ\"ש וזרעתי' [לי] בארץ<sup data-n=\"1787\">158</sup>, <span data-k=\"pg\">נו</span> ּ וכלום אדם זורע קב<sup data-n=\"1788\">159</sup> אלא להוציא כמה כורין כו', וזהו שארז\"ל כדי להוסיף עליהם גרים<sup data-n=\"1789\">160</sup> כו' שהן ניצוצות דקדושה הנ\"ל שיוצאים מכל שר ואומה בנפש הנולד מישראל",[["1774","145","<b>בד' מלכיות מצרים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161091\" data-slug=\"likkutei-sichot\" data-id=\"1300161091\">לקו\"ש וארא (כרך טז) ע' 91</a>."],["1775","146","<b>בד' מלכיות. . בד' נהרות</b>: ראה ב\"ר פט\"ז, ד. יל\"ש בראשית ב, יד (רמז כב) ושם: מלכיות."],["1776","147","<b>וישב ישראל</b>: ויגש מז, כז."],["1777","148","<b>ויברך יעקב את פרעה</b>: ויגש מו, ז. זהר ויגש ריא, ב. ראה ביאוה\"ז שם קלו, א ואילך."],["1778","149","<b>בכל</b>: אד: בבל."],["1779","150","<b>האחרון</b>: אוצ\"ל: האחרון)."],["1780","151","<b>ויתהלכו מגוי אל גוי</b>: תהלים קה, יג. דהי\"א טז, כ. ראה גם לקמן פ' בשלח קלג, ג. רלב, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680051\" data-slug=\"torat-chaim\" data-id=\"2300680051\">תו\"ח מקץ רטו, ג</a>. מאמרי אדה\"א דברים ח\"ד ע' א'תסא. בראשית ע' קסו."],["1781","152","<b>לא הניח לעשקם</b>: תהלים שם, יד. דהי\"א שם, כא [בדילוג — ראה גם לקמן פ' בשלח קלד, א]."],["1782","153","<b>ולא ידח ממנו נדח</b>: ע\"פ שמואל-ב יד, יד."],["1783","154","<b>אשר שלט האדם באדם</b>: נסמן לעיל ל, ד."],["1784","155","<b>חיל בלע ויקיאנו</b>: איוב כ, טו. ראה סידור סדר סעודת שבת רג, ב. מאמרי אדה\"א בראשית ע' תקכא. וש\"נ. שע\"ת נא, א ובהנסמן במ\"מ לשם."],["1785","156","<b>צדקת פרזונו</b>: ס' שופטים ה, יא. ראה פסחים פז, ב. לקמן פ' בשלח רלב, ב."],["1786","157","<b>פרזונו פזרונו</b>: ראה פסחים שם. וראה ג\"כ שע\"ת פ, ד ובהנסמן במ\"מ לשם."],["1787","158","<b>וזרעתי' [לי] בארץ</b>: הושע ב, כה."],["1788","159","<b>וכלום אדם זורע קב</b>: ראה פסחים שם. לקמן פ' בשלח קלג, ג. רלא, ב. משפטים רצו, א. מאמרי אדה\"א דברים ח\"ג ע' תתקו. ח\"ד ע' א'תלד. ובהנסמן בהנ\"ל."],["1789","160","<b>כדי להוסיף עליהם גרים</b>: פסחים שם. ראה גם לקמן פ' בשלח קלג, ג. רלב, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370022\" data-slug=\"torah-or\" data-id=\"3901370022\">תו\"א ו, א</a>. יא, ב. קיז, ב. מאמרי אדה\"א דברים ח\"ב ע' תכב. וש\"נ. שע\"ת קמב, רע\"ד. תו\"ח נח נח, ב. ח\"ש קכא, ג ובהערה 32."]]],[2300540410,"כו' (וכמשי\"ת בסמוך בפי' אז יאמרו בגוים כו') ובכאו\"א לפי שיעור מהלכו והתחלקותו בארץ וד\"ל (וכך הוא ממש בעולם העליון הרוחני כמו בג\"ע דיצי' וג\"ע דבריאה<sup data-n=\"1790\">161</sup> שהם ג\"כ נהר יוצא מעדן כו' ומשם יפרד לד' נהרות כו' כנ\"ל בג\"ע הארץ דעשי', ויש לכל נהר שיעור מהלכו בארץ העליונה כו' רק ששם הוא בבחי' הרוחניות יותר ויורד ומשתלשל מעולם לעולם עד ד' נהרות הגשמיים כידוע ומבואר במ\"א). אך הנה כל עיקר ענין ירידת והתלבשות הניצוצו' הנ\"ל בד' נהרות היו לצורך עלי' דוקא כנ\"ל, והיינו שיעלו ויבואו לבחי' ומדרגה עליונה ביותר מכמו שהי' תחלה במקורן קודם ירידתן למטה כו', והיינו ע\"י שהם עולים אחר ירידתן מלמטה למעלה מתהום רבה שהוא מ\"ש כל הנחלים הולכים אל הים ואל מקום שהנחלים הולכים שם הם שבים<sup data-n=\"1791\">162</sup> כו', דאחר המשכות ד' נהרות למטה בים האחרון חוזרים משם ללכת למקורם בנהר הראשון שיוצא מעדן (כמ\"ש והנהר הד' הוא נהר פרת<sup data-n=\"1792\">163</sup> הוא דמעיקרא<sup data-n=\"1793\">164</sup> ולע\"ל יעברו בנהר פרת<sup data-n=\"1794\">165</sup> כו' כמ\"ש במ\"א) ועולים משם בתוס' עילוי גדול הרבה יותר מכמו שהי' בתחלה בירידתן בנהר זה כו' משום דבחי' או\"ח דמ\"ת<sup data-n=\"1795\">166</sup> יעלו למעלה יותר וכמ\"ש ביום ההוא יצאו מים חיים<sup data-n=\"1796\">167</sup> מירושלים חציים אל הים הקדמוני שהוא מ\"ע דמעל השמים שהוא בחי' התהו כו' [(וכמ\"ש במ\"א ע\"פ לרוקע הארץ<sup data-n=\"1797\">168</sup> כו'<sup data-n=\"1798\">169</sup> )].\n<b>ויובן</b> זה מענין התלבשות הנשמה בגוף כנ\"ל שאע\"פ שבירידה זו נחשך אורה ביותר כנ\"ל, אבל הוא לצורך עלי' שתתעלה עי\"ז דוקא למעלה ממקור חוצבה למעלה שהיתה קשורה ודבוקה שם כנ\"ל, והוא [ע\"י] ענין התשובה דוקא כידוע, והענין הוא לפי שהתשובה היא לאהפכא חשוכא לנהורא כו' שהוא מואס ברע שזהו<sup data-n=\"1799\">170</sup> מהפך לרע [עצמו] להיות טוב ע\"י העלאות והתכללות דבחי' או\"ח למעלה ממש, וכראב\"ד שיצתה נשמתו בבכי'<sup data-n=\"1800\">171</sup> וכה\"ג, שעי\"ז יעלה לשרשו בבחי' אורות דתהו קודם השבירה שהוא בבחי' ס\"ג שלמעלה משם מ\"ה<sup data-n=\"1801\">172</sup>, ועולה עוד למעלה בעצמות א\"ס ממש שכל או\"ח חוזר לקדמותו<sup data-n=\"1802\">173</sup>",[["1790","161","<b>וג\"ע דבריאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380917\" data-slug=\"likkutei-torah\" data-id=\"4001380917\">לקו\"ת נצבים מט, ג</a>. לקמן רט, א."],["1791","162","<b>כל הנחלים. . ואל. . שבים</b>: קהלת א, ז [בדילוג. ושם: אל]."],["1792","163","<b>והנהר הד' הוא נהר פרת</b>: בראשית ב, ז [ותיבת נהר ליתא שם. וכ\"ה בכת\"י: בהזי — אבל בהוספת תיבת נהר הובא גם במאמרי אדה\"א ויקרא ח\"א ע' קנח]."],["1793","164","<b>הוא דמעיקרא</b>: בכורות נה, ב."],["1794","165","<b>ולע\"ל יעברו בנהר פרת</b>: ראה ישעי' יא, טו ובמפרשים שם. מאמרי אדה\"א ויקרא ח\"א ע' רכ. דברים ח\"א ע' טו ואילך (ובהנסמן שם). שער האמונה פג, סע\"א ואילך ובהערה 3. שם צה, ב ואילך. לעיל א, ב, כג, א. לקמן פ' בא קי, א. בשלח קמט, ב. קעח, א. קפה, ג. רכד, ג. רל, ד. תצוה שכד, ד. ויקהל תט, ב. תי, ד."],["1795","166","<b>משם. . דמ\"ת</b>: גהוז: לשם. . הזי: דמ\"ח."],["1796","167","<b>ביום ההוא יצאו מים חיים</b>: זכרי' יד, ח."],["1797","168","<b>לרוקע הארץ</b>: תהלים קלו, ו. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תקלד."],["1798","169","<b>כו'</b>: י: עה\"מ ( על המים). חט: כל החצאי עיגול ליתא."],["1799","170","<b>שזהו</b>: ג: שבזה. ט: שזה."],["1800","171","<b>וכראב\"ד שיצתה נשמתו בבכי'</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["1801","172","<b>ס\"ג שלמעלה משם מ\"ה</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' ה (הערה ד\"ה שם)."],["1802","173","<b>שכל או\"ח חוזר לקדמותו</b>: ראה מאמרי אדה\"א בראשית ע' תנג ”לכלל המונח בס' קבלה ובס' חקירה\". <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670125\" data-slug=\"torat-chaim\" data-id=\"2300670125\">תו\"ח נח ס, ב</a> ובהערה 22. 23. שע\"ת קכט, א. שה\"א כט, א. נז, ב לקמן פ' בשלח קנג, א. קעז, א. רכ, ג."]]],[2300540430,"ממש כו', וזהו שארז\"ל בז' דברים שקדמו לעולם<sup data-n=\"1803\">174</sup> וא' מהן התשובה כו', שמטעם זה בע\"ת גדולים מצד\"ג<sup data-n=\"1804\">175</sup> שאין יכולים לעמוד כלל במקום שבע\"ת עומדים כו' וכמ\"ש בזהר משום דבע\"ת משכי[ן] לי' לקוב\"ה בחילא יתיר<sup data-n=\"1805\">176</sup> פי' בכח רב ועצום מאד שאין זה בכח העלא[ת מ\"ן] דאוי\"ר ותומ\"צ דצ\"ג, וכמו שנתקנא רבי בבע\"ת אמיתי זה דראב\"ד ואמר יש קונה עולמו<sup data-n=\"1806\">177</sup> בשעה אחת כו', והיינו לפי שהעלאה דבע\"ת הוא בבחי' עצמיות הנפש דבחי' יחידה עד כלותו ממש שלמעלה מהגבלת אורות בכלים כו', וזהו בחילא יתיר מכפי המדה דאו\"כ והוא בבחי' אורות מקיפים דתהו שלמעלה מהגבלת אורות וכלים כו', וצ\"ג הן מבחי' התיקון שהוא בחי' המשכות אורות בכלים דוקא ע\"י תומ\"צ שהן בחי' כלים מכלים שונים לבחי' גילוי אור הוי' ממש ונק' תורת הוי'<sup data-n=\"1807\">178</sup> מצות הוי'<sup data-n=\"1808\">179</sup> דרכי הוי'<sup data-n=\"1809\">180</sup> כידוע, אבל שורש העלאות דבע\"ת הוא במקיפי'<sup data-n=\"1810\">181</sup> דבחי' התהו ששם האור בא בבחי' מול\"מ<sup data-n=\"1811\">182</sup> כידוע, והענין הוא כמו ורוח אלקים מרחפת<sup data-n=\"1812\">183</sup> ע\"פ המים נוגע ואינו נוגע כו', לפי שאין גילוי אור המאציל עדיין בא בבחי' התיישבות אור בכלי ממש, אלא בבחי' צמצום והסתלקות בעצמותו עדיין, וזהו ענין מטי ומיד לא מטי שחוזר ומסתלק כענין זה דמרחפת נוגע ואינו נוגע כו' וכמ\"ש בע\"ח<sup data-n=\"1813\">184</sup> ומבואר במ\"א, וזהו ענין ובחי' העלאה והסתלקות דבע\"ת כו' שא\"א לאור להתיישב בכלי כלל, וכמו אה\"ר דבכל מאדך<sup data-n=\"1814\">185</sup> <span data-k=\"pg\">114</span> ּ למעלה מהגבלת הכלי כו', וזהו פי' תשובה תשוב ה'<sup data-n=\"1815\">186</sup> למקורה ממש כמו והרוח תשוב אל האלקים<sup data-n=\"1816\">187</sup> כו' בבחי' או\"ח שחוזר לקדמותו ממש שהוא עצמות א\"ס ב\"ה שלמעלה מהגבלת אורות בכלים, שהוא למעלה גם מבחי' קו\"ח שנק' קו המדה<sup data-n=\"1817\">188</sup> למדוד או\"כ כו', כי באתעדל\"ת אתעדל\"ע<sup data-n=\"1818\">189</sup> ג\"כ באופן זה ממש, וע\"כ זהו הטעם דכח<sup data-n=\"1819\">190</sup> אור<sup data-n=\"1820\">191</sup> דבע\"ת מגיע למעלה מעלה מבחי' או\"י דתו\"מ דצ\"ג כנ\"ל וד\"ל.\n<b>וזהו</b> שא' דתשובה קדמה לעולם אפי' לעולם הנאצל כו' והוא בבחי' מטי ולא מטי הנ\"ל, וע\"כ א' בר\"מ דגם משה זכה לתשובה<sup data-n=\"1821\">192</sup> רק קודם מותו דכתיב בג' ערי מקלט ושמתי לך",[["1803","174","<b>בז' דברים שקדמו לעולם</b>: ראה פסחים נד, א. מאמרי אדה\"א דברים ח\"ד ע' א'קסד. וש\"נ."],["1804","175","<b>בע\"ת גדולים מצ\"ג</b>: ראה ברכות לד, ב. לקו\"ש נצבים (כרך יד) ע' 361 וע' 363. לקמן פ' בשלח קס, ב. שע\"ת כט, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670356\" data-slug=\"torat-chaim\" data-id=\"2300670356\">תו\"ח בראשית ו, ד</a> הערה 32."],["1805","176","<b>דבע\"ת. . בחילא יתיר</b>: נסמן לעיל לז, א הערה 27."],["1806","177","<b>יש קונה עולמו</b>: ע\"ז יז, א. ראה לקמן פ' בשלח קס, ב."],["1807","178","<b>תורת הוי'</b>: בא יג, ט."],["1808","179","<b>מצות הוי'</b>: ויקרא ד, ב. יג. כב. ועוד."],["1809","180","<b>דרכי הוי'</b>: שמואל-ב כב, כב. הושע יד, י. תהלים יח, כב."],["1810","181","<b>במקיפי'. . מול\"מ</b>: ראה גם לקמן מו, א ובהנסמן לשם."],["1811","182","<b>מול\"מ</b>: ראה זהר בראשית טז, ב. נח סה, א. מאמרי אדה\"א שמות ח\"א ע' רפ. וש\"נ. קונטרסים ע' רפו."],["1812","183","<b>ורוח אלקים מרחפת</b>: בראשית א, ב. ראה ב\"ר פ\"ב, ד. רש\"י האזינו לב, יא."],["1813","184","<b>וכמ\"ש בע\"ח</b>: ראה שם (שער מטי ולא מטי) ש\"ז, פ\"א. וראה גם בהנסמן לעיל הערה 182. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670552\" data-slug=\"torat-chaim\" data-id=\"2300670552\">תו\"ח נח נז, ב</a>."],["1814","185","<b>אה\"ר דבכל מאדך</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קצה. דר\"מ קס, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">תו\"א מקץ לט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380482\" data-slug=\"likkutei-torah\" data-id=\"4001380482\">לקו\"ת שלח מב, ג</a>."],["1815","186","<b>תשובה תשוב ה'</b>: ראה זהר (רע\"מ) נשא קכב, א."],["1816","187","<b>והרוח תשוב אל האלקים</b>: קהלת יב, ז."],["1817","188","<b>קו\"ח שנק' קו המדה</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרסט. ש\"א מט, ב. שער האמונה עג, ב ואילך ובהערה 25. לעיל כט, א. לקמן פ' בשלח קנה, ב. קסה, א. קצב, ד."],["1818","189","<b>באתעדל\"ת אתעדל\"ע</b>: ראה זהר לך פח, א. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. נ\"ך ע' לה. וש\"נ. קונטרסים ע' תקעב. לקמן פ' בא צד, ב. תרומה שיב, א."],["1819","190","<b>דכח</b>: גו: דבחי'."],["1820","191","<b>אור</b>: גוזחי: או\"ח."],["1821","192","<b>משה זכה לתשובה</b>: נסמן לעיל לז, א."]]],[2300540450,"מקום<sup data-n=\"1822\">193</sup> לך דוקא כו', והענין הוא דכל בחי' משה הוא להמשיך גילוי אור א\"ס בתומ\"צ ואוי\"ר שזהו בחי' או\"י דצ\"ג, וגם שמשה הי' גדול מכל הצ\"ג כמ\"ש פא\"פ אדבר בו כו' בכל ביתי נאמן<sup data-n=\"1823\">194</sup> כו', לא המשיך רק בבחי' גילוי אוא\"ס בקו\"ח כו' להביא התלבשות האורות בכלים באמצעות תומ\"צ שהוא עיקר בחי' התיקון דשם מ\"ה כו' כמ\"ש מה שמו<sup data-n=\"1824\">195</sup> כו' ולא למעלה מזה כלל, רק קודם מותו שנתעלה נשמתו יותר זכה לתשובה שהוא בחי' או\"ח לעצמות א\"ס ב\"ה ממש שלמעלה מבחי' הקו\"ח כו' וד\"ל. וזהו עיקר יתרון מעלת משיח על משה שהרי בז' [דברים] שקדמו לעולם הזכיר שמו של משיח כו' שהרי נאמר בו ישכיל עבדי כו' וגבה מאד<sup data-n=\"1825\">196</sup> למעלה מבחי' אדם דתומ\"צ דמ\"ה דמשה כו', והוא ע\"י התשובה דוקא שאם ישראל עושים תשובה נגאלים<sup data-n=\"1826\">197</sup> כו', והיינו מ\"ש בר\"מ דמלכא משיחא אתא לאתבא צדיקייא בתיובתא<sup data-n=\"1827\">198</sup> כו' (ודוקא לצ\"ג שיהי' בע\"ת כמו משה שהי' צ\"ג וזכה לתשובה, אבל בע\"ת לבד לא יעלו כ\"כ למעלה כמ\"ש במ\"א בענין ראה ריח בני<sup data-n=\"1828\">199</sup> כריח שדה כו' שהי' יעקב צ\"ג ונתלבש בב\"ע<sup data-n=\"1829\">200</sup> להיות בע\"ת כו' עי\"ז הי' כריח שדה העליונה אשר ברכו ה' בבחי' התיקון דתו\"מ, כי יש שורש לשם מ\"ה דשם הוי' דתו\"מ בעצמות א\"ס ב\"ה ממש שלמעלה גם מבחי' התהו שהוא הצמצום הראשון שנק' מקו\"פ<sup data-n=\"1830\">201</sup> כו' וכמ\"ש יעקב ואנכי איש חלק כו' וכמ\"ש כי חלק ה' עמו<sup data-n=\"1831\">202</sup> כו', רק שעלי' שלהם הוא ע\"י בירור דרפ\"ח דתהו דוקא וד\"ל).\n[ו] <b>ובכ\"ז</b> יובן מ\"ש בשוב ה' כו' אז יאמרו בגוים דוקא הגדיל ה' לעשות עם אלה שהן בנ\"י בבחי' עלי' וגדלות שיתגדלו עד למעלה מעלה בעצמות א\"ס כו', והטעם הוא כפי הנ\"ל שניצוצות דתהו ירדו בד' נהרות להתברר בד' גליות במצרים כו' מפני שנפלו כ\"כ להיות שרשית<sup data-n=\"1832\">203</sup> לד' מלכיות כו', אך הרי ירידה זו לצורך עלי' היא והוא ע\"י התשובה שהיא בבחי' או\"ח למעלה ממש (וכמו הד' נהרות שחוזרים ועולים מלמטה למעלה בבחי' או\"ח שז\"ש יצאו מים חיים כו' למעלה מעלה ממקורם כו'), וא\"כ הרי מה שהגדיל ה' לעשות עם אלה",[["1822","193","<b>ושמתי לך מקום</b>: משפטים כא, יג."],["1823","194","<b>פא\"פ. . בכל ביתי נאמן</b>: בהעלותך יב, ח. ז."],["1824","195","<b>מה שמו</b>: שמות ג, יג. משלי ל, ד."],["1825","196","<b>ישכיל. . וגבה מאד</b>: ישעי' נב, יג. ראה גם שה\"א פט, א. וראה גם בהנסמן לשם."],["1826","197","<b>שאם ישראל עושים תשובה נגאלים</b>: נסמן לעיל לז, א הערה 37."],["1827","198","<b>לאתבא צדיקייא בתיובתא</b>: ראה זהר (רע\"מ) בהעלותך קנג, ב. מאמרי אדה\"א קונטרסים ע' רפא. וש\"נ. הנחות תקע\"ז ע' צה. שע\"ת פד, א. ש\"א לח, ב. תו\"ח בראשית ז, א ובהערה 34. לקמן מד, ב. פ' וארא סה, ד. בשלח (קסא, א). קעז, ב. תצוה שכד, ד. שדמ, א (כר\"מ). פלח הרמון בשלח ע' שיב בשם רז\"ל."],["1828","199","<b>בענין ראה ריח בני</b>: מאמרי אדה\"ז תקס\"ה ח\"א ע' לח ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370095\" data-slug=\"torah-or\" data-id=\"3901370095\">תו\"א תולדות כ, ג</a>."],["1829","200","<b>בב\"ע</b>: גט: בבגדי עשו."],["1830","201","<b>הצמצום הראשון שנק' מקו\"פ</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["1831","202","<b>ואנכי איש חלק. . כי חלק ה' עמו</b>: תולדות כז, יא. האזינו לב, ט. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680078\" data-slug=\"torat-chaim\" data-id=\"2300680078\">תו\"ח וישלח קפא, ב</a> ובהערה 32 לקמן פ' תצוה שכד, ג."],["1832","203","<b>שרשית</b>: גה: שרשים. ט: שרשי'."]]],[2300540470,"הניצוצות בהתלבשותם בכנס\"י בכל דור ודור בהיותם בד' גליות כנ\"ל לא הי' רק מן הגוים שהן הע' שרים שמקבלים מד' נהרות כנ\"ל, ע\"כ מאד יחרה לגוים בהיות [ש]יראו שמהם ועל ידם הי' כל יתרון האור [הרב<sup data-n=\"1833\">204</sup> ] הזה שהגדיל הוי' לעשות עם אלה כו' ועשו אותן ריקן מכל טוב דקדושה וכמו וינצלו כו' שעשאום כמצולה כו', וזהו שא' אז יאמרו בגוים דוקא הגדיל כו' כי מהם דוקא נעשה כל הגדלה [ה]זאת כנ\"ל ע\"כ הם דוקא יאמרו זה ויתפלאו מאד <span data-k=\"pg\">נז</span> ּ ולא זולתם וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן שרש ענין כללות האותות והמופתים שהיו במצרים כו', דהנה מבואר למעלה בענין ירידת [ו]התלבשות הניצוצות דתהו בד' נהרות דג\"ע בד' גליות כדי להתברר ולהיות מזה יתרון אור גדול ורב מכמו שהי' תחלה כו' והוא ירידת התלבשות הנשמה בגוף שירידה זו לצורך עלי' דוקא כנ\"ל. והנה ידוע שזהו עד\"מ הפרי בקליפתה כמו האגוז שתחילת צמיחת הפרי מעורב בקליפתו בתכלית ומכוסה ונעלם בחי' הטוב דפרי ברע דקליפת האגוז ולא ניכר הפרי כלל עד שיוגמר גידולו אז יופרד הטוב דפרי מן הקליפה והקליפה הולך וקשה ונפרד בפ\"ע והטוב דפרי נעשה נקי מכל פסולת דקליפה שלה בתכלית ויבא בפרי גילוי טוב טעמה בתכלית כאשר נגמר בישולה כל צרכה דוקא (וכמו הולד במעי אמו שמעורב בפסולת הדמים דשליא כו' ויוצא נקי בהולדו כו'), ואז צריך לשבור הקליפה כדי להוציא הפרי שהוא הטוב הגנוז בה ובלעדי השבירה א\"א ליטול הפרי מתוכה וזה דוקא אחר גמר הפרי, אבל בתחילת צמיחתה הרי הפרי מעורב בקליפה כו'. וכך יובן הנמשל בהתלבשות בניצוצות הקדושה בד' נהרות בד' מלכיות הנ\"ל וכמו התלבשות הנשמה בגוף כו' שמפני ירידת ונפילת האור למטה עד בחי' ק\"נ דעשי' שהן ד' מלכיות כו' כדי להתברר כנ\"ל הרי הי' תחלה מעורב הטוב ברע בתכלית והיינו מפני סיבת חטא עה\"ד טו\"ר כו' כנ\"ל עד שלא ניכר הטוב ברע כלל כמשל צמיחת הפרי בתערובות עם קליפתו כנ\"ל באגוז כדי שיבוררו בטוב, וכמו ירידת הנשמה האלקי' בחומר הגוף שמתערב טוב ברע והיו לאחדים ממש כו' וד\"ל. אך ענין ירידה זאת הי' לצורך עלי' דוקא כנ\"ל זהו לאחר שנשלם הבירור דניצוצות בק\"נ שזהו כמו גמר הפרי בתוך קליפתו כנ\"ל שנפרד בחי' הטוב מן הרע לגמרי, רק שם מכוסה ונעלם בקליפתו כמו פרי האגוז כשנגמר בישולו דוקא כנ\"ל שאז צריכים לשבור הקליפה כדי שיתגלה הפרי כו', כך הוא ענין שבירת הקליפה לגמרי כדי להוציא בחי' הטוב דניצוצות הנ\"ל שמכוסים ונעלמים שם כשנגמר ונשלם הבירור שלהם דוקא ולא קודם תשלום הבירור שעדיין מעורב הטוב ברע כו' וד\"ל.",[["1833","204","<b>הרב</b>: כ\"ה בהזי. ג: הרם."]]],[2300540488,"[ז] <b>וזהו</b> שרש ענין האותות ומופתים שהיו במצרים שהוא לשבור לבחי' קליפה דשר של מצרים וכמ\"ש ובכל אלקי מצרים<sup data-n=\"1834\">205</sup> כו' ואי' בזהר דתבר שלשליהון דלעילא<sup data-n=\"1835\">206</sup> כו' כדי להוציא לס\"ר ניצוצות דקדושה שהן בנ\"י יוצאי מצרים (ששרשם בניצוצות שנפלו בנהר נילוס כנ\"ל) שהיו מכוסים ונעלמים בהם כו' והיו שולטים בהם בכל עבודה קשה בחומר ובלבנים<sup data-n=\"1836\">207</sup> כו', שהוא ענין אשר שלט האדם באדם לרע לו דוקא וכנ\"ל בענין אז יאמרו בגוים דוקא הגדיל הוי' לעשות עם אלה כו' וד\"ל. וזהו [שא'] או הנסה [אלקי'<sup data-n=\"1837\">208</sup> ] לבוא לקחת לו גוי מקרב גוי במסות [ובאותות] כו', פי' גוי מקרב גוי פרי מקליפתו שהרי היו<sup data-n=\"1838\">209</sup> משוקעים ונבלעים בנ' שע\"ט<sup data-n=\"1839\">210</sup> דקליפת מצרים כו' וכתיב וינצלו את מצרים שעשאום כמצולה כו' שהעלו מהם כל בחי' הטוב דקדושה ונשארו ריקן מכל טוב העליון כו' וד\"ל. וזה הי' ענין כללות אותות ומופתים שהוא רק לשבר כח הקליפה שבשר של מצרים שהוא מקבל מנהר נילוס כו', והוא היפך דרכי הטבע לשנות סדר ההשתלשלו' השפע שנמשך ע\"י ד' נהרות הנ\"ל, והוא ע\"י שהי' המופת הראשון שנהפך היאור לדם<sup data-n=\"1840\">211</sup> דוקא שבזה נשבר כח ושרש יניקת פרעה בנהר נילוס למעלה במה שנהפך לדם כו' (אחר שעשה מופת בהפיכת המטה לנחש<sup data-n=\"1841\">212</sup> ומנחש למטה כו'), ועד\"ז כל המסות ומופתים שהי' רק לשבור בחי' <span data-k=\"pg\">116</span> ּ הע' שרים דקליפת מצרים כדי להוציא הטוב הגנוז בהם שהם הניצוצות הנ\"ל וכמ\"ש וינצלו כו' וד\"ל (רק שהוצרך להיות תחלה עבודה קשה בחומר ובלבנים שזהו כדי שיוכלו לצאת מן הרע דנש\"ט במה שצעקו בתשובה שלימה כו').\n<b>והנה</b> האות<sup data-n=\"1842\">213</sup> הראשון הי' בהפיכת המטה לתנין, ויש להבין למה לתנין דוקא ולא לדבר אחר ולמטה משה<sup data-n=\"1843\">214</sup> דוקא, אך הנה האות הזה מורה על כללות ענין ירידת והתלבשות האורות עליונים בכלים מכלים שונים בריבוי הצמצומים וההעלמות העלם אחר העלם וירידה אחר ירידה כו' עד שבאו להתלבש בד' נהרות שיוצאים בבחי' פירוד מאלקות וכמ\"ש ומשם יפרד<sup data-n=\"1844\">215</sup> כו' שהן ע' שרים דנוגה דעשי', שעכ\"ז אינו בבחי' פירוד ממש מאלקות ח\"ו אלא אדרבה עדיין כמו שהן למטה מטה אחוז וקשור הכל ביחוד עליון דעצמות א\"ס ב\"ה בלי שום פירוד ליש ודבר בפ\"ע כלל וכלל ח\"ו כי אין לך דבר חוץ ממנו ית' שהרי נאמר את זה לעו\"ז<sup data-n=\"1845\">216</sup> עשה האלקים עד בחי' הצמצום ו[ה]הסתר היותר אחרון הכל עשה האלקים כו', וע\"כ הגם שמאד רבו הצמצומים וההתלבשות עד החיצוני' דחיצוניות דנוגה כו' לא נפרדו מיחודו ית' כלל וכלל כו' וד\"ל.",[["1834","205","<b>ובכל אלקי מצרים</b>: בא יב, יב."],["1835","206","<b>דתבר שלשליהון דלעילא</b>: ראה זהר בא לז, ב. מ, א. בשלח מט, א."],["1836","207","<b>בכל עבודה קשה בחומר ובלבנים</b>: שמות א, יד."],["1837","208","<b>או הנסה [אלקי']</b>: ואתחנן ד, לד [ושם: באותות]."],["1838","209","<b>היו</b>: י: ישראל. גז: ניתוסף: ישראל."],["1839","210","<b>בנ' שע\"ט</b>: ראה ז\"ח יתרו לא, א. לעיל יז, ד. לקמן פ' וארא סג, ד. בשלח קצא, ב. משפטים רפט, א. מאמרי אדה\"א דברים ח\"ד ע' א'רסב. וש\"נ. שה\"א יג, ב ובהערה 23."],["1840","211","<b>שנהפך היאור לדם</b>: וארא ז, כ."],["1841","212","<b>מופת בהפיכת המטה לנחש</b>: וארא ז, ב ואילך."],["1842","213","<b>האות</b>: אבל לעיל בשו\"ה למעלה: מופת. וראה גם לעיל לז, ב ובהערה 50."],["1843","214","<b>ולמטה משה</b>: גזי: ולמה (ל)מטה. וראה גם לקמן מב, ב שו\"ה בחכ' — מטה משה."],["1844","215","<b>ומשם יפרד</b>: בראשית ב, י."],["1845","216","<b>את זה לעו\"ז</b>: קהלת ז, יד."]]],[2300540506,"[ח] <b>וזהו</b> ענין האות המורה על זה שהוא הפיכת המטה לתנין דוקא, דהנה ידוע בפי' מטה לשון הטי'<sup data-n=\"1846\">217</sup> כמו מטה כלפי חסד<sup data-n=\"1847\">218</sup> וכמו ענפי האילן כו' וכאשר כורתין אותו מן האילן הרי שרשו העב למעלה וראשו למטה הוא הנק' מטה שביד האדם ומשענת<sup data-n=\"1848\">219</sup> הילוכו כידוע (משא\"כ שבט הוא הענף בעודו מחובר באילן שראשו למעלה, וע\"כ נק' שבטי יעקב<sup data-n=\"1849\">220</sup> שפונים ועולים למעלה נופו בתר עיקרא<sup data-n=\"1850\">221</sup> כו') וענף קטן מן הגדול נק' שבט כמו כוכבא דשביט<sup data-n=\"1851\">222</sup> והוא נטי' פרטית יותר מן האילן כו'. וכך הוא למעלה בבחי' הטי' של אור ושפע האלקי' הבא ונמשך מלמעלה למטה בירידה והתלבשות אורות בכלים מכלים שונים נק' מטה והוא הנק' מטה האלקי'<sup data-n=\"1852\">223</sup> בכלל (וזהו<sup data-n=\"1853\">224</sup> בחי' מטה משה (בחי' יסוד אבא<sup data-n=\"1854\">225</sup> ) שכולל כל פרטי ההטיות שנוטה ונמשך השפע בכמה אופנים מדרגות שונות והוא ע\"י בחי' הדעת שרש נשמת משה<sup data-n=\"1855\">226</sup> כנ\"ל<sup data-n=\"1856\">227</sup> שנק' דעת נוטה<sup data-n=\"1857\">228</sup> לחו\"ג בכמה אופנים שונים, כמ\"ש ובדעת חדרים ימלאון<sup data-n=\"1858\">229</sup> כו', ויורד ומשתלשל מעילה לעילה בריבוי צמצומים והתלבשו' מאצי' לבי\"ע עד שיבא האור והשפע האלקי' למטה מטה ביותר, והוא עד ע\"ש דק\"נ דעשי' שהן מקבלים מד' נהרות דג\"ע דעשי' כנ\"ל שהוא צמצום היותר אחרון כידוע וד\"ל. וזהו ענין האות הזה שהראה להם משה שנהפך המטה שבידו לתנין, שבחי' מטה העליון דמשה איש האלקי'<sup data-n=\"1859\">230</sup> כנ\"ל נהפך להיות בחי' צמצום והסתר שלו היותר אחרון שהוא התנין שהוא שרש שר של מצרים שמקבל מנהר נילוס כו' וכמ\"ש התנים הגדול<sup data-n=\"1860\">231</sup> הרובץ בתוך יאוריו כו' שקליפת מצרים נק' תנים הגדול כמ\"ש בזהר<sup data-n=\"1861\">232</sup> שהוא בבחי' פירוד גדול מאלקו' בחוצפא וגסות לומר לי יאורי<sup data-n=\"1862\">233</sup> כו', עכ\"ז גם אז איננו בבחי' פירוד כלל וכלל מאלקות שהרי חזר ונהפך התנין למטה כמו שהוא בבחי' ביטול בתכלית בראשית המשכת והטיית אור השפע האלקי' בבחי' מטה משה כו', ונמצא אין כל הצמצומי' מסתירים כלל ויכול להיות בחי' ביטול בתכלית לאלקות גם בצמצום והסתר היותר אחרון כמו שהוא למעלה",[["1846","217","<b>מטה לשון הטי'</b>: נסמן לקמן פ' בשלח קמז, ב."],["1847","218","<b>מטה כלפי חסד</b>: ר\"ה יז, א."],["1848","219","<b>ומשענת</b>: גהי: למשענת."],["1849","220","<b>שבטי יעקב</b>: ישעי' מט, ו."],["1850","221","<b>נופו בתר עיקרא</b>: שבת ד, ב. ח, א. ב\"מ קיח, ב."],["1851","222","<b>כוכבא דשביט</b>: ברכות נח, ב."],["1852","223","<b>מטה האלקי'</b>: שמות ד, כ."],["1853","224","<b>(וזהו</b>: גהזחטי: וזהו."],["1854","225","<b>מטה משה. . יסוד אבא</b>: ראה ע\"ח (שער הארות המוחין זו\"ן) של\"ב, פ\"ב. מאו\"א מערכת מטה סס\"ד."],["1855","226","<b>הדעת שרש נשמת משה</b>: נסמן לקמן פ' וארא פה, ד."],["1856","227","<b>כנ\"ל</b>: לע\"ע לא נתברר לאיזה מאמר כוונתו. ולהעיר שענין זה נמצא במאמרי אדה\"א בראשית ע' קצח. ושם בריש המאמר [ע' קצה] נרשם: פ' וארא [וירא ] תקפ\"ב. ולהעיר מלעיל לה, ב הערה 406."],["1857","228","<b>דעת נוטה</b>: ראה גם לקמן פ' וארא פה, ד. בא פט, א. בשלח ר, סע\"א ואילך. ריט, ד. משפטים רפג, ד. תצוה שנד, א. שעו, ב. ויקהל תלז, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670147\" data-slug=\"torat-chaim\" data-id=\"2300670147\">תו\"ח וירא קי, ג</a> ואילך. שה\"א פב, ב."],["1858","229","<b>ובדעת חדרים ימלאון</b>: משלי כד, ד [ושם: ימלאו — ראה לקמן נז, ד. שנד, ב. שסא, ב [ושם נדפס מגוכתי\"ק]. שעז, ב. מאמרי אדה\"א בראשית ע' ג. שמות ח\"ב ע' תרנז. דברים ח\"ד ע' א'רמב. הנחות תקע\"ז ע' שנה ובהנסמן בהנ\"ל. שע\"ת טו, ב]."],["1859","230","<b>דמשה איש האלקי'</b>: ברכה לג, א."],["1860","231","<b>התנים הגדול</b>: יחזקאל כט, ג."],["1861","232","<b>כמ\"ש בזהר</b>: ראה שם בא לד, א."],["1862","233","<b>לי יאורי</b>: המשך הכתוב התנים הגדול."]]],[2300540524,"מעלה ממש, וע\"כ נהפך תחלה המטה העליון לתנין <span data-k=\"pg\">נח</span> ּ ומתנין למטה להורות שאין בחי' הצמצום דתנין בבחי' פירוד כלל וכלל ע\"כ המטה עצמו הוא התנין והתנין הוא המטה והכל א' ממש וכמ\"ש אני ראשון<sup data-n=\"1863\">234</sup> ואני אחרון ומבלעדי אין אלקים כו' וכתיב ראו כי אני<sup data-n=\"1864\">235</sup> אני הוא משום דקמי' כחשיכה כאורה כו' וכמ\"ש בשמים ממעל<sup data-n=\"1865\">237</sup> ועל הארץ מתחת [בשניהם] אין עוד בשוה, וכן א' אם אסק שמים<sup data-n=\"1866\">238</sup> כו' אציעה שאול הנך כו' וכמו שדיבר עם הנחש<sup data-n=\"1867\">239</sup> כו', דגם חושך<sup data-n=\"1868\">236</sup> לא יחשיך כו' וד\"ל.\n[ט] <b>וזהו</b> ויאמר אליו ה מה זה בידך ויאמר מטה ויאמר השליכהו ארצה וישליכהו ארצה ויהי לנחש וינס משה מפניו, פי' צוה לו להשליך מטהו שהוא בחי' מקור הראשון להטות ההמשכות והשפעות להטות כלפי חסד ולהיות יורד האור ובא בהתלבשות שונות כנ\"ל, וא' לו השליכהו ארצה להיות בבחי' ירידה וצמצום אחרון יותר, והוא עד ארץ העמים שמקבלים מד' נהרות שיוצאים חוץ לג\"ע הארץ אחר הפסק דלהט החרב המתהפכת לשמור<sup data-n=\"1869\">240</sup> כו', וישליכהו ארצה ויהי לנחש שהוא בחי' קליפה דמצרים שנק' תנין הגדול כו', וינס משה מפניו להיות[ו] תכלית הגסות דקליפה הקשה כו', וחזר וציוה לו שיחזיק בזנבו כו' וזה להורות דגם צמצום האחרון יותר בטל ונכנע כ\"כ עד שיוכל לעלות ולהיות בבחי' מטה משה ממש כמ\"ש ויחזק כו' ויהי למטה בכפו<sup data-n=\"1870\">241</sup> (וזהו ענין גלות השכינה בע' שרים דכתי' קולה כנחש ילך<sup data-n=\"1871\">242</sup> כו', רישא שכיבת לעפרא<sup data-n=\"1872\">243</sup> וזנבא שליט כו' שמשפיע בבחי' אחוריים לע\"ש דנוגה כו', וז\"ש ויחזק בו ויהי למטה בכפו כו') לפי<sup data-n=\"1873\">244</sup> שהשבירה לא הי' רק במדות<sup data-n=\"1874\">245</sup> שמקבלים מחיצוניות הדעת שהוא מלך הא' בלע<sup data-n=\"1875\">246</sup> כו' כבלע את הקדש<sup data-n=\"1876\">247</sup> כו', אבל בפנימי' חכ' שהוא פנימי' הדעת דמשה לא הי' שבירה כלל וכמ\"ש ימותו ולא בחכ'<sup data-n=\"1877\">248</sup> כו' וע\"כ נהפך מנחש למטה להיותו מטה משה דוקא, וראי' מנחש הנחשת שעשה משה שכל הרואה אותו חי<sup data-n=\"1878\">249</sup>",[["1863","234","<b>אני ראשון</b>: ישעי' מד, ו."],["1864","235","<b>ראו כי אני</b>: האזינו לב, לט [בדילוג]."],["1865","237","<b>בשמים ממעל</b>: ואתחנן ד, לט."],["1866","238","<b>אם אסק שמים</b>: תהלים שם, ח [ושם: ואציעה]."],["1867","239","<b>שדיבר עם הנחש</b>: בראשית ג, יד."],["1868","236","<b>כחשיכה כאורה. . דגם חושך</b>: תהלים קלט, יב."],["1869","240","<b>דלהט החרב המתהפכת לשמור</b>: בראשית שם, כד."],["1870","241","<b>ויחזק. . בכפו</b>: שמות ד, ד."],["1871","242","<b>קולה כנחש ילך</b>: ירמי' מו, כב."],["1872","243","<b>רישא שכיבת לעפרא</b>: ראה זהר במדבר קיט, ב. ע\"ח (שער מיעוט הירח) של\"ו, פ\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' יד."],["1873","244","<b>כו') לפי</b>: גז: כו') (לפי. ט: כו' לפי."],["1874","245","<b>שהשבירה. . במדות</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ח. וש\"נ."],["1875","246","<b>הדעת. . בלע</b>: וישלח לו, לב. ראה ע\"ח (שער דרושי הנקודות) ש\"ח, פ\"ד. (שער שביה\"כ) ש\"ט, פ\"א. ביאוה\"ז פינחס קטז, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקנא. תקס\"ז ע' לג. ע' נט. ע' עו. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370492\" data-slug=\"torah-or\" data-id=\"3901370492\">תו\"א (תצוה) קי, ד</a>. (מג\"א) קיח, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380089\" data-slug=\"likkutei-torah\" data-id=\"4001380089\">לקו\"ת ויקרא ג, ד</a>. במדבר י, ג. מאמרי אדה\"א דברים ח\"ב ע' תרמג. וש\"נ. שמות ח\"ב ע' תצו. וש\"נ. קונטרסים ע' שפז. לקמן פ' יתרו ער, ד. תצוה שסה, א. שעח, ג. סה\"מ עזר\"ת ע' פט."],["1876","247","<b>בלע. . כבלע את הקודש</b>: במדבר ד, כ. ראה גם מאמרי אדה\"א דברים שם. וש\"נ. קונטרסים שם. לקמן פ' יתרו ער, ד. תצוה שעח, ג. אבל בתו\"א שם (קי, ד) ע\"ד ותבלענה שבע פרות הרעות. עיי\"ש. ראה גם ילקוט ראובני וישלח קרוב לסופו (קמד, א ואילך) ד\"ה הספירה ראשונה. וראה גם ביאוה\"ז להצ\"צ אמור כרך ב ע' תתקנ. ד\"ה וספרתם תרי\"ט, יודפס בעז\"ה בפלח הרמון ויקרא."],["1877","248","<b>ימותו ולא בחכ'</b>: איוב ד, כא. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' ט' וע' רצט. לקמן פ' ויקהל תכא, ג הערה 1209."],["1878","249","<b>מנחש הנחשת. . חי</b>: חוקת כא, ט."]]],[2300540542,"להיותו למעלה מן המות שנמשך ע\"י הנחש כחטא עה\"ד טו\"ר כו'), (וכך הוא ענין האות השני במה שנעשה ידו מצורעת כשלג<sup data-n=\"1879\">250</sup> וישב ידו אל חיקו ויוציאה והנה שבה כבשרו<sup data-n=\"1880\">251</sup>, דידוע בבחי' צרעת שבנגעים שהוא שורש יניקת החיצונים להיות שם הסתלקות אור אבא שהוא החכ' דאדם וכמ\"ש בתרגום צרעת סגירו<sup data-n=\"1881\">252</sup> דנהורא עילאה<sup data-n=\"1882\">253</sup> כו' כמ\"ש במ\"א באריכות, וציוה לו להשיב ידו לחיקו ויוציאה והנה שבה כבשרו להורות שגם הטמא טהור יהי' כמ\"ש מי יתן טהור מטמא<sup data-n=\"1883\">254</sup> לא אחד דלגבי פנימי' ח\"ע ששם עצמו' אוא\"ס ממש גם הנגע יהפך לענג<sup data-n=\"1884\">255</sup> כו' וכנ\"ל וד\"ל (ולהיות<sup data-n=\"1885\">256</sup> קליפה דנגע צרעת באדם קשה יותר מקליפה דנחש ונק' נגעי בנ\"א<sup data-n=\"1886\">257</sup>, ע\"כ א' ואם לא יאמינו לך<sup data-n=\"1887\">258</sup> לקול האות הראשון והאמינו לקול האות האחרון כו'<sup data-n=\"1888\">259</sup>, ואם לא יאמינו<sup data-n=\"1889\">260</sup> בשני האותות האלה ולקחת ממימי היאור כו' שהוא אות גמור על ליקוי שרשי יניקות פרעה ומצרים מנהר נילוס שנהפך לדם ביבשת כו' ולא יתנשא לומר לי יאורי כו' וכנ\"ל שבזה הי' כללות המופתים וד\"ל.\n[י] <b>והנה</b> בפ' וארא בשליחות ששלח ה' למשה ואהרן לפרעה אמר כי ידבר אליכם פרעה<sup data-n=\"1890\">261</sup> תנו לכם מופת ואמרת אל אהרן קח את מטך והשלך לפני פרעה יהי לתנין כו' עד ויבלע מטה אהרן<sup data-n=\"1891\">262</sup> את מטותם, ויש להבין בזה למה לא עשה אהרן גם זה שיהפך התנין למטה כמו שציוה למשה ויהי למטה בכפו, אשר ודאי החרטומים לא היו יכולים לעשות כן, וא\"א לומר דלגבי ישראל הוצרך להראות להם האות שנהפך הנחש למטה <span data-k=\"pg\">118</span> ּ להיות בלי פירוד כלל גם ברוב הצמצומים כנ\"ל ולא לפרעה ומצרים, הנה<sup data-n=\"1892\">263</sup> לפרעה הי' צריך להראות ביותר שלא יהי' בבחי' פירוד מאלקות ולא יאמר לי יאורי כו'. אך באמת גם זה עשה אהרן לפני פרעה שנהפך התנין למטה שהרי א' ויבלע מטה אהרן את מטותם, דהיינו אחר שחזר ונעשה מטה כפרש\"י<sup data-n=\"1893\">264</sup>, וא\"כ גם החרטומים עשו כן שנהפך תנינים שלהם למטה כמ\"ש ויבלע מטה אהרן את מטותם כו', אלא",[["1879","250","<b>ידו מצורעת כשלג</b>: שמות ד, ו. ראה גם לעיל כ, סע\"ב ואילך."],["1880","251","<b>וישב ידו. . כבשרו</b>: שם ד, ז [בדילוג]."],["1881","252","<b>בתרגום צרעת סגירו</b>: ראה ת\"א תזריע יג, ג."],["1882","253","<b>צרעת סגירו דנהורא עילאה</b>: ראה זהר תזריע מט, ב. ביאוה\"ז תזריע עב, א. עג, ב. ע\"ח (שער לאה ורחל) של\"ח, פ\"ז. מאמרי אדה\"ז תקס\"ה ח\"א ע' תכג ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תנג וע' תעג ואילך."],["1883","254","<b>מי יתן טהור מטמא</b>: איוב יד, ד. ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' פט."],["1884","255","<b>הנגע יהפך לענג</b>: נסמן לעיל כ, ג הערה 840."],["1885","256","<b>וד\"ל (ולהיות</b>: בג: וד\"ל) ולהיות כי. דהז: וד\"ל) (ולהיות כי."],["1886","257","<b>נגעי בנ\"א</b>: שמואל-ב ז, יד. ראה גם מאמרי אדה\"א קונטרסים ע' תקלט. וש\"נ."],["1887","258","<b>ואם לא יאמינו לך </b>[דזי: ניתוסף: כו']<b>: שמות ד, ח [ושם</b>: והי' אם. בדילוג]."],["1888","259","<b>כו'</b>: כ\"ה גם בהכת\"י."],["1889","260","<b>ואם לא יאמינו</b>: שמות שם, ט [ושם: והי' אם. . לשני (וכ\"ה באו). בדילוג]."],["1890","261","<b>כי ידבר אליכם פרעה</b>: וארא ז, ט [בדילוג]."],["1891","262","<b>ויבלע מטה אהרן</b>: שם ז, יב."],["1892","263","<b>הנה</b>: גהזי: אדרבא."],["1893","264","<b>כפרש\"י</b>: עה\"פ. ובשבת צז, א ד\"ה נס. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261049\" data-slug=\"likkutei-sichot\" data-id=\"1300261049\">לקו\"ש וארא (כרך כו) ע' 49</a> ואילך."]]],[2300540559,"שלא נז' היפך התנין למטה במעשה דאהרן רק במעשה דמשה שהי' צריך לזה שיתחזק הדבר הזה ע\"י משה עצמו דוקא, כי לכאורה לא הוצרך להראות אות זה למשה עצמו שהוא הי' מאמין לדבר ה' שדיבר אליו רק לחזק לב ישראל ע\"י כו' כמ\"ש וילך משה ואהרן ויאספו כו' ויעש האותות לעיני העם ויאמן העם<sup data-n=\"1894\">265</sup> כו' (ומטה אהרן זה<sup data-n=\"1895\">266</sup> הוא מטה האלקים דמשה<sup data-n=\"1896\">267</sup> כו'). והנה גם חרטומי מצרים יכלו לעשות כן להפוך המטה לנחש להיות כי ידעו בשרש [ו]מקור יניקתם באחוריים דשם אלקי', א[י]ך שיורד ונמשך בהשתלשלו' רבות וצמצומים גדולים עד שנהפך המטה לנחש דקליפה כו', ועכ\"ז הראה להם משה עוד שאין גם בזה שנעשה תנינים שום פירוד מיחודו ית', והוא מה שבלע מטה אהרן את מטותם. כי הנה בחי' המטה שלהם ג\"כ<sup data-n=\"1897\">268</sup> כמו שהן למעלה בשרש אחיזתם במקור ושרש שרשם בקדושה העליונה דבחי' אור החסד דשם הוי' דאצי' שמאיר עד צמצום האחרון דשם אלקי' במ\"ח צירופי' האחרונים<sup data-n=\"1898\">269</sup> כו', גם שם נכללים ובטלים במציאותם ומתייחדים ממש בתוך מטה אהרן דוקא שהוא בחי' מטה האלקי' דמשה שהוא המקור הראשון הכללי לכל הטיות והמשכות דחסדים העליונים שמטה כלפי חסד כו' שעדיין הוא בבחי' יחוד האמיתי בעצמות אוא\"ס ב\"ה והוא בחי' נהר שיוצא מעדן שהוא גילוי בחי' רב חסד שבתענוג הנעלם כו' וד\"ל. והוא הנק' מטה אהרן כאשר נמשך ויורד למטה להטות כלפי חסד שזהו שרש מדריגת אהרן<sup data-n=\"1899\">270</sup>, כידוע בענין ענני כבוד שהי' בזכות אהרן<sup data-n=\"1900\">271</sup> כו' וכמ\"ש כי ענן ה' יומם<sup data-n=\"1901\">272</sup> כו' והוא מ\"ש יומם יצוה ה' חסדו<sup data-n=\"1902\">273</sup> כמ\"ש בזהר. וזהו ויבלע מטה אהרן את מטותם שבלע אותם וכללם בעצמות[ו] ממש ולא נמצאו במציאות שלהם כלל להורות שנתבטלו במציאות אל מקור הראשון שמטה כלפי חסד בקדושה, שמשם הולך ומשתלשל בבחי' מותרי החסדים גם למטות דמצרים כידוע וד\"ל.",[["1894","265","<b>וילך משה. . ויעש. . ויאמן העם</b>: שמות ד, כט. ל. לא."],["1895","266","<b>ומטה אהרן זה. . דמשה</b>: ראה ראב\"ע וארא ז, ט. זהר וארא כח, ב. שיחת ש\"פ וארא תשל\"ד. לקו\"ש וארא הנ\"ל ע' 53 בהערה 38."],["1896","267","<b>מטה האלקים דמשה</b>: ראה זהר בשלח מח, א. שם תוספות ערב, א. ז\"ח (מדהנ\"ע) ל, ג. תנחומא שמות כג."],["1897","268","<b>ג\"כ</b>: גט: גם."],["1898","269","<b>במ\"ח צירופי' האחרונים</b>: נסמן לעיל ל, ב."],["1899","270","<b>חסד. . אהרן</b>: נסמן לעיל לז, ג."],["1900","271","<b>ענני כבוד שהי' בזכות אהרן</b>: תענית ט, א. ראה סידור שער הסוכות רנז, א. רנח, ב ואילך."],["1901","272","<b>כי ענן ה' יומם</b>: פקודי מ, לח [בדילוג]. ובזהר (שבהערה הבאה] כי ענן ה' עליהם יומם. וראה בשולי הגליון בזהר שם. אבד: בענן ה' יומם."],["1902","273","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט. ראה זהר אמור קג, א. ב."]]],[2300540049,"<b>ב\"ה פ' שמות </b>\nתורה שאמר אדמו\"ר שליט\"א בק\"ק באברוסק\nשנת תקפ\"ב לפ\"ק ר\"ח טבת\n<span data-k=\"pg\">נט</span> ּ<b>ויאמר</b> משה אל ה' כו' לא איש דברים<sup data-n=\"1903\">1</sup> אנכי<sup data-n=\"1904\">2</sup> גם מתמול גם משלשום גם מאז דברך כו' כי כבד פה וכבד לשון אנכי ויאמר ה' אל משה<sup data-n=\"1905\">3</sup> מי שם פה לאדם כו' עד אנכי אהי' עם פיך<sup data-n=\"1906\">4</sup> כו', הנה יש להקדים בשרש נשמת משה שהי' מבחי' מ\"ע דח\"ע כמ\"ש כי מן המים משיתיהו<sup data-n=\"1907\">5</sup> כידוע, והוא מ\"ש ונחנו מה<sup data-n=\"1908\">6</sup> בחי' מ\"ה העליון דוקא, ולזה אמר לא איש דברים אנכי גם מתמול גם משלשום כו' (וכפרש\"י מתמול שלשום מאז דברך הרי ג' ימים, וג' פעמים גם ג' ריבויים הרי ו' ימים, והוא עמד ביום הז' כשאמר לו ה' שילך ואמר לו לא איש דברים כו' שלח נא כו' שכל הז' ימים הי' מפתה למשה עד שחרה כו' וקיבל עליו עכ\"ל<sup data-n=\"1909\">7</sup>), ואינו מובן לפ\"ז מ\"ש לא איש דברים גם מתמול כו' הרי לא הי' איש דברים גם קודם שדיבר עמדו הרבה, והנה איתא בס' התמונה<sup data-n=\"1910\">8</sup> שיש שבעה שמיטות ושמיטה הראשונה היתה של מדת החסד והי' בה ו' אלפי שנה ואלף הז' קודם שבא שמיטה שני' שהוא העולם שאנו בו שהוא שמיטה דוא\"ש ואלף הז' הכל בבחי' מדת הדין והפחד מימות אדם הראשון עד אלף הז' (וכמו בעולם שאנו בו יש ג' מדרגות [בכלל] ג\"ע התחתון וגעה\"ע ועוה\"ב, כך הי' ג' מדרגות הללו בשמיטה שקדמה שהיא למעלה הרבה משמיטה זו שלנו עד שבחי' געה\"ת דשם הוא למעלה מעוה\"ב של שמיטה זו כו', וא\"כ בשמיטה שאחר זו ירד עוד למטה כו', ובמ\"א מבואר להיפך בז' השמיטות<sup data-n=\"1911\">9</sup> שיהי' עלי'<sup data-n=\"1912\">10</sup> אחר עלי' במעלת ומדריגת דעונג העליון עד שבעוה\"ב שלנו יהי' רק געה\"ע בשמיטה שאחריה). ולזאת אנו מוצאים שיש בזה העולם שאנו בו שינוים ותמורות הרבה בבחי' עליות וירידות שונות ולא עמד אפי' זמן א' בבחי' החסד והטוב מימי אדה\"ר עד אלף הז',",[["1903","1","<b>ויאמר משה. . לא איש דברים</b>: מאמר זה מיוסד על ד\"ה זה מש\"פ שמות בסעודת שחרית תקס\"ה. הנחת כ\"ק אדה\"א ממאמר זה דתקס\"ה נמצאת בבוך 2076 סד, ב בכותרת בעז\"ה יום שבת פ' שמות, ולא נדפסה לע\"ע. הנחת הר\"מ בן כ\"ק אדה\"ז נדפסה במאמרי אדה\"ז תקס\"ה ח\"א ע' קעח. ובשינויים ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370232\" data-slug=\"torah-or\" data-id=\"3901370232\">תו\"א פ' שמות נא, ד</a> [ושם: ההתחלה הוא: ויאמר ה' אליו מי שם פה לאדם] והגהות הצ\"צ נדפסו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830030\" data-slug=\"or-hatorah-hb\" data-id=\"8158830030\">אוה\"ת שמות ע' עו</a>. וכן נמצא תוכן המאמר בקיצור בד\"ה שלח נא ביד תשלח שנדפס במאמרי אדה\"ז הקצרים ע' ל. ראה עוד ע\"ד המאמר וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["1904","2","<b>ויאמר משה. . אנכי</b>: שמות ד, י."],["1905","3","<b>ויאמר ה' אל משה</b>: שמות שם, יא [ושם: ויאמר ה' אליו]."],["1906","4","<b>אנכי אהי' עם פיך</b>: שם ד, יב [ושם: ואנכי]."],["1907","5","<b>כי מן המים משיתיהו</b>: שמות ב, י. ראה לקמן בפנים. פ' וארא עט, ד. בשלח קסב, ב. קצד, ד. ריא, א. יתרו רסג, א. רסה, א. משפטים רצא, ד. תצוה שמב, ג. שמז, א. שסט, ד. ויקהל תיז, ד. תל, ב. פקודי תס, ד. לעיל א, ג. י, ב. יא, ג. לה, ד. מאמרי אדה\"א שמות ח\"ב ע' שצד ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670119\" data-slug=\"torat-chaim\" data-id=\"2300670119\">תו\"ח בראשית ב, ג</a> ובהנסמן לשם."],["1908","6","<b>ונחנו מה</b>: בשלח טז, ז. ח. ראה לקמן מד, ב. פ' וארא עח, ב. פ, ג. פה, א. בא קיא, א. בשלח קסב, ג. רכה, א. יתרו רסג, ד. משפטים רצב, ב. תצוה שכג, ג. שנא, ב. שנז, א. שנט, ב. ויקהל תד, ד. פקודי תמד, ד. תמה, ג. תנא, ד. תנח, א. לעיל ז, ד. מאמרי אדה\"א בראשית ע' כב. וש\"נ. שמות ח\"ב ע' שלד. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670200\" data-slug=\"torat-chaim\" data-id=\"2300670200\">תו\"ח שם כא, ג</a> הערה 24."],["1909","7","<b>(וכפרש\"י. . עכ\"ל)</b>: בשינוי לשון."],["1910","8","<b>בס' התמונה</b>: ראה תו\"א כאן שמציין: בהקדמה לתמונה ג' דכ\"ז כ\"ט ל\"א. הערה בספר המאמרים תרפ\"ד ס\"ע רמח [נדפסה גם בסה\"מ קונטרסים ח\"ג ע' קלא]. ראה גם עטרת ראש ע' 134."],["1911","9","<b>בז' השמיטות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680063\" data-slug=\"torat-chaim\" data-id=\"2300680063\">תו\"ח וישלח קפח, ג</a> ובהנסמן לשם בהערה 31. בהערה הבאה."],["1912","10","<b>בז' השמיטות שיהי' עלי'</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' רכד וע' רכח. שע\"ת יד, א. כט, ג. מאמרי אדה\"א במדבר ח\"ד ע' א'דש ואילך. לקמן פ' ויקהל תלא, א."]]],[2300540087,"שהרי מיד שחטא אדה\"ר בעה\"ד גורש מג\"ע ונתקללה האדמה בעבורו כמ\"ש קוץ ודרדר<sup data-n=\"1913\">11</sup> כו' ואח\"ז בימי אנוש הוחל לקרוא בשם ה'<sup data-n=\"1914\">12</sup> כו' עד חנוך שהי' עליות העולמות על ידו כמ\"ש ויתהלך חנוך את האלקים<sup data-n=\"1915\">13</sup> כו' (כמשי\"ת בסמוך), וכן הי' ירידה עוד בדור המבול שרבה רעת האדם<sup data-n=\"1916\">14</sup> והי' עלי' ע\"י נח ובניו כו' וחזר להיות ירידה ע\"י דור הפלגה כו' עד אברהם שהי' עליות כל העולמות ע\"י וחזר וירד בימי ישמעאל ועשו עד יעקב ובניו ירדו ג\"כ מצרים וגלה שכינה עמו<sup data-n=\"1917\">15</sup> עד מ\"ת שהי' עלי' גדולה ע\"י משה וחזרו לירד בחטא העגל ובחטא מרגלים עד לוחות האחרונות<sup data-n=\"1918\">16</sup> שהי' עלי' קצת כו', וכן בימי יהושע והשופטים הי' עליות וירידות עד דוד ושלמה. ואח\"כ הי' חורבן בהמ\"ק ראשון וחורבן ב\"ש כו' עד גלות האחרון הזה שהן שיעבוד ד' מלכיות<sup data-n=\"1919\">17</sup> בכללות כידוע. וכל זה לפי ששמיטה זאת שאנחנו בה היא מבחי' הדין והפחד בחי' הגבורות, הגם שכלול גם מחסדי' אבל חוזר מיד להיות בבחי' הדין לפי שכח הדין גובר ביותר ונמשך בחי' פסולת הגבו' הנק' גבורות קשות ביותר, ע\"כ רוב שמיטה זו הכל בבחי' ירידות וצמצומים (כמו שא' כי כלינו באפך שתה עוונותינו לנגדיך כו' כי כל ימינו<sup data-n=\"1920\">18</sup> פנו בעברתך כו' וכמ\"ש במ\"א). והכל כדי לתקן ולברר עה\"ד טו\"ר שאין מיתוק הדין אלא בשרשו<sup data-n=\"1921\">19</sup> בבחי' הגבו' כמו יסורים ממרקים<sup data-n=\"1922\">20</sup> כו', והוא ענין כל הצרות רבות ורעות בכל משך שמיטה זו כו', <span data-k=\"pg\">120</span> ּ אבל שמיטה הראשונה הי' הכל בבחי' החסד וטוב העליון ולא הי' שם בחי' דינין וצמצומים וירידות כלל וכלל, וע\"כ מעלתה גבוה מאד נעלה משמיטה זו גם מהיותר עליון בכללות ומכל פרטי ההשתלשלו' דאבי\"ע דשמיטה זאת גם מן המקיפי' ופנימי' כו', דגם מקיפי' דע\"ס דאבי\"ע יש בהן עליות וירידות כמו מחול לשבת וג' מועדים כו' וג' תפלות בכל יום כו', וגם משתנה מעת לעת כמו והימים ימי בכורי<sup data-n=\"1923\">21</sup> כו' מבחי' גבורות דאימא דאית יומין לטב ואית יומין לביש<sup data-n=\"1924\">22</sup> כמ\"ש למה אירא בימי רע כו' וכן אשרי",[["1913","11","<b>קוץ ודרדר</b>: בראשית ג, יח [ושם: וקוץ]."],["1914","12","<b>בימי אנוש הוחל לקרוא בשם ה'</b>: שם ד, כו."],["1915","13","<b>ויתהלך חנוך את האלקים</b>: בראשית ה, כד."],["1916","14","<b>בדור המבול שרבה רעת האדם</b>: שם ו, ה."],["1917","15","<b>יעקב. . מצרים וגלה שכינה עמו</b>: ראה שמו\"ר פט\"ו, טז. מגילה כט, א."],["1918","16","<b>ובחטא מרגלים עד לוחות האחרונות</b>: כנראה הכוונה ”לירד בחטא העגל\" ”עד לוחות האחרונות שהי' עלי' קצת\" וחזרו לירד ”בחטא המרגלים\" אלא שקיצר וחושב שתי הירידות (חטא העגל והמרגלים) ביחד (ואח\"כ העלי')."],["1919","17","<b>ד' מלכיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161091\" data-slug=\"likkutei-sichot\" data-id=\"1300161091\">לקו\"ש וארא (כרך טז) ע' 91</a>."],["1920","18","<b>כי כלינו. . שתה. . כי כל ימינו</b>: תהלים צ, ז-ט. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680162\" data-slug=\"torat-chaim\" data-id=\"2300680162\">תו\"ח מקץ ריז, ב</a>."],["1921","19","<b>שאין מיתוק הדין אלא בשרשו</b>: ראה פע\"ח (שער השופר) שכ\"ו, פ\"א. תניא עם מ\"מ, הגהות והע\"ק לפל\"א. מאמרי אדה\"א דברים ח\"ב ע' תרטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670562\" data-slug=\"torat-chaim\" data-id=\"2300670562\">תו\"ח וירא קח, ב</a> ובהנסמן בהערה 11."],["1922","20","<b>יסורים ממרקים</b>: ברכות ה, א."],["1923","21","<b>והימים ימי בכורי</b>: שלח יג, כ. ראה זהר שלח קנח, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680335\" data-slug=\"torat-chaim\" data-id=\"2300680335\">תו\"ח מקץ רכ, ד</a>. ובהנסמן שם בהערה 58."],["1924","22","<b>דאית יומין לטב. . לביש</b>: ראה זהר מקץ רד, א. ביאוה\"ז לשם לג, ג."]]],[2300540125,"משכיל אל דל<sup data-n=\"1925\">24</sup> ביום רעה ימלטהו ביומין דדינין שלטין כו' דאפי' עוונות שאדם דש בעקביו<sup data-n=\"1926\">23</sup> נתבעים ממנו כו', וכן בר\"ה שהעולם נידון במדת הדין כו' (ואע\"פ שבשמיטה של חסד הי' ג\"כ ר\"ה וג' מועדים אך הכל בבחי' החסד).\n<b>והנה</b> המקובלים האחרוני' למדו מדברי ס' התמונה הנ\"ל שיהי' עוד ה' שמיטות<sup data-n=\"1927\">25</sup> אחר שמיטה שלנו נגד ז' מדות, ולא משמע כן כלל בכהאריז\"ל<sup data-n=\"1928\">26</sup>, דודאי לא יהי' שום שמיטה אחרי שמיטה זו כי העוה\"ב הבא באלף הז' הוא נצחי וכמ\"ש וע\"י יתיב מלכותי' מלכות עלם דלא תשתנה<sup data-n=\"1929\">27</sup>, וכמובן בכמה כתובים שנק' חיי עולם<sup data-n=\"1930\">28</sup> ונק' מנוחה לחיי העולמים<sup data-n=\"1931\">29</sup> שאין עוד עליות וירידות<sup data-n=\"1932\">30</sup> כלל כמ\"ש במ\"א וכמו ביום הג' יקימנו<sup data-n=\"1933\">31</sup> ונחי' לפניו כו' וד\"ל. אך בזה מודה גם האריז\"ל גם הוא שקדם לשמיטה זו שמיטה אחת שהוא מבחי' החסד כמ\"ש בס' התמונה, אך שהוא מלביש הענין באופן אחר שלא כמ\"ש בס' התמונה שקוראה בשם שמיטה הא' כו' שא\"כ הי' צריך שיהי' עוד ה' שמיטות כנ\"ל, אלא הוא בחי' עולם התהו שקדם לעולם התיקון, והיינו בחי' ז' מדות<sup data-n=\"1934\">32</sup> דאורות דתהו שנק' שנים קדמוניות<sup data-n=\"1935\">33</sup> או ימי קדם<sup data-n=\"1936\">34</sup> כידוע, וכמ\"ש ואלה המלכים אשר מלכו בארץ אדום שהוא שם ב\"ן<sup data-n=\"1937\">36</sup> דעולם התהו והן ז' מלכים דז\"מ בבחי' הכתרים כו' לפני מלוך מלך לבנ\"י, ולא נתקיימו כמ\"ש וימלוך וימת<sup data-n=\"1938\">35</sup> כו', עד שנעשה עולם התיקון כמו אדה\"ר למטה בצלם אדם העליון [שהוא] שם מ\"ה<sup data-n=\"1939\">37</sup> דהוי'<sup data-n=\"1940\">38</sup> שזהו עיקר בחי' התיקון שהוא התכללות אורות וכלים בפרצוף אדם (כמשי\"ת בסמוך והכל עולה לענין אחד). רק שיש בזה שינוי הלשון מהיפך להיפך שלפ\"ד ס' התמונה שמיטה [ה]א' הי' של חסדים לגמרי כנ\"ל, ולפ\"ד האריז\"ל",[["1925","24","<b>אשרי משכיל אל דל</b>: תהלים מא, ב. ראה זהר (היכלות) פקודי רנ, ב."],["1926","23","<b>למה אירא בימי רע. . עוונות שאדם דש בעקביו</b>: תהלים מט, ו. ע\"ז יח, א. ראה גם ביאוה\"ז שם. דרך חיים שעה\"ת ח, א. מאמרי אדה\"א במדבר ח\"ב ע' תקג."],["1927","25","<b>המקובלים האחרוני'. . שיהי' עוד ה' שמיטות</b>: בתו\"א כאן מציין הצ\"צ בחצאי עיגול: וכמ\"ש שם בסה\"ת."],["1928","26","<b>ולא משמע. . בכהאריז\"ל</b>: ראה לקו\"ת להאריז\"ל ר\"פ קדושים. בהנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680162\" data-slug=\"torat-chaim\" data-id=\"2300680162\">תו\"ח מקץ ריז, ב</a> הערה 20."],["1929","27","<b>וע\"י יתיב מלכותי' מלכות עלם דלא תשתנה</b>: דניאל ז, ט. ג, לג. ז, כז. ראה גם פירוש המלות עח, ג. מאמרי אדה\"א דברים ח\"א ע' רו. הנחות תקע\"ז ע' קיז."],["1930","28","<b>בכמה כתובים שנק' חיי עולם</b>: ראה דניאל יב, ב."],["1931","29","<b>מנוחה לחיי העולמים</b>: סוף תמיד."],["1932","30","<b>שאין עוד עליות וירידות</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשיח. במדבר ח\"א ע' סא. נ\"ך ע' תסט. תקע\"ז ע' פז וס\"ע שנ ואילך. לקמן פ' בשלח רכא, ב ואילך. משפטים רפו, ב."],["1933","31","<b>ביום הג' יקימנו</b>: הושע ו, ב. ראה מאמרי אדה\"א נ\"ך ע' שצג וע' שצח."],["1934","32","<b>ז' מדות</b>: ז: ז\"מ ז' מלכים."],["1935","33","<b>שנים קדמוניות</b>: מלאכי ג, ד."],["1936","34","<b>ימי קדם</b>: מיכה ז, כ."],["1937","36","<b>בארץ אדום שהוא שם ב\"ן</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670154\" data-slug=\"torat-chaim\" data-id=\"2300670154\">תו\"ח בראשית לב, א</a> ובהנסמן בהערה 11 שם."],["1938","35","<b>ואלה המלכים. . לפני מלוך. . וימלוך וימת</b>: וישלח לו, לא-ג. ראה זהר (אדרא רבא) נשא קכח, א. ע\"ח שער הכללים פ\"א. שם (שער דרושי הנקודות) ש\"ח, פ\"ד."],["1939","37","<b>אדם. . שם מ\"ה</b>: נסמן לעיל ד, ב."],["1940","38","<b>שם מ\"ה דהוי'</b>: ראה ע\"ח (שער לאה ורחל) של\"ח, פ\"א. פ\"ב. וראה ג\"כ זהר בראשית לד, ב."]]],[2300540163,"שהוא בחי' התהו כולו בחי' הדין וצמצום דגבורו' עליונים דשם ב\"ן נק' ארץ אדום וכמ\"ש וימלוך וימת זה תחת זה כו'. ושמיטה זו שלנו לפ\"ד ס' התמונה הוא בחי' הדין ולפ\"ד האריז\"ל זהו בבחי' התיקון דשם מ\"ה<sup data-n=\"1941\">*39</sup> שכלול מחו\"ג יחד (וראי' לזה שהי' הכל בבחי' עליות וירידות זא\"ז כנ\"ל, וגם במבול א' ויאמר ה' לא אוסיף לקלל<sup data-n=\"1942\">39</sup> עוד כל ימי הארץ<sup data-n=\"1943\">40</sup> כו', וכן בכל ירידה הי' עלי' אח\"כ מיד כמו שאנו מוצאים בכל הסיפורים מאדם הראשון עד גם בדור הזה יש הרבה ניסים וישועות כו').\n<b>והנה</b> שתי<sup data-n=\"1944\">41</sup> נשמות גבוהות מאד שהן בחי' שמיטה הראשונה בבחי' חסדים (לפ\"ד ס' התמונה, ולפ\"ד האריז\"ל הוא מבחי' התהו) (ולא יתכן לפ\"ד האריז\"ל לומר בנשמת משה שהי' מבחי' התהו שהרי הי' בחי' שם מ\"ה דתיקון כמ\"ש מה שמו<sup data-n=\"1945\">42</sup> כו' ובבחי' התהו הוא בבחי' ב\"ן או ס\"ג<sup data-n=\"1946\">*43</sup> כידוע, ואפשר מ\"ש <span data-k=\"pg\">ס</span> ּ מה שמו כו' הוא בבחי' מ\"ה החדש שהוא מלך הח' הדר<sup data-n=\"1947\">43</sup> כו' שלמעלה מבחי' התהו כו', והוא מבחי' משיח כמ\"ש במ\"א<sup data-n=\"1948\">45</sup> ביום השמיני שלח<sup data-n=\"1949\">44</sup> כו' ומשה ומשיח הכל א' דגואל ראשון הוא גואל אחרון<sup data-n=\"1950\">46</sup> כמ\"ש ז\"ל יבא טוב<sup data-n=\"1951\">47</sup> זה משה שנק' טוב בטי\"ת רבתי<sup data-n=\"1952\">48</sup> שהוא בחי' עה\"ח שלמעלה מעה\"ד כו', והוא שרש נשמת חנוך רק שחנוך עלה למעלה כי לקח אותו אלקים<sup data-n=\"1953\">50</sup> ובמשיח<sup data-n=\"1954\">49</sup> יבא זה האור למטה וע\"כ נא' בו ישכיל עבדי<sup data-n=\"1955\">51</sup> שהוא עבדו זקן ביתו<sup data-n=\"1956\">52</sup> כו' בחי' חנוך נער מט\"ט<sup data-n=\"1957\">53</sup> כמ\"ש חנוך לנער<sup data-n=\"1958\">54</sup> כו' וכן משה עבדי בכל ביתי נאמן הוא<sup data-n=\"1959\">55</sup> רק שירד למטה לתקן ע\"י תומ\"צ כמשי\"ת), וירדו למטה בשמיטה שלנו כדי לתקן לעולם שלנו, והן נשמת חנוך [ו]נשמת משה שנא' בו כי מן המים משיתיהו בבחי' מ\"ע דשמיטה הראשונה.",[["1941","*39","<b>התיקון דשם מ\"ה</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"א ואילך."],["1942","39","<b>ויאמר ה' לא אוסיף לקלל</b>: נח ח, כא (בדילוג)."],["1943","40","<b>עוד כל ימי הארץ</b>: נח שם, כב."],["1944","41","<b>שתי</b>: תוקן ע\"פ טו. ובתו\"ח: שרש."],["1945","42","<b>משה. . מה שמו</b>: משלי ל, ד. ראה זהר בראשית בהשמטות רנג, א. לעיל א, ג. יב, א. לו, א. לקמן מז, א. פ' וארא עט, ד. בשלח קסא, ג. יתרו רסג, ב. משפטים רצב, ב. תרומה שטו, ד. תצוה שמו, ד. שנד, ד. ויקהל שצח, ג. תיא ג. מאמרי אדה\"א ויקרא ח\"א ס\"ע טז. וש\"נ. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670586\" data-slug=\"torat-chaim\" data-id=\"2300670586\">תו\"ח נח עו, א</a> הערה 11."],["1946","*43","<b>התהו. . ס\"ג</b>: ראה גם לעיל לט, ד. וש\"נ."],["1947","43","<b>מ\"ה החדש שהוא מלך הח' הדר</b>: וישלח לו, לט. ראה ע\"ח (שער שבירת הכלים) ש\"ט, פ\"ח. (שער התיקון) ש\"י, פ\"ב. פ\"ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670088\" data-slug=\"torat-chaim\" data-id=\"2300670088\">תו\"ח בראשית ח, א</a> ובהנסמן לשם בהערה 16."],["1948","45","<b>במ\"א</b>: אב: ניתוסף: וכמ\"ש. ח: ניתוסף בין השיטין (בכת\"י אחר ): ע\"פ."],["1949","44","<b>כמ\"ש במ\"א ביום השמיני שלח</b>: מל\"א ח, סו. ראה ד\"ה זה [אבל הוא משנת תקפ\"ז] במאמרי אדה\"א דברים ח\"ד ע' א'שפו וע' א'תפב. וראה אוה\"ת דרושים לשמ\"ע ע' א'תשעח שמציין: כ\"כ בתורה בשמ\"ע תקס\"ה [נדפס במאמרי אדה\"ז תקס\"ד ס\"ע רלג ואילך — ראה הערה במאמרי אדה\"א דברים שם ע' א'שנה]."],["1950","46","<b>דגואל ראשון הוא גואל אחרון</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' רמט (נוסחא שני'). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111008\" data-slug=\"likkutei-sichot\" data-id=\"1300111008\">לקו\"ש שמות (כרך יא) ע' 8</a>. וש\"נ."],["1951","47","<b>כמ\"ש ז\"ל יבא טוב</b>: מנחות נג, ב. ראה מאמרי אדה\"ז אתהלך לאזניא ע' לו. ביאוה\"ז בהקדמה. שה\"א פט, א. צה, ב. מאמרי אדה\"א ויקרא ח\"א ע' שנט. וש\"נ. בראשית ע' שס. במדבר ח\"ב ע' תשעז. ח\"ג ע' תתקמג. דברים ח\"ד ע' א'תכא. דרושי חתונה ח\"ב ע' תרכה. לקמן פ' בשלח קנה, ג."],["1952","48","<b>משה שנק' טוב בטי\"ת רבתי</b>: שמות ב, ב ובמנחת שי שם. ראה בסמוך בפנים. לעיל א, ג. יא, ג. כז, א. לו, א. לקמן פ' בשלח קנז, א. קעו, ד. ריא, א. רסג, א. משפטים שג, ב. תצוה שמב, ג. שנה, ד. ויקהל שצח, ד. תיז, ד. מאמרי אדה\"א קונטרסים ע' שצג. וש\"נ. בראשית ע' קלט. וש\"נ."],["1953","50","<b>כי לקח אותו אלקים</b>: בראשית ה, כד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301670073\" data-slug=\"likkutei-sichot\" data-id=\"1301670073\">לקו\"ש בראשית (כרך לה) ע' 11</a> הערה *55."],["1954","49","<b>חנוך. . ובמשיח</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680162\" data-slug=\"torat-chaim\" data-id=\"2300680162\">תו\"ח מקץ ריז, ב</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' סג. מאמרי אדה\"א דרושי חתונה ח\"א ע' קל ואילך."],["1955","51","<b>ובמשיח. . נא' בו ישכיל עבדי</b>: ישעי' נב, יג. ראה מאמרי אדה\"א ויקרא ח\"א ע' קיב. וש\"נ."],["1956","52","<b>עבדו זקן ביתו</b>: לשון הפסוק חיי שרה כד, ב."],["1957","53","<b>חנוך נער מט\"ט</b>: ראה יבמות טז, ב ובתוס' שם."],["1958","54","<b>כמ\"ש חנוך לנער</b>: משלי כב, ו. זהר חדש רות פה, ג."],["1959","55","<b>משה עבדי בכל ביתי נאמן הוא </b>[זט: ליתא תיבת הוא]: בהעלותך יב, ז [ושם: עבדי משה — ראה שע\"ת פ, ד]."]]],[2300540200,"<b>והענין</b> הוא לפי שעד חנוך הי' התגברות כח יניקת החיצוני' ביותר כמו בדורו של אנוש שהוחל לקרוא בשם ה' והי' רובם טועים אחר אמונות זרות לעבוד לכו\"מ<sup data-n=\"1960\">56</sup> כו', מצד ריבוי המשכות דגבורות קשות שהוא פסולת הגבו' העליונה שנפלו למטה בשמיטה זו שהוא מבחי' הדין (ולפ\"ד ס' התמונה וגם לפ\"ד האריז\"ל רבו כחות הדינין על החסדים כמו שמצינו ברוב ד\"ה<sup data-n=\"1961\">57</sup> ובפרט אחר חורבן ב\"ש כו'), כמו שא' הנפילים היו בארץ אשר יבואו בני האלקים כו' המה הגבורים אשר מעולם אנשי השם<sup data-n=\"1962\">58</sup> דבחי' גבורות העליונים ע\"כ נק' בני האלקים כו' עד שרבו רעות האדם והי' המבול כו', וע\"כ ירד נשמת חנוך בשמיטה שקדמה שגבוה מאד נעלה מעולם שלנו כדי לתקן ולהעלות כל הניצוצות דקדושה שנפלו בדור אנוש והבאים אחריו, ועכ\"ז דורו של נח נאבדו במבול. ואמנם גם זה שהי' הצלה לעולם ע\"י נח ובניו שמאלה נפצה<sup data-n=\"1963\">59</sup> כו', ג\"כ הי' ע\"י חנוך ובנו<sup data-n=\"1964\">60</sup> משותלח כו', שאם לא עבודת חנוך בזה העולם הי' העולם השפל הזה הי'<sup data-n=\"1965\">61</sup> חשוך מאד בהתגברו' כחות החיצוני' עד שלא הי' אפשר להציל גם לנח ובניו כו' וד\"ל. ואחר חנוך ונח הי' אברהם שהי' מתקן ומעלה לכל הניצוצות דקדושה שנפלו עד דורו, ונק' אב המון גוים<sup data-n=\"1966\">62</sup> וכמ\"ש והנפש אשר עשו<sup data-n=\"1967\">63</sup> כו' וכמאמר אחד הי' אברהם<sup data-n=\"1968\">64</sup> כו', ועדיין לא הי' תיקון גמור לזה העולם מרוב התגברות כחות הטומאה כמו במצרים וארץ כנען כו', עד שבא משה שירד ממ\"ע דשמיטה הא' למטה כדי לתקן תיקון גמור דשם מ\"ה דהוי' שנגלה לעולם ע\"י שהוציא לבנ\"י מנש\"ט דמצרים וקרבם להר סיני לקבלת תו\"מ פב\"פ בגילוי עצמות א\"ס ב\"ה ממש, עד שכמעט נתקן כל העולם מזוהמא<sup data-n=\"1969\">65</sup> של נחש הקדמוני ומכל רע שנמשך בעולם כעין דלע\"ל ממש כידוע, ולא הי' עילוי גדול כזה ע\"י כל נשמה גבוה שבשמיטה זו רק ע\"י נשמת משה דוקא שהי' משמיטה הא' דוקא כו' להיותו גבוה הרבה במדריגה משמיטה זו כנ\"ל וד\"ל.\n<b>וזהו</b> הטעם שנק' משה כי מן המים משיתיהו (פי' מבחי' מ\"ע שנק'<sup data-n=\"1970\">66</sup> ים הקדמוני<sup data-n=\"1971\">67</sup> כו') שהוא שמיטה הא' שקדמה שהיתה של בחי' חסד עליון, וממ\"ע הללו ירד למטה בעולם שלנו שלא לצורך תיקון עצמו שהרי כבר הי' מתוקן וטוב כמ\"ש ותרא אותו כי טוב<sup data-n=\"1972\">68</sup> הוא בטי\"ת רבתי כו' ברב טוב העליון דעה\"ח ממש כו', רק מפני שכבר הוא מתוקן יש ביכולתו לירד",[["1960","56","<b>בדורו של אנוש. . רובם טועים. . לעבוד לכו\"מ</b>: ראה שבת קיח, ב. רמב\"ם ריש הל' ע\"ז. וראה גם לעיל פ' שמות ל, ג."],["1961","57","<b>ד\"ה</b>: דברי הימים."],["1962","58","<b>הנפילים. . בני האלקים. . אנשי השם</b>: בראשית ו, ד [בדילוג]."],["1963","59","<b>שמאלה נפצה</b>: נח ט, יט."],["1964","60","<b>ג\"כ. . ובנו</b>: תוקן ע\"פ זט. ובתו\"ח: ע\"כ. . ובניו."],["1965","61","<b>הי'</b>: ז: ליתא."],["1966","62","<b>אב המון גוים</b>: לך יז, ה."],["1967","63","<b>והנפש אשר עשו</b>: לך יב, ה [ושם: ואת — ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'קיט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670266\" data-slug=\"torat-chaim\" data-id=\"2300670266\">תו\"ח לך פג, ד</a> הערה 65]."],["1968","64","<b>אחד הי' אברהם</b>: יחזקאל לג, כד."],["1969","65","<b>שכמעט נתקן כל העולם מזוהמא</b>: ראה שבת קמו, רע\"א."],["1970","66","<b>(פי'. . שנק'</b>: זט: פי'. . (שנק'."],["1971","67","<b>מ\"ע שנק' ים הקדמוני</b>: יחזקאל מז, יח. יואל ב, כ. זכרי' יד, ח. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שצד. דברים ח\"ד ע' א'שמא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670039\" data-slug=\"torat-chaim\" data-id=\"2300670039\">תו\"ח בראשית א, ב</a>. לקמן פ' בשלח קעח, ד. יתרו רסג, א. תצוה שמב, ג. שמז, א. ויקהל תל, ב."],["1972","68","<b>ותרא אותו כי טוב</b>: שמות ב, ב."]]],[2300540233,"למטה ולתקן ולהעלות <span data-k=\"pg\">122</span> ּ לכנ\"י לדורות הבאים ולכל העולם שיבורר עה\"ד טו\"ר ע\"י תומ\"צ שניתן ע\"י לישראל כו' (כענין קשוט עצמך<sup data-n=\"1973\">69</sup> ואח\"כ יכול לקשט אחרים כו'), אבל כל נשמה זולתו הגם שהיא היותר עליון בשמיטה זו לא הי' בכחה כלל לתקן לעולם שלנו וד\"ל. וזהו מן המים משיתיהו, לשון משיתיהו הוא בע\"כ ושלא לרצונו כמו שמושכים לאדם בע\"כ שירד ויבא למטה כך אמר משיתיהו לנשמת משה מבחי' מ\"ע בע\"כ כו', וראי' לזה שגם בהיותו בזה העולם לא רצה לילך בשליחות לתקן לבנ\"י וא' שלח נא ביד תשלח<sup data-n=\"1974\">70</sup> וד\"ל.\n<b>ובזה</b><sup data-n=\"1975\">71</sup> יובן מ\"ש במשה והאיש משה עניו מאד<sup data-n=\"1976\">72</sup> מכל האדם כו' מפני שהי' מבחי' מ\"ע דחסד שבשמיטה הא' ששם הוא בחי' הביטול והתכללות במאציל בתכלית עד שאינו נראה במציאות כלל וכלל וע\"כ הי' גם בזה העולם עניו מכל האדם כו' אע\"פ שהי' גבוה מהכל, ועוד מפני שראה לפניו נשמות עליוני' צדיקים מופלגים וגדולים הרבה ממנו בשמיטה הא' לא הי' נחשב בעצמו לכלום גם בעולם שלנו, וז\"ש ונחנו מ\"ה מ\"ה האמיתי דבחי' מ\"ה העצמי דבשמיטה הא'<sup data-n=\"1977\">73</sup> (שהוא מ\"ע שמעל השמים שאין ערך כלל לביטול דשמים אל בחי' ביטול דמ\"ע שכלולי' בחכ' העצמי' דא\"ס ממש כו'<sup data-n=\"1978\">74</sup> (אך מה שהי' עניו מכל האדם כו' אפי' מאברהם שאמר ואנכי עפר ואפר<sup data-n=\"1979\">75</sup> לפי שבחי' חסד דאברהם הי' רק מבחי' אחרונה דמ\"ע הנ\"ל, וע\"כ הי' יכול להשקות גם לצאן יתרו כמ\"ש וגם דלה דלה לנו<sup data-n=\"1980\">76</sup> כו' וד\"ל). וזהו הטעם שמיאן בשליחות ה' להעלות לישראל ממצרים ואמר מי אנכי<sup data-n=\"1981\">77</sup> כו', וא' גם בפעם הג' לא איש דברים אנכי גם מתמול כו' (וכפרש\"י שהן ו' ימים שהן וי\"ו ימי קדם דשמיטה הא' ובז'<sup data-n=\"1982\">78</sup> שא' שלח נא כו' שכוונתו הי' על משיח<sup data-n=\"1983\">79</sup> חרה בו מפני שצריך להיות תחלה תיקון לעה\"ד טו\"ר ע\"י תומ\"צ ואח\"כ יבא משיח, דמשיח אתא לאתבא צ\"ג שהן כנס\"י בתו\"מ בתשובה כו' כנ\"ל<sup data-n=\"1984\">80</sup> וזה א\"א כ\"א ע\"י משה דוקא וד\"ל). ובכ\"ז יובן מ\"ש לא איש דברים אנכי גם מתמול כו' (כמ\"ש כי אלף שנה דהיינו בעולם שלנו, כיום אתמול כי יעבור<sup data-n=\"1985\">81</sup> בשמיטה הא' וזהו גם מתמול כו') גם מאז דברך אל עבדך שהוא כשהי' נשמתו בשמיטה הא' כמו נכון כסאך מאז<sup data-n=\"1986\">82</sup> כו' (וכן מ\"ש משה מעון אתה היית לנו כו' בטרם הרים יולדו<sup data-n=\"1987\">83</sup> ותחולל ארץ שהיא שמיטה שלנו) כי כבד פה וכבד לשון אנכי, והשיבו מי שם פה לאדם כו'.",[["1973","69","<b>קשוט עצמך</b>: ב\"מ קז, סע\"ב. ראה ביאוה\"ז תרומה נא, ג. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670135\" data-slug=\"torat-chaim\" data-id=\"2300670135\">תו\"ח בראשית ב, ד</a>. מאמרי אדה\"א במדבר ח\"ב ע' תשפה. לקמן פ' ויקהל תיח, א."],["1974","70","<b>שלח נא ביד תשלח</b>: שמות ד, יג."],["1975","71","<b>ובזה</b>: ד: נרשם כאן פ\"ב."],["1976","72","<b>והאיש משה עניו מאד</b>: בהעלותך יב, ג."],["1977","73","<b>הא'</b>: תוקן ע\"פ זט. ובנדפס: הב'."],["1978","74","<b>כו'</b>: אוצ\"ל: כו')."],["1979","75","<b>עניו. . אפי' מאברהם שאמר ואנכי עפר ואפר</b>: וירא יח, כז. ראה ספרי בהעלותך שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>."],["1980","76","<b>וגם דלה דלה לנו</b>: שמות ב, יט."],["1981","77","<b>מי אנכי</b>: שמות ג, יא."],["1982","78","<b>ובז'</b>: תוקן ע\"פ זט. ובנדפס: ובזה."],["1983","79","<b>שלח. . שכוונתו הי' על משיח</b>: לקח טוב עה\"פ. ראה לקמן מז, ב. פ' בשלח קנו, ד. משפטים רפב, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111008\" data-slug=\"likkutei-sichot\" data-id=\"1300111008\">לקו\"ש שמות (כרך יא) ע' 8</a>."],["1984","80","<b>דמשיח אתא לאתבא. . כנ\"ל</b>: ראה המאמר שלפנ\"ז מא, ב. וש\"נ."],["1985","81","<b>כי אלף שנה. . יעבור</b>: תהלים צ, ד [בדילוג. ושם: שנים. וכ\"ה בהו — ראה מאמרי אדה\"א בראשית ע' נג. שמות ח\"א ע' ריח. דברים ח\"ג ע' תתה]."],["1986","82","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["1987","83","<b>מעון. . בטרם הרים יולדו</b>: תהלים צ, א. ב."]]],[2300540265,"[ב] <b>והנה</b> תחלה יש להבין ביאור ענין בחי' התהו ובחי' התיקון, דהנה ידוע שעיקר ההפרש בין התהו והתיקון<sup data-n=\"1988\">84</sup> שבבחי' התהו הוא בבחי' התכללות כל המדריגות כא' בלי שום התחלקות כלל, כמשל הכחות נפש האדם מצד עצמה שהיא רוחני' שכל הכחות כלולים יחד רצון ושכל ומדות ומו\"ד כא' בלי התחלקות כאו\"א בפ\"ע כלל, לפי שכל רוחני' בלתי מתחלק לחלקים מיוחדים, אע\"פ שהנפש מלובשת בגוף ויש לכל כח כלי מיוחד כמו השכל במוח ומדות בלב כו', מ\"מ מצד עצם הנפש אין התחלקות ביניהם כלל (כמו בעבודת ה' אנו רואים בהתפעלות עצמי' הנפש מתפעלים כל הכחות עליון [ותחתון] יחד כמו התפעלות הרצון והתפעלות השכל ומדות ומחשבה כו' הכל כא' ולא בסדר והדרגה מעליון לתחתון כלל (וכמו<sup data-n=\"1989\">85</sup> העיגול שיסובב כא' בכל חלקיו מראשו לסופו (והוא כמו טבע נפש הבהמית שכל כחות שלה <span data-k=\"pg\">סא</span> ּ כא', ובעבודת ה' הוא מה שמתפעל הנפש עצמה שכלול בה הכל כא' רצון ושכל עד סוף מעשה כא'). אבל בבחי' התיקון הוא להיפך ממש, והוא מה שיש סדר והדרגה בכל כחות הנפש שבאים בהתלבשות באבר[י] הגוף בכל אבר כח מיוחד בפ\"ע וכמו כח השכל במוח והמדות בלב כו' (וכמשי\"ת), והוא הנק' בחי' התחלקות שבא בציור פרצוף אדם במוח חב\"ד ובלב חג\"ת כו' (וכמו בעבודת ה' בא בסדר מעליון לתחתון תחילה מתפעל ברצון שלמעלה מן הטעם ואח\"כ בא להתפעלות השכל וטעם לרצון ומשם להתפעלות המדות אוי\"ר בלב כו')<sup data-n=\"1990\">86</sup> עד סוף מעשה בבחי' הרגל<sup data-n=\"1991\">87</sup> ), ונמצא שעיקר כללות ההפרש הוא שבחי' התהו הוא בבחי' ההתכללות ובחי' התיקון הוא בבחי' ההתחלקות בציור פרצוף אדם כו' וד\"ל.\n<b>והנה</b> יש לכאורה סתירה גדולה לזה והוא מה שאנו מוצאים בס' הקבלה ובזהר היפך זה ממש והוא בענין עיגולים ויושר<sup data-n=\"1992\">88</sup> שהעיגולים דבחי' התהו הן בבחי' ההתחלקות דוקא והוא כמו העיגולים זה תחת זה כאשר יהי' האופן<sup data-n=\"1993\">89</sup> בתוך האופן כו' שאין א' נוגע לחבירו כו', אלא כל עילה סובב ומקיף לעילתו כעיגול הכתר סובב ומקיף לעיגול החכ' שבתוכו ולעולם לא נוגע עיגול החכ' לעיגול הכתר כו' וכידוע בענין ז' מלכים דתהו דכתיב וימלוך וימת<sup data-n=\"1994\">90</sup> כו' שאין מל' נוגע[ת] לחברתה<sup data-n=\"1995\">91</sup> להיות[ן] בחי' ענפין מתפרדין<sup data-n=\"1996\">92</sup> זת\"ז<sup data-n=\"1997\">93</sup> דוקא שזהו בחי' ההתחלקות דוקא היפך ההתכללו', ובבחי' התיקון דפרצוף אדם הוא דוקא בבחי' ההתכללות דראש ורגל כו' עד שלא ימצא מי הראש ומי הסוף משום דנעוץ תחב\"ס וסוב\"ת<sup data-n=\"1998\">94</sup> כו' כי הסוף משפיע לראש שיש בתחתון יתרון מעלה מה שאין בעליון עד שיקבל ממנו הראש כו', משא\"כ בבחי' התהו שהן בבחי' ההתחלקות זת\"ז דוקא כנ\"ל",[["1988","84","<b>שעיקר ההפרש בין התהו והתיקון</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשמח. מאמרים שנסמנו בריש המאמר. סה\"מ תרמ\"ג ע' קמז."],["1989","85","<b>כלל (וכמו</b>: אה: כלל) וכמו."],["1990","86","<b>כו')</b>: ח: כו'."],["1991","87","<b>הרגל</b>: אהו: תיקון. ב: מחק תיבת תיקון וכתב רגל."],["1992","88","<b>בענין עיגולים ויושר</b>: ראה גם ביאוה\"ז עקב קכ, א. סידור שחרית לשבת קעט, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ס\"ע תרכ ואילך. פיה\"מ ח, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670411\" data-slug=\"torat-chaim\" data-id=\"2300670411\">תו\"ח (נח) נג, ב</a>. (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680412\" data-slug=\"torat-chaim\" data-id=\"2300680412\">תולדות) קנז, ב</a>. (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680063\" data-slug=\"torat-chaim\" data-id=\"2300680063\">וישלח) קפח, ג</a>. סה\"מ תרמ\"ח ע' ריג. תרמ\"ט ע' רלט. עת\"ר ע' קסז. הנסמן בהערות הבאות."],["1993","89","<b>כאשר יהי' האופן</b>: יחזקאל א, טז. י, י."],["1994","90","<b>ז' מלכים. . וימלוך וימת</b>: וישלח לו, לב ואילך. נסמן לעיל מג, ג."],["1995","91","<b>שאין מל' נוגע[ת] לחברתה </b>[א: בחברתה]: ברכות מח, ב."],["1996","92","<b>ענפין מתפרדין</b>: זהר ח\"ש קכג, א."],["1997","93","<b>זת\"ז</b>: ראה ע\"ח שער הכללים פ\"א. (שער התיקון) ש\"י, פ\"ה. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשיט ואילך. ס\"ע תשסב ואילך. מאמרי אדה\"א קונטרסים ע' תז. וש\"נ."],["1998","94","<b>דנעוץ תחב\"ס וסוב\"ת</b>: ראה ספר יצירה פ\"א, מ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680326\" data-slug=\"torat-chaim\" data-id=\"2300680326\">תו\"ח ויגש רלה, ב</a>: כלל הידוע."]]],[2300540294,"עד שלא יתכן לומר נעוץ תחב\"ס כו' אדרבה כאו\"א בפ\"ע הוא ואין לו שייכות וחיבור עם חבירו כלל עד שאין לעליון ותחתון חיבור כלל וכלל כו' ולא ימצא בו כלל שהעליון יקבל מהתחתון כו' כמו שנמצא בבחי' התיקון דפרצוף אדם מאחר ששם הוא זת\"ז דוקא כנ\"ל, וא\"כ הרי יש כאן סתירה גדולה להיפך מכל הנ\"ל דבחי' התהו הוא בבחי' ההתכללות (כעיגול הסובב יחד שנעשה מתחתון עליון כו' כנ\"ל) ובתיקון הוא בחי' ההתחלקות בסדר והדרגה כנ\"ל, ומלשון המקובלים משמע להיפך ממש כנ\"ל וד\"ל.\n<b>והנה</b><sup data-n=\"1999\">95</sup> תחילה יש להבין ביאור לענין השני דיעות הנ\"ל, היינו דעת המקובלים דבחי' התהו הוא בבחי' ההתחלקות זת\"ז ובתיקון הוא בבחי' ההתכללות כנ\"ל, וגם יובן דגם זה אמת דבחי' התהו הוא בבחי' ההתכללות דוקא ובתיקון הוא בבחי' ההתחלקות כו', דהנה באמת כל אחד ואחד מב' המדרגות דתהו ותיקון יש בו דבר והיפוכו ממש שהן א'<sup data-n=\"2000\">96</sup> ההתחלקות וההתכללות ושניהם אמת, והענין הוא עד\"מ בנפש האדם עצמה כמו שהיא טרם שיתפשטו ממנה כחות שלה הרי כולם כלולים כא' ממש מכח הרצון ותענוג עד כח המעשה שהוא בחי' ראש ורגל בעצם הנפש (כנ\"ל בענין התפעלות עצמיות הנפש ממש), וזהו כעיגול הסובב בבת אחת ונעשה עליון תחתון ותחתון עליון, כמו שאדם חושק בכל נפשו לבנות בנין כל רצונו הוא במעשה דוקא א\"כ הכל כא' ממש, <span data-k=\"pg\">124</span> ּ והתכללות זאת הוא יותר מהתכללות דתיקון שהוא בא מצד שהעליון מקבל מתחתון שיש לכל א' מציאה בפ\"ע עכ\"פ, אבל כאשר עיקר ההתפעלות הוא למעשה הבנין נכלל בזה הרצון והתענוג ושכל כו'. ואמנם כאשר בא בחי' התפשטות כחות הנפש מעצם הנפש הרי יש לכל א' מקום בפ\"ע ולחלק יצא ואין לו חיבור כלל וכלל עם חבירו וכ\"ש שלא יחובר עליון בתחתון וב' הפכים יחד, להיות שהתפשטות זאת באה בכל א' בבחי' הכתר שבה שהוא בחי' העצמיות דמדה זו כמו התפשטות כח הרצון שהוא עצם כח הרצון הנק' כתר שבכתר, אז א\"א שיבא הרצון לכלל טעם ושכל לרצון, אלא מובדל הוא מן הטעם ושכל לעולם, אע\"פ שיגיע ויבא לכלל טעם לרצון, א\"א שיגיע וישיג הטעם לעצם הרצון כעיגול שבתוך העיגול כנ\"ל. וכן התפעלות השכל בעצם דחו\"ב מובדל הוא לעולם מן המדות ואע\"פ שיתפעל במדות לא ישיגו לעצם השכל כו', וכן מו\"ד עד כח המעשה שהוא אחרון יותר והוא הנק' זת\"ז דוקא כנ\"ל, וא\"א שיהי' התחתון שהוא כח המעשה או הדבור העליון ולא העליון<sup data-n=\"2001\">*97</sup> שהוא הרצון תחתון כו' וכ\"ש שא\"א שיחוברו ב' הפכים כחו\"ג שברצון או חכ' ומדות כמו אש ומים ממש לפי שכל בחי'",[["1999","95","<b>והנה</b>: ד: נרשם כאן פ\"ג."],["2000","96","<b>שהן א'</b>: ניתוסף ע\"פ או. זט: שאין (!) א'."],["2001","*97","<b>ולא העליון</b>: ניתוסף ע\"פ: א."]]],[2300540322,"התהו היינו בבחי' הכתרים של כל מדה שהוא העצמיות שלה, ואיך אפשר עצם הרחמנות והחסד עם עצם האכזריות במדות וכן בחו\"ג העצמיי' שברצון וחכ' כו' וכ\"ז נק' בחי' התחלקות ושניהם אמת.\n[ג] <b>ומעתה</b> יש להבין גם בבחי' התיקון שיש בו ג\"כ דבר והיפוכו שהוא בחי' ההתחלקות וההתכללות כנ\"ל ושניהם אמת, דהנה אנו רואים בציור חלקי האברים כולם שבאדם מראש לרגל פנימיות וחיצוניות שיש לכל אבר כח מיוחד לפי אופן מזגו וטבעו ופעולתו שאין זה באבר זולתו כלל לא מיני' ולא מקצתי', כמו כח הראי' בעין מיוחד הוא לכלי העין לפעול פעולתו בראי' ואין בו התכללות מאבר זולתו כמו חוש השמיעה שבאוזן כלל, וכן בכלי האזן מיוחד השמיעה ואין בו מחוש הראי' כלל וכלל, וכן ביד ורגל אין ביד מפעולת הילוך הרגל ואין ברגל מפעולת המלאכה והמעשה שביד כי כל אחד מובדל ומיוחד בפ\"ע דוקא ואין להם חיבור והתכללות כלל (וכמו\"כ במדות אהוי\"ר אין באהבה מבחי' יראה כלל ואין ביראה מן האהבה כלל אע\"פ ששניהם משכנם בלב, וכן החסד והדין ב' הפכים אין מרחמין בדין<sup data-n=\"2002\">97</sup> ואין דין בחסד וכן בחו\"ג שבשכל ורצון<sup data-n=\"2003\">98</sup> כו' ועכ\"ז מתכללים יחד כמשי\"ת בהתכללות שבאברים), וכן בכח המעשה עצמה שבידים יש פרטי חלוקים כמו במלאכ[ת] הכתיבה שהוא באצבעות היד, אבל כלי קבלה הוא בפס כף היד שנק' חפניו שיש ביד ג' פרקין חב\"ד באצבעות כמו הרמז שבאצבע כו', וכן יש ג' פרקין ברגל<sup data-n=\"2004\">99</sup> לכח מעשה ההילוך ירך ושוק ורגל כו', כי כל אלה חלקים מפורדים ומיוחדים כל א' בפ\"ע, וכ\"ש באברים הפנימים כמו כליות וקיבה וריאה ולב כו' כל א' פעולתו מיוחדת בפ\"ע דוקא עד המוחין שבראש ומדות שבלב וכל פרטיהן לכאו\"א יש כלי מיוחד, וכמו\"כ בכל פרטי רמ\"ח אברים המה מפורדים ומחולקים זה מזה שאין בזה מה שבזה כלל ואינם שייכים זע\"ז כלל, וכ\"ז בא מצד חילוקי אור השפע והחיות רוחני מן הנפש שנק' כחות <span data-k=\"pg\">סב</span> ּ רוחני' כשבאים ומתפשטים בכלי האברים הן הנה בבחי' פירוד והתחלקות זה מזה, כמו כח הראי' הרוחני' המתפשט מן הנפש בא בחלק ומדריגה מיוחדת בכלי העין בלתי משתתפת ומתחברת כלל עם כח השני שהוא כח השמיעה הרוחני' הנשפע בכלי האוזן אלא כאו\"א דבר בפ\"ע, [וכך בבחי'<sup data-n=\"2005\">100</sup> המעשה שביד ורגל בא מן הנפש בחילוק ופירוד זמ\"ז כל א' בפ\"ע כח פעולת היד בפ\"ע] וכח פעולת הרגל דבר בפ\"ע בלתי משתתפי' יחד כלל, וכך גם בפרטי חלוקי כחות שיש בכל אבר כו'. ובכלל הרי כל רמ\"ח כחות של רמ\"ח אברים הבאים בהשתלשלו' מרוחני' לחיות גשמי באברי הגוף הרי הן באים מפורדים זה מזה וזה תחת זה ממש בלי חיבור<sup data-n=\"2006\">101</sup> כלל (כמו כח הראי' נמשכת בפ\"ע וכח היד בפ\"ע והן זה תחת זה ואין להם שייכות זע\"ז כלל, וכן הוא הסתעפו' כל פרטי",[["2002","97","<b>אין מרחמין בדין</b>: כתובות פד, א (במשנה)."],["2003","98","<b>ורצון</b>: ניתוסף ע\"פ אהו."],["2004","99","<b>שיש ביד ג' פרקין. . ברגל</b>: ראה זהר ויחי רמא, א. לעיל כט, ג. לקמן פ' בשלח קלט, ג. קמה, ב. מאמרי אדה\"א נ\"ך ע' שכג וע' שמו. שה\"א פז, א ובהערה 16."],["2005","100","<b>וכך בבחי'</b>: אבהו: דוקא וכך בכח."],["2006","101","<b>חיבור</b>: תוקן ע\"פ זט. ובתו\"ח: חילוק."]]],[2300540347,"הכחות בכל סדר ציור קומת אדם הכל בא בפירוד כל א' בפ\"ע והן באים בבחי' זת\"ז דוקא), דהיינו בסדר הסתעפות מעילה לעילה שלמטה הימנו כענפי האילן כו' או כשלשלת כו' שהרי מן המוח שבראש נמשך ומסתעף כח המעשה כתיבה ביד לכתוב שכל שבמוח או לעשות חסד ביד כפי שכל המחייב במוח רק שהחסד שבמעשה היד יש לו כח מיוחד בפ\"ע דוקא כנ\"ל, וכן במוח אין מפעולת היד כלל כנ\"ל, ועכ\"ז הולך ומשתלשל מעליון לתחתון עד צפורן הרגל שאע\"פ שכל אחד מיוחד ונבדל בפ\"ע, וזהו פלא דלכאורה זהו דבר והיפוכו.\n<b>אלא</b> צ\"ל דהסתעפות זאת אינה באה מצד עצמן שהרי מובדלים הן בעצם בלי חיבור כלל וכלל וכנ\"ל בבחי' התהו במדרגה הב' בבחי' התפשטות הכחות מן עצם הנפש שהן זה תחת זה בלתי חיבור כלל לעולם כו', וא\"כ גם בהיותן באי' בגוף למה משונה טבעם להשפיע זה לזה בין מן הרצון לשכל שבמוח ובין מן המוח ללב ויד כו'. אך הענין הוא דאין זה רק מצד התלבשות כחות הנפש בכלי האברים ששוכן כל כח וכח כאו\"א במקום המיוחד לו המזוג לפי טבעו דוקא, אע\"פ שזהו העושה פירוד והתחלקות כל פעולת אבר מזולתו כנ\"ל, אבל מ\"מ אנו רואים שמזה דוקא יבא בחי' ההתכללו' מכל הכחות יחד עד שיעשה<sup data-n=\"2007\">*102</sup> כח הרגל בראש וכח הראש ברגל מבלי שימצא ראש וסוף כלל, והענין הוא לפי שגם שכחות הנפש מצד עצמן יצאו מפורדים זה תחת זה כנ\"ל, אבל האברים מצד עצמן יש בהן בחי' התכללות שכלולים זה מזה דייקא ויש להם שייכות וחיבור זה עם זה דוקא, שהרי ידוע שירפא כאב הראש ע\"י הקזת דם ביד, וכה\"ג בכל רפואות שירפא אבר אחד ויתקן כל הגוף, כי הילוך הדמים סובב באברים עי\"ז יש חיבור וקישור כל האברים זע\"ז, ולבד זה הנה יש חיבור וקשר לכל קומת אדם מראש לרגל יחד והוא מה שמרגיש במחשבה שבמוח כאב צפורן הרגל כו' והוא כמו שמרגיש א\"ע הכל כאחד בלי חילוק מדרגות<sup data-n=\"2008\">102</sup> כלל כו', ואע\"פ שהמח' היותר רוחני' וצפורן הרגל גשמיות ביותר הרי יש להם חיבור והתכללות זה עם זה (ע\"י גידים ועורקים המחברים כו'), וממה שמרגיש בכח המח' שבמוח כל האברים יחד, הגם שהוא בבחי' מקיף שסובל הכל כא' לפי שהחכ' שבמוח כח כללי שכוללם יחד להיותו כח ראשון כידוע, מ\"מ מצד בחי' ההתחלקות של כל כחות הנפש בכל האברים כח<sup data-n=\"2009\">103</sup> בפ\"ע עד שגם מוח החכ' כח מיוחד בפ\"ע לא הי' ראוי <span data-k=\"pg\">126</span> ּ שירגיש במוח כל האברים מאחר שאין לחכמה שייכות לכל מה שלמטה הימנה כו', אלא צ\"ל עכ\"פ שיש בחי' התכללות ממש במוח שבראש מכל מזגי כחות האברים דהיינו שיש במוח גם בחי' [כח] ההילוך שברגל, ויש מציאות כח המח' שבראש באבר הרגל, ועד\"ז יש התכללות בעין ואזן זה עם זה הגם שהן כחות נבדלים זה מזה וכן ביד ורגל יש מכח העין והאזן אע\"פ שאין זה בגילוי כלל,",[["2007","*102","<b>שיעשה</b>: זט: שיש."],["2008","102","<b>שמרגיש א\"ע. . בלי חילוק מדרגות</b>: ראה גם לקמן פ' בשלח קסו, ג. וש\"נ."],["2009","103","<b>האברים כח</b>: אבהו: אבר."]]],[2300540370,"וראי' מן הרפואה וההרגשה כנ\"ל וד\"ל. ונמצא מובן מזה שבחי' התכללות זאת אינו רק מצד האברים עצמן הוא שעושה בחי' התכללות בכחות המתפשטות מן הנפש להיות כלולים זה מזה כנ\"ל היפך ירידתן מן הנפש שבאו בבחי' פירוד והתחלקות כנ\"ל (וראי' לזה שהרי טרם שבאו בכלים ואברים הרי מתפשטים מעצם הנפש בפירוד גדול זה מזה עד שא\"א להתחבר לעולם ומיד שבאו הכחות באברים יכולים להתחבר גם ב' הפכים דחו\"ג במוח ולב ועליון ותחתון כו', וזהו מצד כלי המוח וכלי הלב דוקא שיכיל ב' הפכים דחו\"ג וכלי המוח יכיל חו\"ג דשכל ורצון כו', משא\"כ בלא כלים הרי הן זה תחת זה בלתי חיבור לעולם כנ\"ל, וכמו\"כ בראש וסוף דרצון ומעשה הרי כח המעשה העיגול האחרון שבסוף והרצון הוא עיגול העליון יותר כנ\"ל, ובהיותן בכלים הרי הילוך הרגל בא עם הרצון שבמוח כא' ממש מבלי שימצא ראש וסוף, דהיינו שיש ראש בסוף וסוף בראש כו' שזה מקבל מזה משום דנעוץ תחב\"ס וסוב\"ת כו' וזהו מצד בחי' הכלים דוקא, ונמצא יש בבחי' התיקון בבחי' אדם בחי' התחלקו' ובחי' התכללות דבר והיפוכו ממש ושניהם אמת דההתחלקות מצד האורות וההתכללות מצד הכלים דוקא וד\"ל).\n[ד] <b>אך</b> הנה זה גופא י\"ל מאין יבא בחי' ההתכללות מצד בחי' הכלים דוקא שהן האברים, שהרי הפי' הפשוט דנעוץ תחב\"ס כו' הוא בבחי' האורות מצד עצמן דוקא. ועוד י\"ל דלכאורה עיקר בחי' התיקון הוא שיתיישב האור בכלי דוקא והוא כשיהי' האור במיעוט וריבוי הכלי כו', וזה א\"א כ\"א כאשר יש מזיגת והתכללות באורות מצד עצמן דוקא כשיהי' מורכב דבר מהיפוכו כאש ומים שא\"א שיתחברו, אבל בחי' הרכבה שלהם יכול להתחבר והוא מה שמורכב אש ממים ומים מאש כמ\"ש בס\"י טרף אש ומים<sup data-n=\"2010\">104</sup> ובללן זה בזה והוא מה שהוציא אש ממים ומים מאש<sup data-n=\"2011\">105</sup> כו'. וכך בחו\"ג אף שעצם מהותן א\"א להתחבר, אבל בבחי' התפשטו' הרכבה שלהם יחוברו, כמו חסד שבגבורה עם גבו' שבחסד כידוע במשל מרקחת דדבש וצנון<sup data-n=\"2012\">106</sup> כו', ואין מציאת הרכבה בכל מדה רק בבחי' התפשטות שלה שהוא ט\"ס דכל מדה מחכ' שבה ולמטה, אבל בבחי' כתר שבה שהוא העצמיות א\"א להרכיבה בהיפוכה כאש ומים כו'. וזהו עיקר ההפרש בין התהו והתיקון וכנ\"ל דבחי' התהו הוא בבחי' הכתרים כו' שאין בהם התכללות כלל אלא זה תחת זה, אבל בבחי' התפשטות שלהם כמו המשכת הכחות באברים שם יוכל להיות התכללות דבר והיפוכו כמו חו\"ג שבמוח ולב כו' כנ\"ל וגם יוכל להיות עליון לתחתון ותחתון לעליון לפי שמזיגה והרכבה דעליון יש בו מבחי' התחתון עד שמקבל הימנו כמו",[["2010","104","<b>כמ\"ש בס\"י טרף אש ומים</b>: כ\"ה בכ\"מ. ראה לקמן פ' בשלח ריב, רע\"ג. רמד, ב. מאמרי אדה\"א דברים ח\"ג ע' א'כג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670368\" data-slug=\"torat-chaim\" data-id=\"2300670368\">תו\"ח בראשית יג, א</a> ובהנסמן בהערה 6 שם."],["2011","105","<b>שהוציא אש ממים ומים מאש</b>: מובא בכ\"מ בשם ס\"י — ראה לקמן פ' בשלח רלח, ג. מאמרי אדה\"א במדבר ח\"ד ע' א'תלא. וש\"נ. דברים ח\"ד ע' א'תלא. וש\"נ. הנחות תקע\"ז ע' קפו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670368\" data-slug=\"torat-chaim\" data-id=\"2300670368\">תו\"ח בראשית יג, א</a> הערה 2."],["2012","106","<b>במשל מרקחת דדבש וצנון</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ע. תקס\"ג ח\"ב ע' תשדמ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670368\" data-slug=\"torat-chaim\" data-id=\"2300670368\">תו\"ח שם יג, א</a> ובהנסמן בהערה 3 שם. שעה\"י קכה, א ובהערה 18."]]],[2300540391,"שיש כח ההילוך דרגל בראש, ועכ\"ז א\"א לילך בראש כ\"א ברגל <span data-k=\"pg\">סג</span> ּ הרי הרגל מוליך לראש, וכן יש כח הראש ברגל לכל אשר יחפוץ ילך. וזהו ענין נעוץ תחב\"ס וסוב\"ת מבלי שימצא ראש וסוף שזה מקבל מזה וע\"י אמצעות חיבור כולם יחד נק' אדם דוקא, הגם שעליון למעלה והולך ממנו כסדר והדרגה זה תחת זה עד למטה מ\"מ קשורים כולם כא' כו' ואין לא' שלימות כלל בלא זולתו, וזהו עיקר בחי' ההתכללות דתיקון (והוא למעלה מבחי' התכללות הכחות בעצמות הנפש כנ\"ל שאין זה רק שכלולים כא' בלי ניכר כאו\"א במציאות בפ\"ע, אבל ההתכללות זו שבכחות הנפש באברים כאו\"א מקבל מזולתו וכן כולם הם מציאה אחת ממש שנק' אדם, וראי' שגם לדבר אחד פרטי כמו להילוך ברגל ישתתפו כל הכחות יחד מן הרצון ומח' ומדות ואברים החיצונים כולם כאחד, וכן לכל דבר פעולת אבר פנימי וחיצוני יש בזה התכללות מהכל כי זה עוזר לזה כמשל ב' בנ\"א שמשתתפים יחד להגביה משא א' כו', וזהו שא' במרכבה דנושאות הכסא דכלילן דא בדא<sup data-n=\"2013\">107</sup> כו', שאל\"כ לא היו מתחברים יחד כ\"כ כו'.\n<b>וכך</b> הוא באדם בעבודת ה' בכל פרט כמו באהבה יש בזה כללות הכל, הרצון ושכל עד גם המעשה שיסתעף מזה כו' וע\"כ גם ב' הפכים כאוי\"ר מתכללים יחד לפי שמורכב האהבה מן היראה והיראה מן האהבה כהרכבה דאש ומים פני ארי' ופני שור<sup data-n=\"2014\">108</sup> כו'. וכך בכללות קומה דכנס\"י מבחי' ראשי אלפי כו' עד נשמות דעקביים בין כולם יחד נק' אדם<sup data-n=\"2015\">109</sup> א', וע\"כ צריך אדם לשתף נפשי'<sup data-n=\"2016\">110</sup> בהדי צבורא קודם התפלה כו', כי אין שלימות לראש בלי סוף שזה מקבל מזה כו', והוא עיקר ענין מצות ואהבת לרעך כמוך שזהו כל התומ\"צ ואידך פירושא הוא<sup data-n=\"2017\">111</sup>, לפי שכל התומ\"צ ברמ\"ח אברים דמלכא הוא רק בבחי' ההתכללות בציור אדם דוקא וד\"ל (וזהו ג\"כ הטעם שבצדקה תכונני וכתיב אני בצדק<sup data-n=\"2018\">112</sup> אחזה פניך בבחי' פני' דמוחין, לפי שהראש מקבל מן הסוף כנ\"ל וכמשי\"ת בסמוך וד\"ל).\n<b>ונמצא</b> מובן שב' אופנים דהתכללות והתחלקות, דבחי' התהו ההתכללות הוא בעצם הנפש וכל א' אינו נשלם ע\"י זולתו רק שכלולים כאחד וההתחלקות [הוא] ההתפשטות עצם מהותן שהוא בחי' הכתר דכל מדה שנק' זה תחת זה כנ\"ל והוא ריבוי האור ומיעוט הכלי כו'. אבל בבחי' התיקון נהפוך הוא שההתחלקות תחלה ואח\"כ ההתכללו' כנ\"ל, אך ההתחלקות הגם שבא בסדר מעליון לתחתון זה תחת זה כאו\"א בפ\"ע כנ\"ל, אבל אין התפשטות זו מבחי' עצם מהות [כל] כח כמו שהוא בעצם",[["2013","107","<b>שא' במרכבה. . דכלילן דא בדא</b>: ראה זהר תרומה קעא, א. שע\"ת יג, א. מאמרי אדה\"א דברים ח\"ג ע' תשמו."],["2014","108","<b>פני ארי' ופני שור</b>: יחזקאל א, י."],["2015","109","<b>קומה דכנס\"י. . נק' אדם</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תערה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670065\" data-slug=\"torat-chaim\" data-id=\"2300670065\">תו\"ח לך צג, ד</a> ובהנסמן בהערה 36 שם. לעיל יג, ג. לקמן פ' וארא עח, ג. פד, ד. תשא שפב, ג. ת, ג."],["2016","110","<b>צריך אדם לשתף נפשי'</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תשמט ובהנסמן שם. נ\"ך ע' צו בשם רז\"ל."],["2017","111","<b>ואהבת לרעך. . ואידך פירושא הוא</b>: קדושים יט, יח. שבת לא, א."],["2018","112","<b>שבצדקה תכונני. . אני בצדק</b>: ישעי' נד, יד. תהלים יז, טו."]]],[2300540411,"הנפש שא\"כ לא הי' אפשר להיות בהן התכללו' כלל ולא חיבור מעליון לתחתון, אלא התפשטות זאת הוא רק מבחי' ט\"ס דכל מדה כמו חכמה שבחסד ואהבה עד מל' שבה וכן במדת הגבורה. וכך הוא גם בחו\"ב כו' שזהו בחי' הרכבה שבכל מדה ולא עצם פשיטות ע\"כ יוכלו ב' הפכים להתחבר וכנ\"ל (כמ\"ש במ\"א בענין לעולם יהא אדם רך כקנה<sup data-n=\"2019\">113</sup> כו'). וז\"ש דנעוץ תחב\"ס וסוב\"ת באורות מצד עצמן, וע\"כ יכול האור להתיישב בכלי ולהתקיים ויוכל לסבול היפוכו שיש מקום להיפוכו כי כלול הוא ממנו, משא\"כ בהתחלקו' שבבחי'<sup data-n=\"2020\">*114</sup> <span data-k=\"pg\">128</span> ּ מצד עצם מהותן טרם שיתפשטו באברים כנ\"ל. אך מזה עצמו אנו רואים שעיקר הסיבה להתכללות האורות והכחות כ\"כ שהוא [בהיותם] מלובשים באברים דוקא ולא קודם לכן שזה בא מצד כלי האברים דוקא, דהיינו שמצד מהות ועצם מזיגה והרכבה דאברים שכלולים זה מזה מראש לסוף אע\"פ שכל א' פועל פעולתו מיוחדת כטבעו ומזגו כנ\"ל, מחמת זה דוקא כאשר האברים מלבישים לכחות הרוחני' שבהם, יבא בהם בחי' ההתכללות זה בזה במזיגה והרכבה דבר והיפוכו ראש ורגל יחד כו' באופן שהעליון מקבל מהתחתון ודבר מהיפוכו עד שאין לא' שלימות בלא זה, דהתכללות כזו לא הי' גם בכחות הכלולים ממש בעצם הנפש כנ\"ל, וצ\"ל שיש בטבע מהות האברים שורש עליון שיוכל לעשות בחי' התכללות כזאת. והענין הוא כמ\"ש בע\"ח בשרש התהוות הכלים למעלה משורש האורות<sup data-n=\"2021\">114</sup> והוא בבחי' מקיפים עליונים כו' (שזהו הוראת ציור הכלי שסובב ומקיף לדבר שבתוכו ויש בו מדה בהקפה זו כפי ערך דבר המונח בו כו' כדוגמא שהמקיף סובב לפנימי<sup data-n=\"2022\">115</sup> מלמעלה למטה כמ\"ש במ\"א), והוא הטעם שכלול דבר והיפוכו לפי שידוע דהמשכות המקיפי' הוא בבחי' מטי ולא<sup data-n=\"2023\">116</sup> מטי<sup data-n=\"2024\">117</sup> כענין ורוח אלקים מרחפת נוגע ואינו נוגע<sup data-n=\"2025\">118</sup> כו' כמשל הברקת כח המשכיל לבא לידי גילוי שכל שבלתי מושג בעלי' והסתלקות [ו]חוזר ומאיר מעט וחוזר ומסתלק כו' שזהו מצד הפלאת הערך דמקיף כו' כידוע, ומזה יבא גם בבחי' הכלים ההתכללות מדבר והיפוכו כמו המקיפי' שכלול בו דבר והיפוכו כו' (ולא כמו התכללות הכחות בעצמות הנפש שכל א' יש במציאות בפ\"ע עכ\"פ, אלא כמו עיגול השמים שאין בהם חלקים כלל אלא עצם אחד פשוט בשוה ומתגלגל כא' עד שהתחתון עליון ועליון תחתון ממש כו'. וע\"כ גם בבחי' כלים שהן האברים נעשה בהן ההתכללות כזאת אע\"פ שיש לכל אחד מציאות בפ\"ע שהרי הן כאלו הוא עצם אחד פשוט ממש כי עליון מקבל",[["2019","113","<b>לעולם יהא אדם רך כקנה</b>: תענית כ, סע\"א. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשמז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ובהנסמן שם בהערה 17."],["2020","*114","<b>שבבחי'</b>: אב: שבכחות."],["2021","114","<b>בע\"ח. . התהוות הכלים למעלה משורש האורות</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ע' יז. סידור ערב שבת קסו, א. הנסמן במאמרי אדה\"א שמות ח\"א ע' קכג־ נ\"ך ע' קלד־ <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670279\" data-slug=\"torat-chaim\" data-id=\"2300670279\">תו\"ח נח סז, ג</a> <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670305\" data-slug=\"torat-chaim\" data-id=\"2300670305\">הערה 9. ש\"א סח, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670596\" data-slug=\"torat-chaim\" data-id=\"2300670596\">ב. עח, ב</a> ובהנסמן במ\"מ להנ\"ל. לקמן מח, א. פ' בשלח רמד, ד. יתרו רנח, ב. תצוה שלג, א. ויקהל תלב, א."],["2022","115","<b>שהמקיף סובב לפנימי</b>: ראה גם סידור שער הלולב רסה, ב."],["2023","116","<b>דהמשכות המקיפי'. . מטי ולא מטי</b>: ראה גם לעיל מא, א. מאמרי אדה\"א שמות ח\"א ע' רפ. קונטרסים ע' תמב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380706\" data-slug=\"likkutei-torah\" data-id=\"4001380706\">לקו\"ת מסעי צה, ג</a>."],["2024","117","<b>מטי ולא מטי</b>: נסמן לעיל מא, א."],["2025","118","<b>ורוח אלקים מרחפת נוגע ואינו נוגע</b>: בראשית א, ב. ראה ב\"ר פ\"ב, ד. רש\"י האזינו לב, יא."]]],[2300540431,"מתחתון ותחתון מעליון מבלי שימצא ראש וסוף כנ\"ל. וזהו פי' אדם אדמה לעליון<sup data-n=\"2026\">119</sup> ממש שהוא למעלה מיחוד והתכללות ע\"ס דתהו כמו שהן כלולים בעצמות כו' אלא הוא כעליון ממש שהוא בחי' מקיף הכללי דעצמות דלאו מכל אינון [מדות] כלל אפי' בבחי' ההתכללות וכמ\"ש אנת חד<sup data-n=\"2027\">120</sup> ולא בחושבן י\"ס גם לא י\"ס הגנוזי' כו' אלא אח\"פ בתכלית, וזהו ג\"כ בבחי' אדם דאצי' שהוא עיקר בחי' התיקון מטעם בחי' ההתכללו' שבכלים דמזה נעשה ההתכללו' באורות כשבאים בכלים דוקא כנ\"ל וד\"ל.\n<b>ונמצא</b> מובן מכל הנ\"ל למעלה שיש ה' מדרגות מלמעלה למטה. א' עצמות א\"ס ב\"ה ממש שנק' עליון עילאה על עילאין סובב הכללי כו' שאינו בבחי' חלקים דע\"ס כלל אפי' בהעלם אלא אחדות פשוט בתכלית כנ\"ל. והב' ע\"ס הגנוזות בעצמות המאציל שהוא בבחי' ההתכללות כהתכללות כחות הנפש בעצם הנפש כנ\"ל. והג' ע\"ס דעיגולים דתהו שיוצא כל עגול בפ\"ע דוקא עיגול בתוך עיגול כו' כנ\"ל שהוא בחי' התפשטות עצם הספי' בחי' כתר של כל ספי' כו', כמו שהן בבחי' התחלקות גמור. והד' בחי' התפשטות אורות דתיקון כמו התפשטות כחות הנפש באברים כו' כנ\"ל שבאים בבחי' התחלקות זה תחת זה <span data-k=\"pg\">סד</span> ּ בסדר ציור האדם. והה' בחי' ההתכללות שבאורות דתיקון ע\"י בחי' הכלים דוקא זהו עיקר בחי' אדם אדמה לעליון ממש שהוא בחי' עצמות א\"ס שזהו שם מ\"ה מלגאו<sup data-n=\"2028\">121</sup> כו' (ונמצא דהתחלקות דתהו א\"א לבא להתכללות, והתחלקות דתיקון בא דוקא לבחי' התכללות אמיתי מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> שאנו מוצאים כל ענין הנ\"ל בבחי' התיקון שהוא בחי' ההתכללות שמצד הכלים כנ\"ל גם בתו\"מ, לפי שהן בבחי' התיקון בציור אדם וכמ\"ש וזאת תורת האדם<sup data-n=\"2029\">122</sup> וכמ\"ש בזהר דרמ\"ח מ\"ע<sup data-n=\"2030\">123</sup> הן רמ\"ח אברים דמלכא כו' (שהן ט\"ס דז\"א וע\"י ה\"ח<sup data-n=\"2031\">124</sup> המגדילים נעשה בג' כלים פנימי ואמצעי [ו]חיצון כו'). ואע\"פ שמצד בחי' האורות שהוא שם הוי' שבכל מצוה ומצוה כל א' מיוחד במדריגה בפ\"ע דוקא כמו מצות ת\"ת בחכמה שבראש וכן מצות תפילין בד' מוחין מקיפי' כו', ויש הרבה מצות שהן בבחי' יד ורגל כמו מצות החסד בחסד דרועא ימינא<sup data-n=\"2032\">125</sup> כו' ומצות צדקה ברגל<sup data-n=\"2033\">126</sup> כמו בצדקה תכונני ונק' מעשה הצדקה<sup data-n=\"2034\">127</sup>, מ\"מ כולם כלולים זע\"ז מבלי שימצא בהם ראש וסוף כלל משום דנעוץ תחב\"ס וסוב\"ת כמו באברי האדם",[["2026","119","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבודת הקדש ח\"א חלק היחוד פי\"ז. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a>."],["2027","120","<b>דלאו מכל אינון. . אנת חד</b>: ראה תקוני זהר בהקדמה יז, ב. א."],["2028","121","<b>שם מ\"ה מלגאו</b>: ראה תקו\"ז שם, א."],["2029","122","<b>וזאת תורת האדם</b>: שמואל-ב ז, יט. זהר (רע\"מ) משפטים קיז, ב. צו כט, ב. ראה מאמרי אדה\"א דברים ח\"ד ע' א'שכז. וש\"נ."],["2030","123","<b>וכמ\"ש בזהר דרמ\"ח מ\"ע</b>: ראה תקו\"ז ת\"ל (עד, סע\"א). סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["2031","124","<b>רמ\"ח. . ט\"ס דז\"א וע\"י ה\"ח</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"ו. שע\"ת מב, ב ובהנסמן לשם."],["2032","125","<b>בחסד דרועא ימינא</b>: תקו\"ז בהקדמה (יז, א)."],["2033","126","<b>צדקה ברגל</b>: ראה אגה\"ק סי\"ט. מאמרי אדה\"א דברים ח\"ד ע' א'שכז. וש\"נ. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670475\" data-slug=\"torat-chaim\" data-id=\"2300670475\">תו\"ח נח עב, ב</a> בהערה 16. לקמן פ' תצוה שמ, ד. ויקהל תלג, ג."],["2034","127","<b>מעשה הצדקה</b>: ישעי' לב, יז. ראה מאמרי אדה\"א דברים ח\"ג ע' א'סט. וש\"נ. נ\"ך ע' שכג."]]],[2300540451,"ממש שיש ברגל מה שאין בראש עד שהראש מקבל מן הרגל ע\"י ההילוך כנ\"ל. כך מצות ת\"ת ותפילין ושבת וכה\"ג מקבלים ממצות הצדקה שבבחי' הרגל שנק' מעשה הצדקה, וראי' ממ\"ש אני בצדק אחזה פניך שהן בחי' יחו\"ע שבמוחין דחו\"ב, וכן אמר צדקה תרומם גוי<sup data-n=\"2035\">128</sup> שירומם לבחי' המוחין שבראש כמ\"ש ויהי נועם ה' עלינו<sup data-n=\"2036\">129</sup> שהוא פנימי' ע\"י שבפנימי' ח\"ע כו' ע\"י שמעשה ידינו כוננהו כו' (כמ\"ש במ\"א בענין עטרת תפארת שיבה<sup data-n=\"2037\">130</sup> בחי' עטרת דכתר דח\"ס דזקן כו' בדרך צדקה דוקא תמצא, וזהו וילבש צדקה כו' וכובע ישועה בראשו<sup data-n=\"2038\">131</sup> כו', וישראל אין נגאלין אלא בזכות הצדקה<sup data-n=\"2039\">132</sup> כידוע). וראי' גמורה לזה ממה שמצינו שנדחה גם המצוה העליונה ביותר מפני המצוה הנמוכה ביותר כמצות צדקה שהוא בבחי' מעשה דבחי' נה\"י כו' כמו שאמר בזהר בעובדא דר\"י ור' יצחק<sup data-n=\"2040\">133</sup> שהבין הינוקא בריחא דלבושייהו שלא קראו ק\"ש מפני שעסקו במצות הכנסת כלה כו'. הרי נדחה מצות ק\"ש שהיא בבחי' היחו\"ע דבחי' המוחי' שבראש מפני מצות הצדקה דהכנסת כלה, וכן העוסקים במת מצוה<sup data-n=\"2041\">134</sup> פטורים מן הק\"ש כו', וכן יכול להיות כמה מצות נמוכות שהן בבחי' רגל שיודחה מפניהם מצות העליונה שהן בבחי' ראש (כמו פיקוח נפש שדוחה שבת אפי' נפש רשע כמאמר חלל עליו שבת א'<sup data-n=\"2042\">135</sup> כו'), וכמו מצות מילה שדוחה שבת, וכן מצות הקרבנות דוחה שבת, וכמו מילה דוחה צרעת<sup data-n=\"2043\">136</sup> הרי עשה דוחה ל\"ת, וכן מצות עשה דתכלת בציצית דוחה ל\"ת דשעטנז<sup data-n=\"2044\">137</sup> כו' וכה\"ג רבים שמצוה אחת נדחה מפני אחרת שגדולה הימנה כו'. וכ\"ז מפני שאין במצות שהן בציור אדם בבחי' רמ\"ח אברים ענין ראש וסוף כלל מטעם הנ\"ל בבחי' התיקון דבחי' אדם כו' שהוא בבחי' הכלים דוקא מצד שרשן למעלה משורש האורות כנ\"ל, וז\"ש כי נר מצוה עי\"ז ותורה אור<sup data-n=\"2045\">138</sup> כו' וכמ\"ש במ\"א וד\"ל.\n[ה] <b>ומזה</b> יובן [ג\"כ] בכללות נשמות ישראל שהן בציור קומת אדם מוחין חב\"ד ראשי אלפי כו' עד בחי' נה\"י כידוע, <span data-k=\"pg\">130</span> ּ שיכול להיות שאותן שאין בהם רק בחי' המעשה דצדקה לבד תהי' שקול הרבה יותר מבחי' הראש ומוחין שבישראל שהן תורה ותפלה ומע\"ט דצ\"ג כו' אף שהם אנשים פשוטים וקלים בשארי המצות וכידוע בכמה מקומות<sup data-n=\"2046\">139</sup> בתלמוד ובזהר (או גם איזה התפעלות אלקי' פשוטה באמונה חזקה שבנפש השפילה ביותר שנשמתו מעשי' דעשי' יכול לעלות",[["2035","128","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["2036","129","<b>ויהי נועם ה' עלינו</b>: תהלים צ, יז."],["2037","130","<b>עטרת תפארת שיבה</b>: משלי טז, לא. ראה שערי אורה שער החנוכה ע' יב ואילך."],["2038","131","<b>וילבש צדקה. . בראשו</b>: ישעי' נט, יז."],["2039","132","<b>וישראל אין נגאלין אלא בזכות הצדקה</b>: ראה אגה\"ק ס\"ד. ס\"ט. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתמח."],["2040","133","<b>בעובדא דר\"י ור' יצחק </b>[אבה: דר\"י ור\"י. ח: דר' יהודה ור' יצחק]: זהר (ינוקא) בלק קפו, א [ושם: ר' יצחק ור' יהודה — בהנחת כ\"ק אדה\"א כאן (בבוך 2076): דרבי יהודה ור\"י. ראה מאמרי אדה\"א שמות ח\"א ע' דש. דברים ח\"ג ע' תשמט. לקמן פ' תצוה שלה, ג (תוקן ע\"פ גוכתי\"ק) ר\"י ור\"י. ועפ\"ז צריך לתקן במאמרי אדה\"א דברים שם]. ראה מאמרי אדה\"א דברים שם. וש\"נ."],["2041","134","<b>העוסקים במת מצוה</b>: ראה שו\"ע אדה\"ז רסע\"ב: נושאי המטה. . שיש למטה צורך בהם. . פטורים מק\"ש."],["2042","135","<b>חלל עליו שבת א'</b>: שבת קנא, ב."],["2043","136","<b>מילה. . הקרבנות. . מילה דוחה צרעת</b>: שבת קלב, א-ב."],["2044","137","<b>מצות עשה דתכלת. . ל\"ת דשעטנז</b>: יבמות ד, א."],["2045","138","<b>כי נר מצוה. . ותורה אור</b>: משלי ו, כג. ראה סידור שער החנוכה עדר, א."],["2046","139","<b>וכידוע בכמה מקומות</b>: ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370234\" data-slug=\"torah-or\" data-id=\"3901370234\">תו\"א כאן (נב, ב</a>) מובא הגהת הצ\"צ: ”ועד\"ז ארז\"ל [ב\"ב ט, ב] גדול העושה צדקה יותר ממשה רבינו וכמ\"ש במ\"א\"."]]],[2300540471,"למעלה יותר מהתפעלו' אה\"ר בתענוגי' שבצ\"ג כו' מטעם הנ\"ל דנעוץ תחב\"ס ויש ברגל מה שאין בראש עד שהראש מקבל מן הרגל כו'). וז\"ש והאיש משה עניו מאד<sup data-n=\"2047\">140</sup> מכל האדם כו', לפי שראה בנשמות שבעקביים דוקא שיש בהם יתרון מעלה מנשמתו שהוא בבחי' ראש וכמ\"ש ת\"ר אלף רגלי<sup data-n=\"2048\">141</sup> העם אשר אנכי בקרבו כו', שהגם שהי' הראש הכולל כל ס' ריבוא דיעות עד בחי' העקב שנק' רגלי, אדרבה היא הנותנת מפני שהי' בחי' המקור וראשית לכל פרטי הנשמות המסתעפים בבחי' ציור אדם דתיקון שלזה הי' מרגיש ומכיר לכולם יחד כהרגשת המוח לכל האברים עד צפורן הרגל, וכמ\"ש וירא ראשית לו<sup data-n=\"2049\">142</sup> שהי' משה בבחי' הראי'<sup data-n=\"2050\">143</sup> דח\"ע שבראש כו' שיכול להשיג ולראות בסקירה אחת כל האורות וכלים הפרטיים הנמצאי' בבחי' התיקון באדם<sup data-n=\"2051\">144</sup> התחתון שצופה ומביט בעצמו כללות גופו בב\"א כו' (דאיהו שם מ\"ה מלגאו דאיהו אורח כל האצי' כו'), ולכך כאשר הסתכל משה בכל פרטי הנשמות שבכל דור עד דור האחרון (שהוא עקבות דמשיחא בכללות ציור הקומה דכנס\"י כידוע) ראה א\"ע בתכלית השפלות ביותר מהכל, כי הוא דוקא ידע והכיר מה שיש בסוף מה שאין בראש משום דנעוץ תחב\"ס דוקא שהראש דוקא מקבל מן הסוף, דלפ\"ז ודאי יש בנשמות דעקביים בבחי' התיקון דאדם יתרון אור רב ומעלה ומדריגה יתירה שאין בנשמת משה כלל, ע\"כ הי' שפל ועניו באמת בנפשו מכל האדם אשר ע\"פ האדמה עד שכל היותר תחתון יותר עליון ממנו וכענין ונפשי כעפר לכל<sup data-n=\"2052\">145</sup> כו', וע\"כ לא הי' שפלות זאת רק במשה דוקא מטעם שהי' בחי' הראש דוקא ומטעם הנ\"ל כמ\"ש ת\"ר אלף אשר אנכי בקרבו כו' וד\"ל.\n[ו] <sup data-n=\"2053\">146</sup> <b>אך</b> עדיין יש להבין דהלא מבואר למעלה דשרש משה הי' ממ\"ע שהוא בחי' העיגולים דתהו משמיטה הראשונה שקדם לבחי' התיקון כו' ששם הוא בחי' ההתחלקות דע\"ס זה תחת זה כאו\"א בפ\"ע היפך ההתכללות, וכעיגול בתוך עיגול כו', והאיך הי' עניו מכל האדם כו' אחר שהוא עליון על הכל לא נעוץ תחב\"ס כלל שיהי' עניו מצד בחי' המעלה שבתחתון יותר מעליון שאין זה רק בבחי' אמצעות הכלים דתיקון דוקא כנ\"ל. וגם איך אמר אשר אנכי בקרבו כו'. אך הענין הוא כמבואר למעלה שגם בבחי' התהו יש ב' מדרגות א' בבחי' ההתכללות דע\"ס בעצמות ממש שנק' ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"2054\">147</sup> כלל כמו כחות הנפש הכלולים בעצם הנפש שאינם",[["2047","140","<b>והאיש משה עניו מאד</b>: בהעלותך יב, ג. ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תריח ואילך."],["2048","141","<b>ת\"ר אלף רגלי</b>: בהעלותך יא, כא."],["2049","142","<b>וירא ראשית לו</b>: ברכה לג, כא. ראה גם לקמן קב, ב. מאמרי אדה\"א שמות ח\"ב ע' שלד וע' תרלה. שה\"א מד, ב. עח, ב."],["2050","143","<b>בבחי' הראי'</b>: תוקן ע\"פ זט. ובתו\"ח: מבחי' היראה."],["2051","144","<b>באדם</b>: אב: כאדם."],["2052","145","<b>ונפשי כעפר לכל</b>: ברכות יז, א. סיום תפלת העמידה (אלקי נצור). ראה מאמרי אדה\"א דברים ח\"ג ע' תשנ."],["2053","146","<b>(ו)</b>: ד: (ה). פ\"ד בבוך זה הוא כמו בפנים."],["2054","147","<b>ע\"ס בלי מה בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."]]]]});
